import type { ScienceFact } from './types.js';

export const SCIENCE_FACTS: ScienceFact[] = [
  {"id": "matter-definition-g3", "domain": "MATTER", "topic": "what is matter", "grades": [3, 4, 5], "terms": ["matter", "mass", "volume", "space", "nahahawakan", "sumasakop", "nagsakop", "mahikap", "espasyo", "anumang", "unsang", "bigat", "halos", "gibug"], "fact": {"tl": "Ang matter ay anumang bagay na may mass (bigat) at sumasakop ng espasyo. Halos lahat ng nakikita o nahahawakan mo — bato, tubig, hangin — ay matter.", "en": "Matter is anything that has mass and takes up space. Almost everything you see or touch — rock, water, air — is matter.", "bis": "Ang matter mao ang bisan unsang butang nga adunay mass (gibug-aton) ug nagsakop og espasyo. Halos tanan nga imong makita o mahikap — bato, tubig, hangin — kay matter."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-properties-g3", "domain": "MATTER", "topic": "properties of materials", "grades": [3, 4, 5], "terms": ["properties", "color", "hardness", "texture", "float", "sink", "nakikilala", "pagbukud", "bukurin", "mailhan", "tigas", "katig", "molunod", "materyales", "lumulubog", "bigat"], "fact": {"tl": "Nakikilala ang iba't ibang materyales sa pamamagitan ng kanilang properties tulad ng kulay, tigas, texture, bigat, at kung lumulutang o lumulubog sa tubig. Ginagamit ang mga properties na ito para pagbukud-bukurin (i-classify) ang mga bagay.", "en": "Materials are recognized by their properties such as color, hardness, texture, weight, and whether they float or sink. These properties are used to sort and classify objects.", "bis": "Mailhan ang nagkalainlaing materyales pinaagi sa ilang properties sama sa kolor, katig-a, texture, gibug-aton, ug kung molutaw o molunod ba sa tubig. Gigamit kini nga mga properties aron i-classify ang mga butang."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-states-particles-g3", "domain": "MATTER", "topic": "states of matter", "grades": [3, 4, 5], "terms": ["solid", "liquid", "gas", "shape", "humuhugis", "tatlo", "modagayday", "lalagyan", "sudlanan", "espasyo", "mosunod", "state", "pangunahing", "umaagos"], "fact": {"tl": "May tatlong pangunahing state ng matter. Ang solid ay may sariling hugis (halimbawa: bato). Ang liquid ay umaagos at humuhugis sa lalagyan nito (halimbawa: tubig). Ang gas ay kumakalat sa buong espasyo (halimbawa: hangin). Lahat ng tatlo ay may mass.", "en": "Matter has three main states. A solid keeps its own shape (e.g., a rock). A liquid flows and takes the shape of its container (e.g., water). A gas spreads to fill space (e.g., air). All three have mass.", "bis": "Adunay tulo ka nag-unang state sa matter. Ang solid adunay kaugalingong porma (pananglitan: bato). Ang liquid modagayday ug mosunod sa porma sa sudlanan niini (pananglitan: tubig). Ang gas mokatag sa tibuok espasyo (pananglitan: hangin). Ang tanan nga tulo adunay mass."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-changes-of-state-g4", "domain": "MATTER", "topic": "changes of state", "grades": [4, 5, 6], "terms": ["melting", "freezing", "evaporation", "condensation", "boiling"], "fact": {"tl": "Nagbabago ang state ng matter kapag iniinit o pinapalamig: natutunaw (melting) ang solid papuntang liquid; nagyeyelo (freezing) ang liquid pabalik sa solid; sumisingaw (evaporation) ang liquid papuntang gas; at nagiging liquid muli ang gas (condensation). Pareho pa rin ang sangkap — tubig pa rin ang yelo, tubig, at singaw.", "en": "Matter changes state when heated or cooled: a solid melts to a liquid; a liquid freezes back to a solid, evaporates to a gas, and a gas condenses back to a liquid. It is still the same substance — ice, water, and steam are all water.", "bis": "Mausab ang state sa matter kung initan o bugnawon: matunaw (melting) ang solid ngadto sa liquid; mo-yelo (freezing) ang liquid balik sa solid; mo-alisngaw (evaporation) ang liquid ngadto sa gas; ug mobalik nga liquid ang gas (condensation). Pareho gihapon ang sustansya — tubig gihapon ang yelo, tubig, ug alisngaw."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-mass-volume-weight-g5", "domain": "MATTER", "topic": "mass volume and weight", "grades": [5, 6, 7], "terms": ["mass", "volume", "weight", "gravity", "espasyong", "sinasakop", "gisakpan", "birahay", "mahina", "huyang", "didto", "kakusog", "lakas", "hila"], "fact": {"tl": "Ang mass ay ang dami ng matter sa isang bagay; ang volume ay ang espasyong sinasakop nito; ang weight ay ang lakas ng hila ng gravity sa mass. Pareho ang mass mo kahit saan, pero mas magaan ang weight mo sa buwan dahil mas mahina ang gravity doon.", "en": "Mass is the amount of matter in an object; volume is the space it takes up; weight is the pull of gravity on that mass. Your mass is the same everywhere, but you weigh less on the Moon because its gravity is weaker.", "bis": "Ang mass mao ang gidaghanon sa matter sa usa ka butang; ang volume mao ang espasyong gisakpan niini; ang weight mao ang kakusog sa birahay sa gravity sa mass. Pareho ang imong mass bisan asa, apan mas gaan ang imong weight sa bulan kay mas huyang ang gravity didto."}, "source": "NRC PS2.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "matter-physical-chemical-change-g5", "domain": "MATTER", "topic": "physical and chemical change", "grades": [5, 6, 7], "terms": ["physical change", "chemical change", "substance", "sunog", "hulagway", "nasunog", "gihapon", "papel", "natutunaw", "anyo", "lahi", "natunaw", "pareho"], "fact": {"tl": "Sa physical change, nagbabago lang ang anyo o hugis ng bagay pero pareho pa rin ang sangkap — halimbawa, ang natutunaw na yelo ay tubig pa rin. Sa chemical change, nabubuo ang bagong sangkap — halimbawa, ang sunog na papel ay nagiging abo na iba na sa papel.", "en": "In a physical change only the form or shape changes but it is the same substance — e.g., melting ice is still water. In a chemical change a new substance forms — e.g., burning paper becomes ash, different from paper.", "bis": "Sa physical change, ang porma o hulagway lang sa butang ang mausab apan pareho gihapon ang sustansya — pananglitan, ang natunaw nga yelo kay tubig gihapon. Sa chemical change, adunay bag-ong sustansya nga maporma — pananglitan, ang nasunog nga papel mahimong abo nga lahi na sa papel."}, "source": "AAAS BSL Ch.4D; NRC PS1.B", "generator": "claude", "reviewed": false},
  {"id": "matter-mixtures-g5", "domain": "MATTER", "topic": "mixtures", "grades": [5, 6], "terms": ["mixture", "pure substance", "combine", "pinaghalong", "kani", "iisa", "gisagol", "paghiwalayin", "mabulag", "dalawa", "kadalasang", "buhangin", "purong"], "fact": {"tl": "Ang mixture ay pinaghalong dalawa o higit pang sangkap na hindi nagbabago ang kani-kanilang katangian, at kadalasang puwedeng paghiwalayin muli (halimbawa: buhangin at tubig). Iba ito sa purong sangkap na iisa lang ang uri.", "en": "A mixture is two or more substances combined without changing their own properties, and usually can be separated again (e.g., sand and water). This differs from a pure substance, which is only one kind.", "bis": "Ang mixture mao ang gisagol nga duha o sobra pa nga sustansya nga wala mausab ang ila-ilang kinaiya, ug kasagaran mabulag balik (pananglitan: balas ug tubig). Lahi kini sa putli nga sustansya nga usa ra ka klase."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-separating-mixtures-g6", "domain": "MATTER", "topic": "separating mixtures", "grades": [5, 6, 7], "terms": ["filtering", "evaporation", "magnet", "sieving", "ihiwalay", "paggamit", "pagsala", "bulagon", "ayag", "magkaibang", "paghiwalayin", "mabulag", "gidak", "laki"], "fact": {"tl": "Puwedeng paghiwalayin ang mga mixture gamit ang kanilang properties: filtering (para ihiwalay ang solid sa likido), evaporation (para makuha ang natunaw na solid sa tubig), paggamit ng magnet (para sa bakal), at sieving o pagsala (para sa magkaibang laki).", "en": "Mixtures can be separated using their properties: filtering (solids from liquids), evaporation (a dissolved solid from water), a magnet (for iron), and sieving (by particle size).", "bis": "Mabulag ang mga mixture gamit ang ilang properties: filtering (aron bulagon ang solid sa likido), evaporation (aron makuha ang natunaw nga solid sa tubig), paggamit og magnet (para sa puthaw), ug sieving o pag-ayag (para sa nagkalainlaing gidak-on)."}, "source": "DepEd Science CG (Matter); AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "matter-solutions-g6", "domain": "MATTER", "topic": "solutions", "grades": [6, 7], "terms": ["solution", "solute", "solvent", "dissolve", "saturated", "limitasyon", "karami", "tunawin", "ganap", "kayang", "hingpit", "lain", "natutunaw", "puwedeng", "matunaw"], "fact": {"tl": "Ang solution ay isang mixture kung saan ganap na natutunaw ang isang sangkap (solute) sa iba (solvent), tulad ng asukal sa tubig. May limitasyon kung gaano karami ang puwedeng matunaw — kapag hindi na kayang tunawin, tinatawag itong saturated.", "en": "A solution is a mixture where one substance (solute) fully dissolves in another (solvent), like sugar in water. There is a limit to how much can dissolve — once no more dissolves, it is saturated.", "bis": "Ang solution usa ka mixture diin hingpit nga matunaw ang usa ka sustansya (solute) sa lain (solvent), sama sa asukal sa tubig. Adunay limitasyon kung pila ang mahimong matunaw — kung dili na matunaw, gitawag kini nga saturated."}, "source": "NRC PS1.A; DepEd Science CG (Matter)", "generator": "claude", "reviewed": false},
  {"id": "matter-particle-nature-g7", "domain": "MATTER", "topic": "particle nature of matter", "grades": [6, 7, 8], "terms": ["particle", "atom", "molecule", "motion"], "fact": {"tl": "Ang lahat ng matter ay binubuo ng napakaliliit at hindi nakikitang particle (atoms at molecules) na patuloy na gumagalaw. Sa solid, magkakalapit at nanginginig lang sila; sa liquid, magkalapit pero nakakadausdos; sa gas, magkakalayo at mabilis. Ito ang dahilan ng hugis at galaw ng bawat state.", "en": "All matter is made of extremely tiny, invisible particles (atoms and molecules) in constant motion. In a solid they are packed and only vibrate; in a liquid they are close but slide past each other; in a gas they are far apart and fast. This explains each state's shape and behavior.", "bis": "Ang tanang matter gilangkoban og gagmay kaayo ug dili makita nga particle (atoms ug molecules) nga padayon nga naglihok. Sa solid, magkaduol ug magkurog lang sila; sa liquid, duol apan makadausdos; sa gas, magkalayo ug paspas. Mao kini ang hinungdan sa porma ug lihok sa matag state."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-conservation-g7", "domain": "MATTER", "topic": "conservation of matter", "grades": [6, 7, 8], "terms": ["conservation of matter", "mass", "nadaragdag", "madugang", "ginamit", "kanhing", "dating", "kinatibuk", "kabuuang", "masunog", "basta", "nananatili"], "fact": {"tl": "Sa anumang physical o chemical change, hindi nawawala o nadaragdag ang matter — nananatili ang kabuuang mass. Kapag nasunog ang kahoy, hindi ito basta nawawala: nagiging abo at mga gas ito na ang kabuuang bigat ay katumbas ng dating kahoy at hangin na ginamit.", "en": "In any physical or chemical change, matter is not lost or created — the total mass stays the same. When wood burns, it does not simply vanish: it becomes ash and gases whose total mass equals the original wood plus the air used.", "bis": "Sa bisan unsang physical o chemical change, dili mawala o madugang ang matter — magpabilin ang kinatibuk-ang mass. Kung masunog ang kahoy, dili kini basta mawala: mahimo kining abo ug mga gas nga ang kinatibuk-ang gibug-aton katumbas sa kanhing kahoy ug hangin nga gigamit."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-atoms-elements-g8", "domain": "MATTER", "topic": "atoms and elements", "grades": [7, 8], "terms": ["atom", "element", "limitadong", "limitado", "kinagamyang", "siyang", "purong", "iisang", "putli", "pinakamaliit", "tanang", "gidaghanon"], "fact": {"tl": "Ang atom ang pinakamaliit na bahagi ng isang element. Ang element ay purong sangkap na gawa sa iisang uri lang ng atom (halimbawa: oxygen, carbon, gold). May limitadong bilang ng elements na siyang building blocks ng lahat ng matter.", "en": "An atom is the smallest part of an element. An element is a pure substance made of only one kind of atom (e.g., oxygen, carbon, gold). There is a limited number of elements, and they are the building blocks of all matter.", "bis": "Ang atom mao ang kinagamyang bahin sa usa ka element. Ang element usa ka putli nga sustansya nga hinimo sa usa ra ka klase nga atom (pananglitan: oxygen, carbon, gold). Adunay limitado nga gidaghanon sa elements nga mao ang building blocks sa tanang matter."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-compounds-molecules-g8", "domain": "MATTER", "topic": "compounds and molecules", "grades": [7, 8], "terms": ["compound", "molecule", "element"], "fact": {"tl": "Kapag nagsama ang atoms ng dalawa o higit pang element, nakabubuo sila ng compound na may bagong properties — halimbawa, ang tubig (H₂O) ay gawa sa hydrogen at oxygen pero iba ito sa dalawang gas na iyon. Ang molecule ay grupo ng atoms na magkakabit.", "en": "When atoms of two or more elements combine, they form a compound with new properties — e.g., water (H₂O) is made of hydrogen and oxygen but differs from those two gases. A molecule is a group of bonded atoms.", "bis": "Kung magsagol ang atoms sa duha o sobra pa nga element, makaporma silag compound nga adunay bag-ong properties — pananglitan, ang tubig (H₂O) hinimo sa hydrogen ug oxygen apan lahi kini niadtong duha ka gas. Ang molecule usa ka grupo sa atoms nga nagkadikit."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-temperature-particles-g7", "domain": "MATTER", "topic": "heat and particle motion", "grades": [6, 7, 8], "terms": ["temperature", "heat", "expansion", "particle motion"], "fact": {"tl": "Mas mabilis gumalaw ang mga particle ng matter kapag mas mainit ito, at mas mabagal kapag malamig. Kaya kadalasang lumalaki (expansion) ang mga bagay kapag iniinit at umuurong kapag pinapalamig.", "en": "The particles in matter move faster when it is hotter and slower when colder. This is why things usually expand when heated and contract when cooled.", "bis": "Mas paspas molihok ang mga particle sa matter kung mas init kini, ug mas hinay kung bugnaw. Mao nga kasagaran modako (expansion) ang mga butang kung initan ug mokunhod kung bugnawon."}, "source": "AAAS BSL Ch.4D; NRC PS3.A", "generator": "claude", "reviewed": false},
  {"id": "matter-elements-compounds-mixtures-g8", "domain": "MATTER", "topic": "elements compounds mixtures", "grades": [8], "terms": ["element", "compound", "mixture", "magkakaibang", "magkasama", "managlahi", "pinaghalo", "gisagol", "paghiwalayin", "mabulag", "dalawa", "iisang", "higit"], "fact": {"tl": "Tatlong magkakaibang bagay: Ang element ay iisang uri ng atom. Ang compound ay dalawa o higit pang element na magkasama sa fixed na ratio at may bagong properties. Ang mixture ay pinaghalo lang nang hindi nabubuo ang bagong sangkap, kaya puwedeng paghiwalayin muli.", "en": "Three different things: an element is one kind of atom. A compound is two or more elements joined in a fixed ratio with new properties. A mixture is just combined without forming a new substance, so it can be separated again.", "bis": "Tulo ka managlahi: Ang element usa ra ka klase nga atom. Ang compound duha o sobra pa nga element nga gisagol sa fixed nga ratio ug adunay bag-ong properties. Ang mixture gisagol lang nga walay bag-ong sustansya, mao nga mabulag balik."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-acids-bases-g9", "domain": "MATTER", "topic": "acids and bases", "grades": [9, 10], "terms": ["acid", "base", "pH", "neutral", "madanlog", "mapakla", "maaslom", "mapait", "sinusukat", "madulas", "gisukod", "maasim", "suka", "kalamansi"], "fact": {"tl": "Ang acid (tulad ng suka at calamansi) ay maasim; ang base (tulad ng sabon at baking soda) ay mapakla at madulas. Sinusukat ng pH scale (0–14) kung gaano ka-acid o ka-base ang isang bagay: mas mababa sa 7 ay acid, mas mataas sa 7 ay base, at ang 7 ay neutral tulad ng purong tubig.", "en": "An acid (like vinegar and calamansi) is sour; a base (like soap and baking soda) is bitter and slippery. The pH scale (0–14) measures how acidic or basic something is: below 7 is acidic, above 7 is basic, and 7 is neutral like pure water.", "bis": "Ang acid (sama sa suka ug kalamansi) maaslom; ang base (sama sa sabon ug baking soda) mapait ug madanlog. Gisukod sa pH scale (0–14) kung unsa ka-acid o ka-base ang usa ka butang: ubos sa 7 kay acid, taas sa 7 kay base, ug ang 7 kay neutral sama sa putli nga tubig."}, "source": "DepEd Science CG (Matter, JHS); NRC PS1.B", "generator": "claude", "reviewed": false},
  {"id": "matter-periodic-metals-g9", "domain": "MATTER", "topic": "periodic table metals nonmetals", "grades": [9, 10], "terms": ["periodic table", "metal", "nonmetal", "element"], "fact": {"tl": "Nakaayos ang mga element sa periodic table. Ang metals (tulad ng bakal at tanso) ay kadalasang makintab, matibay, at nagpapadaloy ng init at kuryente; ang nonmetals (tulad ng oxygen at carbon) ay kadalasang hindi nagpapadaloy ng kuryente.", "en": "The elements are arranged in the periodic table. Metals (like iron and copper) are usually shiny, strong, and conduct heat and electricity; nonmetals (like oxygen and carbon) usually do not conduct electricity.", "bis": "Gihan-ay ang mga element sa periodic table. Ang metals (sama sa puthaw ug tumbaga) kasagaran sinaw, lig-on, ug nagpadala og init ug kuryente; ang nonmetals (sama sa oxygen ug carbon) kasagaran dili magpadala og kuryente."}, "source": "DepEd Science CG (Matter, JHS); AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "living-photosynthesis-g5", "domain": "LIVING_THINGS", "topic": "photosynthesis", "grades": [4, 5, 6], "terms": ["photosynthesis", "sunlight", "carbon dioxide", "oxygen", "glucose", "chlorophyll", "nilalanghap", "nagbuga", "berdeng", "gumawa", "giginhawa", "berde", "humuhuli", "modakop", "sarili", "naglalabas"], "fact": {"tl": "Sa photosynthesis, ginagamit ng halaman ang liwanag ng araw, tubig, at carbon dioxide mula sa hangin para gumawa ng sarili nitong pagkain na sugar (glucose). Naglalabas din ito ng oxygen na nilalanghap natin. Ang berdeng kulay (chlorophyll) sa dahon ang humuhuli sa liwanag.", "en": "In photosynthesis a plant uses sunlight, water, and carbon dioxide from the air to make its own food, a sugar (glucose). It also releases the oxygen we breathe. The green color (chlorophyll) in leaves captures the light.", "bis": "Sa photosynthesis, gigamit sa tanom ang kahayag sa adlaw, tubig, ug carbon dioxide gikan sa hangin aron maghimo sa kaugalingong pagkaon nga sugar (glucose). Nagbuga usab kini og oxygen nga atong giginhawa. Ang berde nga kolor (chlorophyll) sa dahon mao ang modakop sa kahayag."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "living-insect-vs-spider-g3", "domain": "LIVING_THINGS", "topic": "insects", "grades": [3, 4], "terms": ["insect", "spider", "legs", "body parts", "dibdib", "dughan", "tiil", "lawalawa", "gagamba", "walong", "tiyan", "anim", "unom", "walo"], "fact": {"tl": "Ang insekto ay may anim (6) na paa at tatlong bahagi ng katawan: ulo (head), dibdib (thorax), at tiyan (abdomen). Ang gagamba ay HINDI insekto dahil may walong (8) paa ito at dalawang bahagi lang ng katawan.", "en": "An insect has six (6) legs and three body parts: head, thorax, and abdomen. A spider is NOT an insect because it has eight (8) legs and only two body parts.", "bis": "Ang insekto adunay unom (6) ka tiil ug tulo ka bahin sa lawas: ulo (head), dughan (thorax), ug tiyan (abdomen). Ang lawalawa DILI insekto kay adunay walo (8) ka tiil ug duha ra ka bahin sa lawas."}, "source": "AAAS BSL Ch.5 (diversity of life)", "generator": "claude", "reviewed": false},
  {"id": "force-push-pull-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "force", "grades": [3, 4, 5], "terms": ["force", "push", "pull", "motion", "makapahunong", "magpatigil", "makapabag", "palihukon", "igalaw", "tulod", "makapalihok", "magpagalaw", "magpabago", "tulak"], "fact": {"tl": "Ang force ay isang tulak (push) o hila (pull) na puwedeng magpagalaw, magpatigil, o magpabago ng direksyon ng isang bagay. Mas malakas na force ang kailangan para igalaw ang mas mabigat na bagay.", "en": "A force is a push or a pull that can make an object move, stop, or change direction. A heavier object needs a stronger force to move it.", "bis": "Ang force usa ka tulod (push) o bira (pull) nga makapalihok, makapahunong, o makapabag-o sa direksyon sa usa ka butang. Mas kusog nga force ang gikinahanglan aron palihukon ang mas bug-at nga butang."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "earth-water-cycle-g4", "domain": "EARTH_SPACE", "topic": "water cycle", "grades": [4, 5, 6], "terms": ["water cycle", "evaporation", "condensation", "precipitation"], "fact": {"tl": "Sa water cycle, ang init ng araw ay nagpapasingaw ng tubig mula sa dagat at lupa (evaporation). Tumataas ang singaw, lumalamig, at nagiging ulap (condensation). Kapag mabigat na ang ulap, bumabagsak ang tubig bilang ulan (precipitation), at bumabalik ito sa dagat at lupa.", "en": "In the water cycle, the sun's heat evaporates water from seas and land. The vapor rises, cools, and forms clouds (condensation). When clouds get heavy, water falls as rain (precipitation) and returns to seas and land.", "bis": "Sa water cycle, ang kainit sa adlaw mopaalisngaw sa tubig gikan sa dagat ug yuta (evaporation). Mosaka ang alisngaw, mobugnaw, ug mahimong panganod (condensation). Kung mabug-at na ang panganod, mahulog ang tubig isip ulan (precipitation), ug mobalik kini sa dagat ug yuta."}, "source": "AAAS BSL Ch.4; NRC ESS2.C", "generator": "claude", "reviewed": false},
  {"id": "living-characteristics-g3", "domain": "LIVING_THINGS", "topic": "living vs nonliving", "grades": [3, 4], "terms": ["living", "nonliving", "grow", "reproduce", "nakakapagpaparami", "kumukuha", "tumutugon", "motubag", "mokuha", "humihinga", "ginagawa", "moginhawa", "kumakain", "mokaon"], "fact": {"tl": "Ang mga buhay na bagay (living things) ay lumalaki, kumakain o kumukuha ng enerhiya, humihinga, tumutugon sa paligid, at nakakapagpaparami (reproduce). Ang mga di-buhay na bagay tulad ng bato at tubig ay hindi ginagawa ang mga ito.", "en": "Living things grow, take in food or energy, breathe, respond to their surroundings, and reproduce. Nonliving things like rocks and water do not do these.", "bis": "Ang buhi nga mga butang (living things) motubo, mokaon o mokuha og enerhiya, moginhawa, motubag sa palibot, ug makahimo og bag-o nga sama nila (reproduce). Ang dili-buhi nga mga butang sama sa bato ug tubig wala maghimo niini."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-basic-needs-g3", "domain": "LIVING_THINGS", "topic": "basic needs", "grades": [3, 4], "terms": ["needs", "food", "water", "air", "sunlight", "matitirhan", "nagkinahanglan", "mabuhay", "anan", "mabuhi", "kailangan", "sikat", "sustansya", "hayop", "lupa"], "fact": {"tl": "Para mabuhay, kailangan ng mga hayop ng pagkain, tubig, hangin, at matitirhan. Kailangan naman ng mga halaman ng tubig, hangin (carbon dioxide), sikat ng araw, at sustansya mula sa lupa.", "en": "To live, animals need food, water, air, and a place to live. Plants need water, air (carbon dioxide), sunlight, and nutrients from the soil.", "bis": "Aron mabuhi, ang mga hayop nagkinahanglan og pagkaon, tubig, hangin, ug puy-anan. Ang mga tanom nagkinahanglan og tubig, hangin (carbon dioxide), kahayag sa adlaw, ug sustansya gikan sa yuta."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "living-plant-parts-g3", "domain": "LIVING_THINGS", "topic": "parts of a plant", "grades": [3, 4], "terms": ["roots", "stem", "leaves", "flower", "sumusuporta", "pagpaparami", "humuhigop", "mosuporta", "pagsanay", "humahawak", "mokupot", "tungkulin", "tangkay", "punoan"], "fact": {"tl": "May iba't ibang bahagi ang halaman na may tungkulin: ang ugat (roots) ang humuhigop ng tubig at sustansya at humahawak sa lupa; ang tangkay (stem) ang nagdadala ng tubig at sumusuporta sa halaman; ang dahon (leaves) ang gumagawa ng pagkain sa photosynthesis; at ang bulaklak (flower) ang bahagi para sa pagpaparami.", "en": "A plant has parts with jobs: roots absorb water and nutrients and anchor it; the stem carries water and supports the plant; leaves make food by photosynthesis; and the flower is the part for reproduction.", "bis": "Adunay nagkalainlaing bahin ang tanom nga may tahas: ang gamot (roots) mosuyop og tubig ug sustansya ug mokupot sa yuta; ang punoan (stem) modala sa tubig ug mosuporta sa tanom; ang dahon (leaves) maghimo og pagkaon pinaagi sa photosynthesis; ug ang bulak (flower) mao ang bahin alang sa pagsanay."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-vertebrate-invertebrate-g4", "domain": "LIVING_THINGS", "topic": "animal groups", "grades": [4, 5], "terms": ["vertebrate", "invertebrate", "backbone", "gulugod", "pasayan", "hipon", "lawalawa", "gagamba", "likod", "bitin", "ibon", "ahas", "langgam"], "fact": {"tl": "Nahahati ang mga hayop sa dalawang malaking grupo: ang vertebrates na may gulugod o backbone (tulad ng isda, ibon, ahas, palaka, at tao) at ang invertebrates na walang backbone (tulad ng insekto, gagamba, uod, at hipon).", "en": "Animals fall into two big groups: vertebrates with a backbone (like fish, birds, snakes, frogs, and humans) and invertebrates without a backbone (like insects, spiders, worms, and shrimp).", "bis": "Nabahin ang mga hayop sa duha ka dako nga grupo: ang vertebrates nga adunay bukog sa likod o backbone (sama sa isda, langgam, bitin, baki, ug tawo) ug ang invertebrates nga walay backbone (sama sa insekto, lawalawa, ulod, ug pasayan)."}, "source": "AAAS BSL Ch.5 (diversity of life)", "generator": "claude", "reviewed": false},
  {"id": "living-life-cycle-g4", "domain": "LIVING_THINGS", "topic": "life cycles", "grades": [4, 5], "terms": ["life cycle", "metamorphosis", "egg", "larva", "ipinanganak", "namamatay", "tangkong", "moturok", "mamatay", "matawo", "kokon", "paru", "paro", "nagpaparami"], "fact": {"tl": "Bawat buhay na bagay ay dumadaan sa life cycle: ipinanganak o tumutubo, lumalaki, nagpaparami, at namamatay. May mga hayop na dumadaan sa metamorphosis — halimbawa, ang paru-paro: itlog → higad (caterpillar) → kokon (pupa) → paru-paro; at ang palaka: itlog → ulo-ulo (tadpole) → palaka.", "en": "Every living thing goes through a life cycle: it is born or sprouts, grows, reproduces, and dies. Some animals undergo metamorphosis — e.g., a butterfly: egg → caterpillar → pupa → butterfly; and a frog: egg → tadpole → frog.", "bis": "Ang matag buhi nga butang moagi sa life cycle: matawo o moturok, motubo, mosanay, ug mamatay. Adunay mga hayop nga moagi sa metamorphosis — pananglitan, ang alibangbang: itlog → tangkong (caterpillar) → pupa → alibangbang; ug ang baki: itlog → ulo-ulo (tadpole) → baki."}, "source": "AAAS BSL Ch.5; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "living-habitat-adaptation-g4", "domain": "LIVING_THINGS", "topic": "habitat and adaptation", "grades": [4, 5, 6], "terms": ["habitat", "adaptation", "survive", "environment", "pangangailangan", "panginahanglan", "nakukuha", "pinasahi", "organismo", "disyerto", "malalim", "lawom", "kapaligiran", "balahibo"], "fact": {"tl": "Ang habitat ay ang natural na tirahan ng isang halaman o hayop kung saan nakukuha nito ang pangangailangan nito. Ang adaptation ay ang espesyal na katangian na tumutulong sa isang organismo na mabuhay sa kapaligiran nito — halimbawa, ang makapal na balahibo ng hayop sa malamig na lugar, o ang malalim na ugat ng halaman sa disyerto.", "en": "A habitat is the natural home where a plant or animal gets what it needs. An adaptation is a special trait that helps an organism survive in its environment — e.g., thick fur on an animal in a cold place, or deep roots on a desert plant.", "bis": "Ang habitat mao ang natural nga puy-anan sa usa ka tanom o hayop diin makuha niini ang panginahanglan niini. Ang adaptation mao ang pinasahi nga kinaiya nga motabang sa organismo nga mabuhi sa palibot niini — pananglitan, ang baga nga balhibo sa hayop sa bugnaw nga dapit, o ang lawom nga gamot sa tanom sa disyerto."}, "source": "AAAS BSL Ch.5; NRC LS4.C", "generator": "claude", "reviewed": false},
  {"id": "living-food-chain-g5", "domain": "LIVING_THINGS", "topic": "food chain", "grades": [5, 6], "terms": ["food chain", "producer", "consumer", "decomposer", "naghimo", "ipinapakita", "naglalansag", "gipakita", "moguba", "agos", "dumadaloy", "kumakain", "patay", "mokaon"], "fact": {"tl": "Ipinapakita ng food chain kung paano dumadaloy ang enerhiya sa pamamagitan ng pagkain. Ang mga halaman ay producers (gumagawa ng sariling pagkain). Ang mga hayop na kumakain ng halaman o ibang hayop ay consumers. Ang mga decomposers (tulad ng fungi at bacteria) ang naglalansag sa patay na bagay pabalik sa lupa.", "en": "A food chain shows how energy flows through eating. Plants are producers (they make their own food). Animals that eat plants or other animals are consumers. Decomposers (like fungi and bacteria) break down dead matter back into the soil.", "bis": "Gipakita sa food chain kung giunsa pag-agos ang enerhiya pinaagi sa pagkaon. Ang mga tanom kay producers (naghimo sa kaugalingong pagkaon). Ang mga hayop nga mokaon og tanom o ubang hayop kay consumers. Ang mga decomposers (sama sa fungi ug bacteria) maoy moguba sa patay nga butang balik sa yuta."}, "source": "AAAS BSL Ch.5; NRC LS2.B", "generator": "claude", "reviewed": false},
  {"id": "living-ecosystem-g6", "domain": "LIVING_THINGS", "topic": "ecosystem", "grades": [6, 7], "terms": ["ecosystem", "biotic", "abiotic", "environment", "uugnayan", "pagpakig", "kausaban", "microorganism", "nakakaapekto", "makaapekto", "magkakaugnay", "pagbabago", "magkadugtong", "tanan"], "fact": {"tl": "Ang ecosystem ay ang lahat ng buhay na bagay (biotic — halaman, hayop, microorganism) at di-buhay na bagay (abiotic — tubig, hangin, lupa, init ng araw) sa isang lugar, at kung paano sila nag-uugnayan. Magkakaugnay ang lahat: ang pagbabago sa isa ay nakakaapekto sa iba.", "en": "An ecosystem is all the living things (biotic — plants, animals, microorganisms) and nonliving things (abiotic — water, air, soil, sunlight) in a place, and how they interact. Everything is connected: a change in one affects the others.", "bis": "Ang ecosystem mao ang tanang buhi nga butang (biotic — tanom, hayop, microorganism) ug dili-buhi nga butang (abiotic — tubig, hangin, yuta, kahayag sa adlaw) sa usa ka dapit, ug kung giunsa sila pagpakig-uban. Magkadugtong ang tanan: ang kausaban sa usa makaapekto sa uban."}, "source": "NRC LS2.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-respiration-g6", "domain": "LIVING_THINGS", "topic": "respiration", "grades": [6, 7, 8], "terms": ["respiration", "oxygen", "energy", "carbon dioxide", "enerhiyang", "palabasin", "gumagamit", "nagbuga", "sukwahi", "mogamit", "kabaligtaran", "nakaimbak", "ipagawas", "natipig"], "fact": {"tl": "Sa respiration, ginagamit ng mga buhay na bagay ang oxygen para palabasin ang enerhiyang nakaimbak sa pagkain (sugar), at naglalabas sila ng carbon dioxide at tubig. Kabaligtaran ito ng photosynthesis: ang halaman ay parehong gumagawa ng pagkain (photosynthesis) at gumagamit nito para sa enerhiya (respiration).", "en": "In respiration, living things use oxygen to release the energy stored in food (sugar), giving off carbon dioxide and water. It is the reverse of photosynthesis: plants both make food (photosynthesis) and use it for energy (respiration).", "bis": "Sa respiration, gigamit sa buhi nga mga butang ang oxygen aron ipagawas ang enerhiya nga natipig sa pagkaon (sugar), ug nagbuga sila og carbon dioxide ug tubig. Sukwahi kini sa photosynthesis: ang tanom maghimo og pagkaon (photosynthesis) ug mogamit niini alang sa enerhiya (respiration)."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-cell-g7", "domain": "LIVING_THINGS", "topic": "the cell", "grades": [7, 8], "terms": ["cell", "unit of life", "organism", "trilyon", "yunit", "kinagamyang", "organismo", "trilyong", "gilangkoban", "binubuo", "iisang", "pinakamaliit", "marami"], "fact": {"tl": "Ang cell ang pinakamaliit na yunit ng buhay — lahat ng buhay na bagay ay binubuo ng isa o higit pang cell. May organismo na iisang cell lang (tulad ng bacteria), at may marami tulad ng tao na binubuo ng trilyong cell.", "en": "The cell is the smallest unit of life — all living things are made of one or more cells. Some organisms are a single cell (like bacteria), and many, like humans, are made of trillions of cells.", "bis": "Ang cell mao ang kinagamyang yunit sa kinabuhi — ang tanang buhi nga butang gilangkoban og usa o sobra pa ka cell. Adunay organismo nga usa ra ka cell (sama sa bacteria), ug adunay daghan sama sa tawo nga gilangkoban og trilyon ka cell."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-plant-animal-cell-g7", "domain": "LIVING_THINGS", "topic": "plant vs animal cell", "grades": [7, 8], "terms": ["cell wall", "chloroplast", "nucleus", "membrane", "panggawas", "dagdag", "dugang", "nagkokontrol", "nagkontrol", "panlabas", "sentro", "parehong", "matigas", "alang"], "fact": {"tl": "Parehong may nucleus (sentro na nagkokontrol), cell membrane, at cytoplasm ang plant at animal cell. Pero ang plant cell ay may dagdag na cell wall (matigas na panlabas na balat) at chloroplasts (para sa photosynthesis) na wala sa animal cell.", "en": "Both plant and animal cells have a nucleus (control center), cell membrane, and cytoplasm. But a plant cell also has a cell wall (a stiff outer layer) and chloroplasts (for photosynthesis), which an animal cell does not.", "bis": "Parehong adunay nucleus (sentro nga nagkontrol), cell membrane, ug cytoplasm ang plant ug animal cell. Apan ang plant cell adunay dugang nga cell wall (gahi nga panggawas nga panit) ug chloroplasts (alang sa photosynthesis) nga wala sa animal cell."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-body-systems-g5", "domain": "LIVING_THINGS", "topic": "human body systems", "grades": [5, 6], "terms": ["body systems", "organ", "digestive", "circulatory", "respiratory", "magkakatulong", "nagtinabangay", "pagdaloy", "pagkontrol", "pagtunaw", "paghilis", "pagbati", "agos", "magkakaugnay", "pakiramdam"], "fact": {"tl": "Ang katawan ng tao ay may magkakaugnay na body systems na may tungkulin: digestive (pagtunaw ng pagkain), respiratory (paghinga), circulatory (pagdaloy ng dugo), skeletal (buto), muscular (kalamnan), at nervous (pagkontrol at pakiramdam). Magkakatulong silang lahat para manatiling buhay ang tao.", "en": "The human body has connected systems with jobs: digestive (breaking down food), respiratory (breathing), circulatory (blood flow), skeletal (bones), muscular (muscles), and nervous (control and sensing). They all work together to keep a person alive.", "bis": "Ang lawas sa tawo adunay magkadugtong nga body systems nga may tahas: digestive (paghilis sa pagkaon), respiratory (pagginhawa), circulatory (pag-agos sa dugo), skeletal (bukog), muscular (kaunoran), ug nervous (pagkontrol ug pagbati). Nagtinabangay silang tanan aron mabuhi ang tawo."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-digestive-g6", "domain": "LIVING_THINGS", "topic": "digestive system", "grades": [6, 7], "terms": ["digestion", "stomach", "intestine", "nutrients", "nginunguya", "hinahaluan", "inilalabas", "gisapsap", "masuyop", "sikmura", "bituka", "laway", "tinai", "dumi"], "fact": {"tl": "Sa digestive system, dumadaan ang pagkain sa bibig (nginunguya at hinahaluan ng laway), lalamunan, sikmura (stomach, kung saan natutunaw ito), at bituka (intestines, kung saan sinisipsip ang sustansya papunta sa dugo). Ang hindi natunaw ay inilalabas bilang dumi.", "en": "In the digestive system, food passes through the mouth (chewed and mixed with saliva), the esophagus, the stomach (where it is broken down), and the intestines (where nutrients are absorbed into the blood). What is not digested is passed out as waste.", "bis": "Sa digestive system, ang pagkaon moagi sa baba (gisapsap ug gisagolan og laway), tutunlan, tiyan (stomach, diin matunaw kini), ug tinai (intestines, diin masuyop ang sustansya ngadto sa dugo). Ang dili matunaw ipagawas isip hugaw."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-circulatory-g6", "domain": "LIVING_THINGS", "topic": "circulatory system", "grades": [6, 7], "terms": ["heart", "blood", "vessels", "oxygen", "naghahatid", "bumobomba", "mobomba", "waste", "kasingkasing", "mokuha", "aalis", "puso", "hugaw", "kalamnan"], "fact": {"tl": "Ang circulatory system ang nagdadala ng dugo sa buong katawan. Ang puso (heart) ay isang kalamnan na bumobomba ng dugo sa mga ugat (blood vessels). Ang dugo ang naghahatid ng oxygen at sustansya sa mga cell at nag-aalis ng mga waste tulad ng carbon dioxide.", "en": "The circulatory system moves blood around the body. The heart is a muscle that pumps blood through blood vessels. Blood delivers oxygen and nutrients to cells and removes wastes like carbon dioxide.", "bis": "Ang circulatory system maoy modala sa dugo sa tibuok lawas. Ang kasingkasing (heart) usa ka kaunoran nga mobomba sa dugo agi sa mga ugat (blood vessels). Ang dugo modala og oxygen ug sustansya ngadto sa mga cell ug mokuha sa mga hugaw sama sa carbon dioxide."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-respiratory-g6", "domain": "LIVING_THINGS", "topic": "respiratory system", "grades": [6, 7], "terms": ["lungs", "breathing", "oxygen", "carbon dioxide", "pinapalabas", "inihihinga", "modumala", "huminga", "ibuga", "humahawak", "pagawas", "unya", "pumapasok", "palabas"], "fact": {"tl": "Ang respiratory system ang humahawak sa paghinga. Kapag huminga ka, pumapasok ang hangin sa baga (lungs), kung saan kinukuha ng dugo ang oxygen at pinapalabas ang carbon dioxide. Pagkatapos, inihihinga mo palabas ang carbon dioxide.", "en": "The respiratory system handles breathing. When you breathe in, air enters the lungs, where the blood takes in oxygen and gives off carbon dioxide. Then you breathe the carbon dioxide back out.", "bis": "Ang respiratory system maoy modumala sa pagginhawa. Kung moginhawa ka, mosulod ang hangin sa baga (lungs), diin kuhaon sa dugo ang oxygen ug ibuga ang carbon dioxide. Unya, imong giginhawa pagawas ang carbon dioxide."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-skeletal-muscular-g5", "domain": "LIVING_THINGS", "topic": "skeletal and muscular system", "grades": [5, 6], "terms": ["bones", "skeleton", "muscles", "support"], "fact": {"tl": "Ang skeletal system (mga buto o skeleton) ang nagbibigay ng hugis at suporta sa katawan at nag-iingat sa mga organ. Ang muscular system (mga kalamnan o muscles) ang nakakabit sa buto at humihila sa mga ito para tayo makagalaw. Magkatuwang silang gumagana.", "en": "The skeletal system (bones) gives the body shape and support and protects organs. The muscular system (muscles) attaches to bones and pulls on them so we can move. They work as partners.", "bis": "Ang skeletal system (mga bukog o skeleton) maghatag og porma ug suporta sa lawas ug manalipod sa mga organ. Ang muscular system (mga kaunoran o muscles) nakadikit sa bukog ug mobira niini aron makalihok ta. Magtinabangay sila."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-nervous-g7", "domain": "LIVING_THINGS", "topic": "nervous system", "grades": [7, 8], "terms": ["brain", "nerves", "senses", "signals", "nagpoproseso", "tumatanggap", "moproseso", "sentrong", "pagtubag", "tutugon", "modawat", "mosugo", "uutos", "nagkokontrol"], "fact": {"tl": "Ang nervous system — utak (brain), spinal cord, at nerves — ang sentrong nagkokontrol ng katawan. Tumatanggap ito ng signals mula sa mga pandama (mata, tainga, balat, ilong, dila), nagpoproseso, at nag-uutos sa katawan kung paano tutugon.", "en": "The nervous system — brain, spinal cord, and nerves — is the body's control center. It receives signals from the senses (eyes, ears, skin, nose, tongue), processes them, and tells the body how to respond.", "bis": "Ang nervous system — utok (brain), spinal cord, ug nerves — mao ang sentro nga nagkontrol sa lawas. Modawat kini og signals gikan sa mga igbalati (mata, dalunggan, panit, ilong, dila), moproseso, ug mosugo sa lawas kung unsaon pagtubag."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-classification-g7", "domain": "LIVING_THINGS", "topic": "classification of living things", "grades": [7, 8], "terms": ["classification", "species", "kingdom", "characteristics", "magkakatulad", "giklasipikar", "kinatukmaang", "pinakatiyak", "siyentipiko", "paghingalan", "pangalanan", "iniuuri", "pagtuon", "aralan"], "fact": {"tl": "Iniuuri (classified) ang mga buhay na bagay ayon sa kanilang magkakatulad na katangian, mula sa malalaking grupo (tulad ng hayop, halaman, fungi, at microorganism) hanggang sa pinakatiyak na grupo na species. Tumutulong ito sa mga siyentipiko na pag-aralan at pangalanan ang milyon-milyong klase ng buhay.", "en": "Living things are classified by their shared characteristics, from large groups (like animals, plants, fungi, and microorganisms) down to the most specific group, the species. This helps scientists study and name the millions of kinds of life.", "bis": "Giklasipikar ang mga buhi nga butang sumala sa ilang managsama nga kinaiya, gikan sa dagkong grupo (sama sa hayop, tanom, fungi, ug microorganism) hangtod sa kinatukmaang grupo nga species. Motabang kini sa mga siyentista sa pagtuon ug paghingalan sa milyon-milyon ka klase sa kinabuhi."}, "source": "AAAS BSL Ch.5; NRC LS4.A", "generator": "claude", "reviewed": false},
  {"id": "living-heredity-g8", "domain": "LIVING_THINGS", "topic": "heredity", "grades": [7, 8], "terms": ["heredity", "traits", "inherited", "parents", "genes", "magkakahawig", "magkapareho", "makapanunod", "ipinapasa", "nagmamana", "ginikanan", "magulang", "ipasa", "gayod", "busa"], "fact": {"tl": "Sa heredity, ipinapasa ng mga magulang ang kanilang mga katangian (traits) sa kanilang anak sa pamamagitan ng genes. Kaya nagmamana ang anak ng mga katangian tulad ng kulay ng mata o hugis ng dahon — kaya magkakahawig ang magulang at anak pero hindi magkapareho.", "en": "In heredity, parents pass their traits to their offspring through genes. That is why offspring inherit traits like eye color or leaf shape — so parents and offspring resemble each other but are not identical.", "bis": "Sa heredity, ipasa sa mga ginikanan ang ilang mga kinaiya (traits) ngadto sa ilang anak pinaagi sa genes. Mao nga makapanunod ang anak og mga kinaiya sama sa kolor sa mata o porma sa dahon — busa magkapareho ang ginikanan ug anak apan dili managsama gayod."}, "source": "NRC LS3.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-plant-reproduction-g6", "domain": "LIVING_THINGS", "topic": "plant reproduction", "grades": [6, 7], "terms": ["pollination", "seed", "flower", "fruit", "nagpapakalat", "inililipat", "nagtatago", "putyokan", "ibalhin", "tumubo", "nagpaparami", "mosanay", "bubuyog", "minsan"], "fact": {"tl": "Maraming halaman ang nagpaparami sa pamamagitan ng mga buto (seeds). Sa pollination, inililipat ng hangin o insekto (tulad ng bubuyog) ang pollen sa bulaklak. Pagkatapos nito, nabubuo ang buto at minsan ay prutas na nagtatago at nagpapakalat sa buto para tumubo ang bagong halaman.", "en": "Many plants reproduce through seeds. In pollination, wind or insects (like bees) move pollen on a flower. After this, a seed forms — sometimes inside a fruit that protects and spreads the seed so a new plant can grow.", "bis": "Daghang tanom ang mosanay pinaagi sa mga liso (seeds). Sa pollination, ibalhin sa hangin o insekto (sama sa putyokan) ang pollen sa bulak. Human niini, maporma ang liso ug usahay prutas nga manalipod ug mokatag sa liso aron motubo ang bag-ong tanom."}, "source": "AAAS BSL Ch.5; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "living-microorganisms-g7", "domain": "LIVING_THINGS", "topic": "microorganisms", "grades": [7, 8], "terms": ["microorganism", "bacteria", "virus", "microscope", "nakakatulong", "nakakasakit", "trangkaso", "pagdurog", "kondili", "kundi", "makapasakit", "paggawa", "paghimo", "pagguba"], "fact": {"tl": "Ang microorganisms ay napakaliliit na buhay na bagay na hindi nakikita ng mata kundi sa pamamagitan lang ng microscope, tulad ng bacteria at fungi. May nakakatulong sa kanila (halimbawa, paggawa ng yogurt o pagdurog ng patay na bagay) at may nakakasakit. Ang virus ay mas maliit pa at nagdudulot ng sakit tulad ng trangkaso.", "en": "Microorganisms are tiny living things seen only through a microscope, like bacteria and fungi. Some are helpful (e.g., making yogurt or breaking down dead matter) and some cause disease. A virus is even smaller and causes illnesses like the flu.", "bis": "Ang microorganisms mao ang gagmay kaayo nga buhi nga butang nga dili makita sa mata kondili pinaagi lang sa microscope, sama sa bacteria ug fungi. Adunay makatabang kanila (pananglitan, paghimo og yogurt o pagguba sa patay nga butang) ug adunay makapasakit. Ang virus mas gamay pa ug maoy hinungdan sa sakit sama sa trangkaso."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-biodiversity-g8", "domain": "LIVING_THINGS", "topic": "biodiversity", "grades": [7, 8], "terms": ["biodiversity", "species", "ecosystem", "balance", "pinakamayaman", "pagkalainlain", "bansang", "nasod", "magkakaiba", "matatag", "kapaligiran", "pagkakaiba", "lainlain", "dato"], "fact": {"tl": "Ang biodiversity ay ang dami at pagkakaiba-iba ng mga buhay na bagay sa isang lugar. Mahalaga ito dahil ang bawat species ay may papel sa ecosystem, at kapag mas magkakaiba-iba ang buhay, mas matatag at malusog ang kapaligiran. Ang Pilipinas ay isa sa mga bansang pinakamayaman sa biodiversity.", "en": "Biodiversity is the number and variety of living things in a place. It matters because each species has a role in the ecosystem, and the more varied the life, the more stable and healthy the environment. The Philippines is one of the most biodiversity-rich countries.", "bis": "Ang biodiversity mao ang gidaghanon ug pagkalainlain sa mga buhi nga butang sa usa ka dapit. Importante kini kay ang matag species adunay papel sa ecosystem, ug kung mas lainlain ang kinabuhi, mas lig-on ug himsog ang palibot. Ang Pilipinas usa sa mga nasod nga labing dato sa biodiversity."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "fme-motion-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "motion and position", "grades": [3, 4, 5], "terms": ["motion", "position", "reference", "distance", "nakatigil", "kaugnay", "kalabot", "posisyon", "poste", "dalan", "nagpahulay", "sasakyan", "sakyanan", "laing"], "fact": {"tl": "Ang isang bagay ay gumagalaw (in motion) kapag nagbabago ang posisyon nito kaugnay ng ibang bagay (reference point). Halimbawa, ang sasakyan ay gumagalaw kaugnay ng poste sa daan. Kapag hindi nagbabago ang posisyon, ito ay nakatigil (at rest).", "en": "An object is in motion when its position changes relative to another object (a reference point). For example, a car moves relative to a post on the road. When its position does not change, it is at rest.", "bis": "Ang usa ka butang naglihok (in motion) kung mausab ang posisyon niini kalabot sa laing butang (reference point). Pananglitan, ang sakyanan naglihok kalabot sa poste sa dalan. Kung wala mausab ang posisyon, kini nagpahulay (at rest)."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-speed-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "speed", "grades": [4, 5, 6], "terms": ["speed", "distance", "time", "fast", "nalalakbay", "nalakbay", "nabaktas", "takdang", "takna", "kabilis", "layong", "malayo", "oras", "parehong"], "fact": {"tl": "Ang speed ay kung gaano kabilis gumalaw ang isang bagay — ang layong (distance) nalakbay sa loob ng isang takdang oras (time). Mas mabilis ang isang bagay kung mas malayo ang nalalakbay nito sa parehong dami ng oras.", "en": "Speed is how fast an object moves — the distance it travels in a certain amount of time. An object is faster if it covers more distance in the same amount of time.", "bis": "Ang speed mao kung unsa ka paspas molihok ang usa ka butang — ang gilay-on (distance) nga nabaktas sulod sa usa ka takna nga oras (time). Mas paspas ang butang kung mas layo ang iyang nabaktas sa parehas nga gidaghanon sa oras."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction", "grades": [4, 5, 6], "terms": ["friction", "surface", "slow", "resist"], "fact": {"tl": "Ang friction ay isang force na sumasalungat sa galaw kapag may dalawang ibabaw (surface) na nagkikiskisan. Kaya humihinto o bumabagal ang gumugulong na bola. Mas malaki ang friction sa magaspang na ibabaw kaysa sa makinis o madulas.", "en": "Friction is a force that opposes motion when two surfaces rub together. That is why a rolling ball slows and stops. Friction is greater on rough surfaces than on smooth or slippery ones.", "bis": "Ang friction usa ka force nga mosupak sa paglihok kung adunay duha ka nawong (surface) nga nagkuskos. Mao nga mohunong o mohinay ang nagligid nga bola. Mas dako ang friction sa gansang nga nawong kaysa sa hamis o danlog."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-gravity-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity", "grades": [4, 5, 6], "terms": ["gravity", "weight", "fall", "Earth", "binitawan", "buhian", "nananatili", "kakusog", "bumabagsak", "humihila", "mobira", "gitna", "magpabilin", "lakas"], "fact": {"tl": "Ang gravity ay ang force na humihila ng mga bagay papunta sa gitna ng Earth. Kaya bumabagsak pababa ang mga bagay kapag binitawan, at kaya tayo nananatili sa lupa. Ang weight ay ang lakas ng hila ng gravity sa isang bagay.", "en": "Gravity is the force that pulls objects toward the center of the Earth. That is why things fall down when released, and why we stay on the ground. Weight is the strength of gravity's pull on an object.", "bis": "Ang gravity mao ang force nga mobira sa mga butang paingon sa tunga sa Earth. Mao nga mahulog paubos ang mga butang kung buhian, ug mao nga magpabilin ta sa yuta. Ang weight mao ang kakusog sa bira sa gravity sa usa ka butang."}, "source": "NRC PS2.B; AAAS BSL Ch.4B/4F", "generator": "claude", "reviewed": false},
  {"id": "fme-simple-machines-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "simple machines", "grades": [5, 6], "terms": ["simple machine", "lever", "pulley", "inclined plane", "work", "nagpapadali", "makapasayon", "kagamitang", "sahaganan", "pakalmot", "trabaho", "dahilig", "palakol", "himan", "atsa"], "fact": {"tl": "Ang simple machines ay mga kagamitang nagpapadali ng trabaho sa pamamagitan ng pagbabago ng laki o direksyon ng force. Anim ang uri: lever (tulad ng seesaw), pulley, inclined plane (dahilig), wheel and axle, wedge (pakalmot tulad ng palakol), at screw.", "en": "Simple machines are tools that make work easier by changing the size or direction of a force. There are six kinds: lever (like a seesaw), pulley, inclined plane (ramp), wheel and axle, wedge (like an axe), and screw.", "bis": "Ang simple machines mga himan nga makapasayon sa trabaho pinaagi sa pag-usab sa gidak-on o direksyon sa force. Unom ka klase: lever (sama sa seesaw), pulley, inclined plane (sahaganan), wheel and axle, wedge (sama sa atsa), ug screw."}, "source": "DepEd Science CG (FME); AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "fme-energy-forms-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "forms of energy", "grades": [4, 5, 6], "terms": ["energy", "heat", "light", "sound", "electrical", "mechanical", "kakayahang", "magpagalaw", "magpabago", "gasolina", "katakos", "pagbag", "nakaimbak", "natipig", "paglihok", "anyo"], "fact": {"tl": "Ang energy ay ang kakayahang magpagalaw o magpabago ng bagay. May iba't ibang anyo ito: heat (init), light (liwanag), sound (tunog), electrical (kuryente), mechanical (galaw), at chemical (nakaimbak sa pagkain at gasolina).", "en": "Energy is the ability to make things move or change. It comes in different forms: heat, light, sound, electrical, mechanical (motion), and chemical (stored in food and fuel).", "bis": "Ang energy mao ang katakos sa paglihok o pagbag-o sa butang. Adunay nagkalainlaing porma kini: heat (kainit), light (kahayag), sound (tingog), electrical (kuryente), mechanical (lihok), ug chemical (natipig sa pagkaon ug gasolina)."}, "source": "NRC PS3.A; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-kinetic-potential-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kinetic and potential energy", "grades": [6, 7, 8], "terms": ["kinetic energy", "potential energy", "stored", "motion", "tumatakbong", "gumulong", "nagdagan", "moligid", "kalagayan", "posisyon", "bungtod", "tuktok", "burol", "nakaimbak"], "fact": {"tl": "Ang kinetic energy ay ang energy ng isang bagay na gumagalaw (halimbawa, tumatakbong bata). Ang potential energy ay ang nakaimbak na energy dahil sa posisyon o kalagayan ng bagay (halimbawa, bato sa tuktok ng burol bago ito gumulong pababa).", "en": "Kinetic energy is the energy of a moving object (e.g., a running child). Potential energy is stored energy due to an object's position or condition (e.g., a rock at the top of a hill before it rolls down).", "bis": "Ang kinetic energy mao ang energy sa naglihok nga butang (pananglitan, nagdagan nga bata). Ang potential energy mao ang natipig nga energy tungod sa posisyon o kahimtang sa butang (pananglitan, bato sa tumoy sa bungtod sa wala pa kini moligid paubos)."}, "source": "NRC PS3.A; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-energy-conservation-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transformation", "grades": [7, 8], "terms": ["energy transformation", "conservation of energy", "nalilikha", "nananatiling", "kinatibuk", "kabuuang", "tapos", "baterya", "dayon", "nawawala", "parehas", "anyo"], "fact": {"tl": "Hindi nalilikha o nawawala ang energy — nagbabago lang ito ng anyo (energy transformation). Halimbawa, sa flashlight, ang chemical energy ng baterya ay nagiging electrical energy, tapos light at heat. Nananatiling pareho ang kabuuang dami ng energy.", "en": "Energy is not created or destroyed — it only changes form (energy transformation). For example, in a flashlight the battery's chemical energy becomes electrical energy, then light and heat. The total amount of energy stays the same.", "bis": "Dili mahimo o mawala ang energy — mausab lang kini og porma (energy transformation). Pananglitan, sa flashlight, ang chemical energy sa baterya mahimong electrical energy, dayon light ug heat. Magpabilin nga parehas ang kinatibuk-ang gidaghanon sa energy."}, "source": "NRC PS3.B; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-heat-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat transfer", "grades": [6, 7], "terms": ["heat", "conduction", "convection", "radiation", "kumukulong", "kutsarang", "dikitang", "pagdikit", "nagbukal", "kutsara", "sopas", "sabaw", "paraan", "paagi"], "fact": {"tl": "Ang init (heat) ay dumadaloy mula sa mas mainit papunta sa mas malamig sa tatlong paraan: conduction (sa pamamagitan ng dikitang tulad ng kutsarang umiinit sa mainit na sopas), convection (sa pamamagitan ng gumagalaw na likido o gas tulad ng kumukulong tubig), at radiation (sa pamamagitan ng sinag tulad ng init ng araw).", "en": "Heat flows from hotter to cooler in three ways: conduction (through contact, like a spoon heating in hot soup), convection (through moving liquid or gas, like boiling water), and radiation (through rays, like the sun's warmth).", "bis": "Ang kainit (heat) moagos gikan sa mas init paingon sa mas bugnaw sa tulo ka paagi: conduction (pinaagi sa pagdikit sama sa kutsara nga moinit sa init nga sabaw), convection (pinaagi sa naglihok nga likido o gas sama sa nagbukal nga tubig), ug radiation (pinaagi sa silaw sama sa kainit sa adlaw)."}, "source": "NRC PS3.B; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-light-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "light", "grades": [4, 5, 6], "terms": ["light", "reflection", "shadow", "straight line", "napakabilis", "nakakakita", "maharang", "puwede", "line", "mabalik", "tuwid", "makakita", "motama", "anino"], "fact": {"tl": "Ang light ay isang anyo ng energy na naglalakbay nang tuwid (straight line). Kapag tumama ito sa bagay, puwede itong mabalik (reflection) — kaya tayo nakakakita; o maharang — kaya nabubuo ang anino (shadow). Naglalakbay nang napakabilis ang liwanag.", "en": "Light is a form of energy that travels in straight lines. When it hits an object it can bounce back (reflection) — which is how we see — or be blocked, which forms a shadow. Light travels extremely fast.", "bis": "Ang light usa ka porma sa energy nga mobaktas nga tul-id (straight line). Kung motama kini sa butang, mahimo kining mobalik (reflection) — mao nga makakita ta; o ma-ali — mao nga maporma ang anino (shadow). Mobaktas og paspas kaayo ang kahayag."}, "source": "NRC PS4.B; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound", "grades": [4, 5, 6], "terms": ["sound", "vibration", "pitch", "loudness", "paggalaw", "malaki", "naglalakbay", "dalunggan", "mobaktas", "tainga", "pabalik", "lihok", "tingog", "tunog"], "fact": {"tl": "Ang sound (tunog) ay nabubuo ng vibration (paggalaw pabalik-balik) ng isang bagay, at naglalakbay ito sa hangin, tubig, o solid papunta sa ating tainga. Mas mataas ang pitch kapag mas mabilis ang vibration; mas malakas ang tunog kapag mas malaki ang vibration.", "en": "Sound is made by the vibration (back-and-forth movement) of an object, and it travels through air, water, or solids to our ears. The pitch is higher when the vibration is faster; the sound is louder when the vibration is bigger.", "bis": "Ang sound (tingog) maporma sa vibration (lihok balik-balik) sa usa ka butang, ug mobaktas kini sa hangin, tubig, o solid paingon sa atong dalunggan. Mas taas ang pitch kung mas paspas ang vibration; mas kusog ang tingog kung mas dako ang vibration."}, "source": "NRC PS4.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-electricity-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "electricity and circuits", "grades": [5, 6, 7], "terms": ["electricity", "circuit", "conductor", "insulator", "kaluwasan", "saradong", "sirado", "nagpapadaloy", "ligtas", "goma", "magpadala", "labas", "wire", "plastik"], "fact": {"tl": "Dumadaloy ang kuryente (electric current) sa isang saradong circuit. Ang conductors (tulad ng metal) ay nagpapadaloy ng kuryente; ang insulators (tulad ng goma at plastik) ay hindi. Kaya ang mga wire ay metal sa loob at goma sa labas para ligtas.", "en": "Electric current flows through a closed circuit. Conductors (like metal) let electricity flow; insulators (like rubber and plastic) do not. That is why wires are metal inside and rubber outside, for safety.", "bis": "Moagos ang kuryente (electric current) sa usa ka sirado nga circuit. Ang conductors (sama sa metal) magpadala og kuryente; ang insulators (sama sa goma ug plastik) dili. Mao nga ang mga wire metal sa sulod ug goma sa gawas alang sa kaluwasan."}, "source": "NRC PS3.A; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-magnetism-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetism", "grades": [4, 5, 6], "terms": ["magnet", "poles", "attract", "repel", "magkaparehong", "naghihilahan", "nagtutulakan", "magkaparehas", "magtuloday", "magbiraay", "magkasumpaki", "magkaibang", "dulo", "tumoy"], "fact": {"tl": "Ang magnet ay humihila (attract) ng mga bagay na gawa sa bakal o iron. May dalawang dulo ito na tinatawag na poles (north at south). Ang magkaibang poles ay naghihilahan (attract), pero ang magkaparehong poles ay nagtutulakan (repel).", "en": "A magnet attracts objects made of iron. It has two ends called poles (north and south). Opposite poles attract each other, but like poles push each other away (repel).", "bis": "Ang magnet mobira (attract) sa mga butang nga hinimo sa puthaw o iron. Adunay duha kini ka tumoy nga gitawag og poles (north ug south). Ang magkasumpaki nga poles magbiraay (attract), apan ang magkaparehas nga poles magtuloday (repel)."}, "source": "NRC PS2.B; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-balanced-unbalanced-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "balanced and unbalanced forces", "grades": [8, 9, 10], "terms": ["balanced force", "unbalanced force", "Newton", "acceleration", "magkapantay", "lumiliko", "batayan", "basihan", "hunong", "moliko", "balaod", "tigil", "batas", "magkasalungat"], "fact": {"tl": "Kapag balanced (magkapantay at magkasalungat) ang mga force sa isang bagay, hindi nagbabago ang galaw nito — nananatiling tigil o pareho ang bilis. Kapag unbalanced (may panig na mas malakas), nagbabago ang galaw: bumibilis, bumabagal, o lumiliko. Ito ang batayan ng mga batas ni Newton.", "en": "When the forces on an object are balanced (equal and opposite), its motion does not change — it stays still or keeps the same speed. When forces are unbalanced (one side stronger), the motion changes: it speeds up, slows down, or turns. This is the basis of Newton's laws.", "bis": "Kung balanced (managsama ug magkasumpaki) ang mga force sa usa ka butang, dili mausab ang lihok niini — magpabilin nga hunong o parehas ang katulin. Kung unbalanced (adunay kilid nga mas kusog), mausab ang lihok: mopaspas, mohinay, o moliko. Mao kini ang basihan sa mga balaod ni Newton."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-work-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "work", "grades": [8, 9, 10], "terms": ["work", "force", "distance", "energy", "nagpagalaw", "naglilipat", "nagaganap", "magbalhin", "nagagawa", "itinulak", "kalakas", "nabuhat", "makapalihok", "paggawa"], "fact": {"tl": "Sa science, may work na nagaganap kapag ang isang force ay nagpagalaw ng bagay sa isang layo (distance) sa direksyon ng force. Kung hindi gumalaw ang bagay, walang work na nagagawa kahit gaano kalakas ang itinulak mo. Ang paggawa ng work ay naglilipat ng energy.", "en": "In science, work is done when a force moves an object over a distance in the direction of the force. If the object does not move, no work is done no matter how hard you push. Doing work transfers energy.", "bis": "Sa science, adunay work nga mahitabo kung ang usa ka force makapalihok sa butang sa usa ka gilay-on (distance) sa direksyon sa force. Kung wala molihok ang butang, walay work nga nabuhat bisan unsa ka kusog ang imong gitulod. Ang paghimo og work magbalhin og energy."}, "source": "NRC PS3.C; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "earth-weather-climate-g4", "domain": "EARTH_SPACE", "topic": "weather and climate", "grades": [4, 5, 6], "terms": ["weather", "climate", "temperature", "rainfall", "himpapawid", "kahanginan", "kalagayan", "naandang", "ting", "karaniwang", "kahimtang", "mahabang", "klima", "taon"], "fact": {"tl": "Ang weather (panahon) ay ang kalagayan ng himpapawid sa isang araw — init, ulan, hangin, ulap. Ang climate (klima) ay ang karaniwang weather ng isang lugar sa mahabang panahon. Halimbawa, ang Pilipinas ay may tropical na climate: mainit buong taon, may tag-init at tag-ulan.", "en": "Weather is the state of the air on a given day — heat, rain, wind, clouds. Climate is the usual weather of a place over a long time. For example, the Philippines has a tropical climate: hot all year, with a dry season and a rainy season.", "bis": "Ang weather (panahon) mao ang kahimtang sa kahanginan sa usa ka adlaw — init, ulan, hangin, panganod. Ang climate (klima) mao ang naandang weather sa usa ka dapit sa taas nga panahon. Pananglitan, ang Pilipinas adunay tropical nga climate: init tibuok tuig, adunay ting-init ug ting-ulan."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-soil-g4", "domain": "EARTH_SPACE", "topic": "rocks and soil", "grades": [4, 5], "terms": ["soil", "rock", "sand", "clay", "humus", "pagpatubo", "hinaluan", "magtanim", "kolonon", "dugmok", "bulok", "luwad", "dunot", "kakayahang", "katakos"], "fact": {"tl": "Ang lupa (soil) ay nabubuo sa mahabang panahon mula sa durog na bato na hinaluan ng bulok na halaman at hayop (humus). May iba't ibang uri ang lupa tulad ng buhangin (sandy), luwad (clay), at loam, at iba-iba ang kakayahang magtanim dahil sa laki ng butil at sustansya.", "en": "Soil forms over a long time from broken-down rock mixed with decayed plants and animals (humus). There are different kinds of soil such as sandy, clay, and loam, and they differ in how well plants grow because of particle size and nutrients.", "bis": "Ang yuta (soil) maporma sa taas nga panahon gikan sa dugmok nga bato nga gisagolan og dunot nga tanom ug hayop (humus). Adunay nagkalainlaing klase ang yuta sama sa balas (sandy), kolonon (clay), ug loam, ug lainlain ang katakos sa pagpatubo tungod sa gidak-on sa lugas ug sustansya."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-rock-cycle-g6", "domain": "EARTH_SPACE", "topic": "types of rocks", "grades": [6, 7], "terms": ["igneous", "sedimentary", "metamorphic", "rock cycle", "nibugnaw", "tumigas", "magbago", "natapok", "nabago", "nigahi", "nausab", "putik", "napakahabang", "naipong"], "fact": {"tl": "May tatlong uri ng bato: igneous (mula sa lumamig na lava o magma), sedimentary (mula sa naipong layer ng buhangin at putik na tumigas), at metamorphic (bato na nabago dahil sa init at presyon). Sa rock cycle, puwedeng magbago ang isang uri ng bato sa iba sa napakahabang panahon.", "en": "There are three kinds of rock: igneous (from cooled lava or magma), sedimentary (from layers of sand and mud that hardened), and metamorphic (rock changed by heat and pressure). In the rock cycle, one kind can change into another over very long times.", "bis": "Adunay tulo ka klase sa bato: igneous (gikan sa nibugnaw nga lava o magma), sedimentary (gikan sa natapok nga layer sa balas ug lapok nga nigahi), ug metamorphic (bato nga nausab tungod sa kainit ug presyur). Sa rock cycle, mahimong mausab ang usa ka klase sa bato ngadto sa lain sa taas kaayo nga panahon."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-weathering-erosion-g5", "domain": "EARTH_SPACE", "topic": "weathering and erosion", "grades": [5, 6], "terms": ["weathering", "erosion", "wind", "water", "pagkadugmok", "pagkadurog", "nadugmok", "nagaagas", "pagbalhin", "paglipat", "paglipas", "paglabay", "durog", "lamig"], "fact": {"tl": "Ang weathering ay ang unti-unting pagkadurog ng bato sa maliliit na piraso dahil sa tubig, hangin, init, at lamig. Ang erosion naman ay ang paglipat ng mga durog na bato at lupa papunta sa ibang lugar dahil sa umaagos na tubig, hangin, o yelo. Kaya nagbabago ang hugis ng lupa sa paglipas ng panahon.", "en": "Weathering is the slow breaking of rock into smaller pieces by water, wind, heat, and cold. Erosion is the moving of broken rock and soil to other places by flowing water, wind, or ice. This is why the shape of the land changes over time.", "bis": "Ang weathering mao ang hinay-hinay nga pagkadugmok sa bato ngadto sa gagmay nga piraso tungod sa tubig, hangin, init, ug bugnaw. Ang erosion mao ang pagbalhin sa nadugmok nga bato ug yuta ngadto sa laing dapit tungod sa nagaagas nga tubig, hangin, o yelo. Mao nga mausab ang porma sa yuta sa paglabay sa panahon."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-landforms-g4", "domain": "EARTH_SPACE", "topic": "landforms", "grades": [4, 5], "terms": ["landform", "mountain", "valley", "plain", "plateau"], "fact": {"tl": "Ang landforms ay ang iba't ibang hugis ng ibabaw ng lupa: bundok (mountain), lambak (valley), kapatagan (plain), talampas (plateau), at burol (hill). Nabubuo ang mga ito sa napakahabang panahon dahil sa galaw ng Earth, bulkan, at weathering at erosion.", "en": "Landforms are the different shapes of the land's surface: mountains, valleys, plains, plateaus, and hills. They form over very long times because of the Earth's movements, volcanoes, and weathering and erosion.", "bis": "Ang landforms mao ang nagkalainlaing porma sa nawong sa yuta: bukid (mountain), walog (valley), kapatagan (plain), talampas (plateau), ug bungtod (hill). Maporma kini sa taas kaayo nga panahon tungod sa lihok sa Earth, bulkan, ug weathering ug erosion."}, "source": "NRC ESS2.B; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-plate-tectonics-g7", "domain": "EARTH_SPACE", "topic": "earthquakes and volcanoes", "grades": [7, 8], "terms": ["plate tectonics", "earthquake", "volcano", "fault"], "fact": {"tl": "Ang panlabas na bahagi ng Earth ay nahahati sa malalaking piraso na tinatawag na plates na dahan-dahang gumagalaw. Kapag nagkiskisan o nagbanggaan ang mga plate, nagkakaroon ng lindol (earthquake) at bulkan (volcano). Ang Pilipinas ay nasa Pacific Ring of Fire kaya madalas itong magkalindol at may maraming bulkan.", "en": "The Earth's outer layer is broken into large pieces called plates that move slowly. When plates rub or collide, earthquakes and volcanoes occur. The Philippines sits on the Pacific Ring of Fire, so it has frequent earthquakes and many volcanoes.", "bis": "Ang gawas nga bahin sa Earth nabahin sa dagkong piraso nga gitawag og plates nga hinay nga molihok. Kung magkuskos o magbangga ang mga plate, adunay linog (earthquake) ug bulkan (volcano). Ang Pilipinas anaa sa Pacific Ring of Fire mao nga kanunay kining maglinog ug daghang bulkan."}, "source": "NRC ESS2.B; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-structure-g7", "domain": "EARTH_SPACE", "topic": "earth's structure", "grades": [7, 8], "terms": ["crust", "mantle", "core", "layers", "kinatatayuan", "pinakaloob", "gibarogan", "malagkit", "kinasuloran", "napakainit", "panlabas", "pangunahing", "matigas", "layer"], "fact": {"tl": "Ang Earth ay may tatlong pangunahing layer: ang crust (ang manipis at matigas na panlabas na balat na kinatatayuan natin), ang mantle (mainit at malagkit na bato sa ilalim), at ang core (ang pinakaloob, gawa sa metal, na napakainit).", "en": "The Earth has three main layers: the crust (the thin, hard outer shell we live on), the mantle (hot, thick rock below it), and the core (the innermost part, made of metal, that is extremely hot).", "bis": "Ang Earth adunay tulo ka nag-unang layer: ang crust (ang nipis ug gahi nga gawas nga panit nga atong gibarogan), ang mantle (init ug baga nga bato sa ilalom), ug ang core (ang kinasuloran, hinimo sa metal, nga init kaayo)."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-atmosphere-g6", "domain": "EARTH_SPACE", "topic": "the atmosphere", "grades": [6, 7], "terms": ["atmosphere", "air", "oxygen", "layers", "nakakasamang", "pinipigilan", "naglangkob", "naglibot", "mopugong", "nakapaligid", "naglalaman", "hinihinga", "nagpoprotekta", "kabugnaw"], "fact": {"tl": "Ang atmosphere ay ang makapal na hangin na nakapaligid sa Earth. Naglalaman ito ng oxygen na hinihinga natin, pinipigilan ang sobrang init at lamig, at nagpoprotekta sa atin mula sa nakakasamang sinag ng araw. Nahahati ito sa mga layer.", "en": "The atmosphere is the thick layer of air surrounding the Earth. It holds the oxygen we breathe, keeps the planet from getting too hot or cold, and protects us from harmful rays of the sun. It is divided into layers.", "bis": "Ang atmosphere mao ang baga nga hangin nga naglibot sa Earth. Naglangkob kini og oxygen nga atong giginhawa, mopugong sa sobra nga kainit ug kabugnaw, ug manalipod kanato gikan sa makadaot nga silaw sa adlaw. Nabahin kini sa mga layer."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-solar-system-g4", "domain": "EARTH_SPACE", "topic": "solar system", "grades": [4, 5, 6], "terms": ["solar system", "planet", "sun", "orbit", "pinagmumulan", "tinubdan", "siyang", "gilangkoban", "binubuo", "walong", "walo", "bituin", "bituon", "planeta"], "fact": {"tl": "Ang solar system ay binubuo ng Araw (Sun) at ng walong planeta na umiikot (orbit) dito: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, at Neptune. Ang Araw ay isang bituin (star) na siyang pinagmumulan ng liwanag at init para sa atin.", "en": "The solar system is made of the Sun and the eight planets that orbit it: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune. The Sun is a star, and it is the source of our light and heat.", "bis": "Ang solar system gilangkoban sa Adlaw (Sun) ug sa walo ka planeta nga molibot (orbit) niini: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, ug Neptune. Ang Adlaw usa ka bituon (star) nga maoy tinubdan sa atong kahayag ug kainit."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-day-night-seasons-g5", "domain": "EARTH_SPACE", "topic": "day night and seasons", "grades": [4, 5, 6], "terms": ["rotation", "revolution", "day", "night", "seasons"], "fact": {"tl": "Umiikot (rotation) ang Earth sa sarili nitong axis isang beses kada araw — kaya may araw (day) sa bahaging nakaharap sa Araw at gabi (night) sa kabila. Umiikot din ito sa Araw (revolution) isang beses kada taon, at dahil sa pagkakatagilid ng Earth, nagkakaroon ng iba't ibang panahon (seasons).", "en": "The Earth rotates on its axis once a day — so there is daytime on the side facing the Sun and night on the other. It also revolves around the Sun once a year, and because the Earth is tilted, this causes the different seasons.", "bis": "Molibot (rotation) ang Earth sa kaugalingong axis niini kausa matag adlaw — mao nga adunay adlaw (day) sa bahin nga nag-atubang sa Adlaw ug gabii (night) sa pikas. Molibot usab kini sa Adlaw (revolution) kausa matag tuig, ug tungod sa pagkahilig sa Earth, adunay nagkalainlaing panahon (seasons)."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-moon-phases-g5", "domain": "EARTH_SPACE", "topic": "phases of the moon", "grades": [5, 6], "terms": ["moon", "phases", "reflect", "orbit", "naliliwanagang", "nabubuwelta", "nalamdagan", "kabilugan", "nibalik", "kalaki", "kadako", "takdol", "kalahati", "katunga"], "fact": {"tl": "Walang sariling liwanag ang buwan (moon) — ang nakikita nating liwanag nito ay sinag ng Araw na nabubuwelta dito. Habang umiikot ang buwan sa Earth, nagbabago kung gaano kalaki ang naliliwanagang bahagi na nakaharap sa atin — kaya may iba't ibang phases (bagong buwan, kalahati, kabilugan).", "en": "The Moon has no light of its own — the light we see from it is sunlight reflecting off it. As the Moon orbits the Earth, the lit part facing us changes in size — which is why it has phases (new moon, half, full).", "bis": "Walay kaugalingong kahayag ang bulan (moon) — ang atong makita nga kahayag niini kay silaw sa Adlaw nga nibalik niini. Samtang molibot ang bulan sa Earth, mausab kung unsa kadako ang nalamdagan nga bahin nga nag-atubang kanato — mao nga adunay nagkalainlaing phases (bag-ong bulan, katunga, takdol)."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-eclipses-g6", "domain": "EARTH_SPACE", "topic": "eclipses", "grades": [6, 7], "terms": ["eclipse", "solar", "lunar", "shadow", "nagkakahanay", "mongitngit", "umiilim", "magsa", "humaharang", "umaga", "moali", "tumatama", "motama", "anino"], "fact": {"tl": "Nagkakaroon ng eclipse kapag nagkakahanay ang Araw, Earth, at buwan. Sa solar eclipse, ang buwan ang humaharang sa Araw kaya umiilim ang araw sa umaga. Sa lunar eclipse, ang Earth ang nasa gitna kaya tumatama ang anino nito sa buwan.", "en": "An eclipse happens when the Sun, Earth, and Moon line up. In a solar eclipse, the Moon blocks the Sun, darkening the daytime. In a lunar eclipse, the Earth is in the middle, so its shadow falls on the Moon.", "bis": "Adunay eclipse kung magsa-ad ang Adlaw, Earth, ug bulan. Sa solar eclipse, ang bulan ang moali sa Adlaw mao nga mongitngit ang adlaw. Sa lunar eclipse, ang Earth ang anaa sa tunga mao nga motama ang anino niini sa bulan."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-stars-galaxies-g7", "domain": "EARTH_SPACE", "topic": "stars and galaxies", "grades": [7, 8], "terms": ["star", "galaxy", "universe", "light-year", "napakalalaking", "napakalaking", "nagdilaab", "bilyong", "bilyon", "aapoy", "dagko", "tila", "napakalayo", "nilang"], "fact": {"tl": "Ang mga bituin (stars) ay napakalalaking bola ng nag-aapoy na gas na naglalabas ng sarili nilang liwanag at init — tulad ng ating Araw. Ang galaxy ay napakalaking grupo ng bilyon-bilyong bituin; ang ating galaxy ay tinatawag na Milky Way. Napakalayo ng mga bituin kaya tila maliit lang sila sa langit.", "en": "Stars are enormous balls of burning gas that give off their own light and heat — like our Sun. A galaxy is a huge group of billions of stars; our galaxy is called the Milky Way. Stars are so far away that they look tiny in the sky.", "bis": "Ang mga bituon (stars) dagko kaayong bola sa nagdilaab nga gas nga mobuga sa ilang kaugalingong kahayag ug kainit — sama sa atong Adlaw. Ang galaxy dako kaayong grupo sa bilyon-bilyon ka bituon; ang atong galaxy gitawag og Milky Way. Layo kaayo ang mga bituon mao nga morag gagmay lang sila sa langit."}, "source": "NRC ESS1.A; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-natural-resources-g5", "domain": "EARTH_SPACE", "topic": "natural resources", "grades": [5, 6], "terms": ["natural resources", "renewable", "nonrenewable", "conservation", "nababalik", "dali", "kinaiyahan", "kalikasan", "mineral", "nauubos", "mahurot", "mabalik", "iingat", "amping"], "fact": {"tl": "Ang natural resources ay ang mga bagay mula sa kalikasan na ginagamit natin: tubig, hangin, lupa, kahoy, at mineral. May renewable na nababalik (tulad ng araw at hangin) at may nonrenewable na nauubos at hindi agad nababalik (tulad ng langis at karbon). Kaya mahalaga ang pag-iingat (conservation).", "en": "Natural resources are things from nature that we use: water, air, soil, wood, and minerals. Some are renewable and replenish (like sun and wind), and some are nonrenewable and run out and are not easily replaced (like oil and coal). That is why conservation matters.", "bis": "Ang natural resources mao ang mga butang gikan sa kinaiyahan nga atong gigamit: tubig, hangin, yuta, kahoy, ug mineral. Adunay renewable nga mobalik (sama sa adlaw ug hangin) ug adunay nonrenewable nga mahurot ug dili dali mabalik (sama sa lana ug karbon). Mao nga importante ang pag-amping (conservation)."}, "source": "NRC ESS3.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-climate-change-g8", "domain": "EARTH_SPACE", "topic": "climate change", "grades": [8, 9, 10], "terms": ["climate change", "greenhouse effect", "carbon dioxide", "global warming", "nagpapanatiling", "matinding", "maghupot", "mokusog", "grabe", "lumalakas", "umiinit", "karbon", "kalibutan", "pagsunog"], "fact": {"tl": "Ang ilang gas sa atmosphere (tulad ng carbon dioxide) ay humuhuli ng init mula sa araw — ang greenhouse effect, na nagpapanatiling mainit-init ang Earth. Pero dahil sa sobrang carbon dioxide mula sa pagsunog ng langis at karbon ng tao, lumalakas ito at unti-unting umiinit ang mundo (climate change), na nagdudulot ng mas matinding panahon.", "en": "Some gases in the atmosphere (like carbon dioxide) trap heat from the sun — the greenhouse effect, which keeps the Earth warm. But because of too much carbon dioxide from humans burning oil and coal, this strengthens and the world slowly warms (climate change), causing more extreme weather.", "bis": "Ang ubang gas sa atmosphere (sama sa carbon dioxide) modakop og kainit gikan sa adlaw — ang greenhouse effect, nga maghupot sa Earth nga init-init. Apan tungod sa sobra nga carbon dioxide gikan sa pagsunog sa lana ug karbon sa tawo, mokusog kini ug hinay-hinay nga moinit ang kalibutan (climate change), nga maghatag og mas grabe nga panahon."}, "source": "NRC ESS3.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "val-water-boiling-freezing", "domain": "MATTER", "topic": "boiling and freezing point of water", "grades": [4, 5, 6], "terms": ["boiling point", "freezing point", "water", "temperature", "Celsius", "Fahrenheit", "tabing", "kumukulo", "naandang", "mobukal", "karaniwang", "baybayon", "purong", "putli", "nagyeyelo", "dagat"], "fact": {"tl": "Ang purong tubig ay kumukulo sa 100°C (212°F) at nagyeyelo sa 0°C (32°F) sa karaniwang air pressure sa tabing-dagat.", "en": "Pure water boils at 100°C (212°F) and freezes at 0°C (32°F) at normal sea-level air pressure.", "bis": "Ang putli nga tubig mobukal sa 100°C (212°F) ug mo-yelo sa 0°C (32°F) sa naandang air pressure sa baybayon."}, "source": "AAAS BSL Ch.4D (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-temperature-scales", "domain": "MATTER", "topic": "temperature scales", "grades": [6, 7, 8], "terms": ["temperature", "Celsius", "Fahrenheit", "convert", "sinusukat", "kumukulo", "gisukod", "mobukal", "nagyeyelo", "temperatura", "yelo"], "fact": {"tl": "Sinusukat ang temperatura sa Celsius (°C) o Fahrenheit (°F). Ang tubig ay nagyeyelo sa 0°C = 32°F at kumukulo sa 100°C = 212°F.", "en": "Temperature is measured in Celsius (°C) or Fahrenheit (°F). Water freezes at 0°C = 32°F and boils at 100°C = 212°F.", "bis": "Gisukod ang temperatura sa Celsius (°C) o Fahrenheit (°F). Ang tubig mo-yelo sa 0°C = 32°F ug mobukal sa 100°C = 212°F."}, "source": "AAAS BSL Ch.4D (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-room-temperature", "domain": "MATTER", "topic": "room temperature", "grades": [4, 5, 6], "terms": ["room temperature", "temperature", "komportableng", "komportable"], "fact": {"tl": "Ang komportableng room temperature ay mga 20–25°C (68–77°F).", "en": "Comfortable room temperature is about 20–25°C (68–77°F).", "bis": "Ang komportable nga room temperature mga 20–25°C (68–77°F)."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-air-composition", "domain": "EARTH_SPACE", "topic": "composition of air", "grades": [5, 6, 7], "terms": ["air", "nitrogen", "oxygen", "atmosphere", "hinihinga", "giginhawa", "mabuhay", "karamihan", "mabuhi", "kasagaran", "ubang", "gigamit", "ginagamit", "ibang"], "fact": {"tl": "Ang hangin na hinihinga natin ay karamihan nitrogen (mga 78%) at oxygen (mga 21%); mga 1% na lang ang ibang gas. Ang oxygen ang ginagamit natin para mabuhay.", "en": "The air we breathe is mostly nitrogen (about 78%) and oxygen (about 21%); only about 1% is other gases. We use the oxygen to live.", "bis": "Ang hangin nga atong giginhawa kasagaran nitrogen (mga 78%) ug oxygen (mga 21%); mga 1% na lang ang ubang gas. Ang oxygen ang atong gigamit aron mabuhi."}, "source": "AAAS BSL Ch.4B (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-body-temperature", "domain": "LIVING_THINGS", "topic": "body temperature", "grades": [4, 5, 6], "terms": ["body temperature", "fever", "health", "temperaturang", "hilanat", "lagnat", "malusog", "himsog", "temperatura", "mataas", "tawo", "tinatawag", "gitawag"], "fact": {"tl": "Ang malusog na temperatura ng katawan ng tao ay mga 37°C (98.6°F). Ang temperaturang mas mataas dito ay tinatawag na lagnat (fever).", "en": "A healthy human body temperature is about 37°C (98.6°F). A temperature much higher than this is a fever.", "bis": "Ang himsog nga temperatura sa lawas sa tawo mga 37°C (98.6°F). Ang temperatura nga mas taas pa niini gitawag og hilanat (fever)."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-human-bones", "domain": "LIVING_THINGS", "topic": "number of bones", "grades": [4, 5, 6], "terms": ["bones", "skeleton", "body", "ipinapanganak", "nagsasanib", "magtapot", "sanggol", "masuso", "natawo", "ilan", "matandang", "bukog", "hamtong"], "fact": {"tl": "Ang katawan ng matandang tao ay may 206 na buto. Ang mga sanggol ay ipinapanganak na may mga 300 na buto, at ang ilan ay nagsasanib habang lumalaki.", "en": "An adult human body has 206 bones. Babies are born with about 300, and some fuse together as they grow.", "bis": "Ang lawas sa hamtong nga tawo adunay 206 ka bukog. Ang mga masuso natawo nga adunay mga 300 ka bukog, ug ang uban magtapot samtang motubo."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-human-teeth", "domain": "LIVING_THINGS", "topic": "number of teeth", "grades": [3, 4, 5], "terms": ["teeth", "milk teeth", "permanent teeth", "permanenteng", "permanente", "matatanda", "kasama", "ngipin", "ngipon", "gatas", "lakip", "bata", "hamtong"], "fact": {"tl": "Ang mga bata ay may 20 na gatas na ngipin (milk teeth); ang matatanda ay may 32 na permanenteng ngipin (kasama ang wisdom teeth).", "en": "Children have 20 milk teeth; adults have 32 permanent teeth (including the wisdom teeth).", "bis": "Ang mga bata adunay 20 ka gatas nga ngipon (milk teeth); ang mga hamtong adunay 32 ka permanente nga ngipon (lakip ang wisdom teeth)."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-heart-rate", "domain": "LIVING_THINGS", "topic": "heart rate", "grades": [5, 6, 7], "terms": ["heart rate", "pulse", "beats per minute", "tumitibok", "mopitik", "nakapahingang", "tibok", "pitik", "kasingkasing", "nagpahulay", "matanda", "minuto", "puso"], "fact": {"tl": "Ang puso ng nakapahingang matanda ay tumitibok nang mga 60–100 beses kada minuto; mas mabilis ang tibok ng puso ng bata.", "en": "A resting adult heart beats about 60–100 times per minute; a child's heart beats faster.", "bis": "Ang kasingkasing sa nagpahulay nga hamtong mopitik mga 60–100 ka beses kada minuto; mas paspas ang pitik sa kasingkasing sa bata."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-breathing-rate", "domain": "LIVING_THINGS", "topic": "breathing rate", "grades": [5, 6, 7], "terms": ["breathing rate", "respiration", "nakapahingang", "nagpahulay", "minuto", "humihinga", "moginhawa", "beses", "kada", "tawo"], "fact": {"tl": "Ang nakapahingang tao ay humihinga nang mga 12–20 beses kada minuto.", "en": "A resting person breathes about 12–20 times per minute.", "bis": "Ang nagpahulay nga tawo moginhawa mga 12–20 ka beses kada minuto."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-body-water", "domain": "LIVING_THINGS", "topic": "body is mostly water", "grades": [4, 5, 6], "terms": ["water", "body", "percent", "napakahalaga", "mahigit", "kapin", "inom", "kalahati", "katunga", "matandang", "hamtong", "importante", "tawo"], "fact": {"tl": "Mga 60% ng katawan ng matandang tao ay tubig — mahigit kalahati! Kaya napakahalaga ng pag-inom ng tubig.", "en": "About 60% of an adult human body is water — more than half! That is why drinking water is so important.", "bis": "Mga 60% sa lawas sa hamtong nga tawo kay tubig — kapin sa katunga! Mao nga importante kaayo ang pag-inom og tubig."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-blood-volume", "domain": "LIVING_THINGS", "topic": "blood volume", "grades": [6, 7], "terms": ["blood", "liters", "body", "litro", "matandang", "hamtong", "dugo", "tawo"], "fact": {"tl": "Ang katawan ng matandang tao ay may mga 5 litro ng dugo.", "en": "An adult human body has about 5 liters of blood.", "bis": "Ang lawas sa hamtong nga tawo adunay mga 5 ka litro nga dugo."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-largest-organ-skin", "domain": "LIVING_THINGS", "topic": "largest organ", "grades": [5, 6], "terms": ["skin", "organ", "largest", "pinoprotektahan", "pinakamalaking", "pagkontrol", "makabati", "paghikap", "kinadak", "hipo", "pakiramdam", "magtugot", "temperatura"], "fact": {"tl": "Ang balat ang pinakamalaking organ ng katawan. Pinoprotektahan nito ang katawan, tumutulong sa pagkontrol ng temperatura, at nagbibigay-daan sa pakiramdam ng hipo.", "en": "The skin is the body's largest organ. It protects the body, helps control temperature, and lets us feel touch.", "bis": "Ang panit mao ang kinadak-ang organ sa lawas. Manalipod kini sa lawas, motabang sa pagkontrol sa temperatura, ug magtugot kanato nga makabati sa paghikap."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-speed-of-light", "domain": "FORCE_MOTION_ENERGY", "topic": "speed of light", "grades": [6, 7, 8], "terms": ["speed of light", "fast", "kilometers", "pinakamabilis", "sansinukob", "uniberso", "milya", "segundo", "kilometro", "labing", "naglalakbay", "mobaktas", "kada"], "fact": {"tl": "Ang liwanag ay naglalakbay nang mga 300,000 kilometro kada segundo (mga 186,000 milya kada segundo) — ang pinakamabilis sa buong sansinukob.", "en": "Light travels about 300,000 kilometers per second (about 186,000 miles per second) — the fastest thing in the universe.", "bis": "Ang kahayag mobaktas mga 300,000 ka kilometro kada segundo (mga 186,000 ka milya kada segundo) — ang labing paspas sa tibuok uniberso."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-speed-of-sound", "domain": "FORCE_MOTION_ENERGY", "topic": "speed of sound", "grades": [6, 7, 8], "terms": ["speed of sound", "thunder", "lightning", "marinig", "metro", "dalugdog", "segundo", "nauuna", "kulog", "madungog", "naglalakbay", "mobaktas", "kidlat"], "fact": {"tl": "Ang tunog ay naglalakbay sa hangin nang mga 343 metro kada segundo (mga 1,235 km/h) — mas mabagal kaysa liwanag, kaya nauuna mong makita ang kidlat bago marinig ang kulog.", "en": "Sound travels through air at about 343 meters per second (about 1,235 km/h) — much slower than light, which is why you see lightning before you hear thunder.", "bis": "Ang tingog mobaktas sa hangin og mga 343 ka metro kada segundo (mga 1,235 km/h) — mas hinay kaysa kahayag, mao nga makita una nimo ang kilat sa dili pa madungog ang dalugdog."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-gravity-moon", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity on the moon", "grades": [6, 7], "terms": ["gravity", "moon", "weight", "makakatalon", "makaambak", "pilo", "didto", "anim", "kang", "unom", "beses", "magaan", "gaan"], "fact": {"tl": "Ang gravity sa buwan ay mga 1/6 lang ng sa Earth, kaya mga anim na beses kang mas magaan doon at mas mataas kang makakatalon.", "en": "The Moon's gravity is only about 1/6 of Earth's, so you would weigh about six times less there and could jump much higher.", "bis": "Ang gravity sa bulan mga 1/6 lang sa Earth, mao nga mga unom ka pilo ka mas gaan didto ug mas taas ka makaambak."}, "source": "reference value; NRC PS2.B", "generator": "claude", "reviewed": false},
  {"id": "val-planets-order", "domain": "EARTH_SPACE", "topic": "order of the planets", "grades": [4, 5, 6], "terms": ["planets", "order", "solar system", "pangatlo", "ikatulo", "kalay", "sumala", "ayon", "layo", "planeta"], "fact": {"tl": "Ang 8 planeta ayon sa layo mula sa Araw: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Ang Earth ang pangatlo mula sa Araw.", "en": "The 8 planets in order from the Sun: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Earth is the 3rd from the Sun.", "bis": "Ang 8 ka planeta sumala sa kalay-o gikan sa Adlaw: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Ang Earth mao ang ikatulo gikan sa Adlaw."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-largest-smallest-planet", "domain": "EARTH_SPACE", "topic": "largest and smallest planet", "grades": [4, 5, 6], "terms": ["Jupiter", "Mercury", "planet", "largest", "smallest", "pinakamalaki", "batuhang", "batoon", "pinakamalaking", "kinagamyan", "kinadak", "pinakamaliit", "planeta"], "fact": {"tl": "Ang Jupiter ang pinakamalaking planeta; ang Mercury ang pinakamaliit. Ang Earth ang pinakamalaki sa mga batuhang (rocky) planeta.", "en": "Jupiter is the largest planet; Mercury is the smallest. Earth is the largest of the rocky planets.", "bis": "Ang Jupiter mao ang kinadak-ang planeta; ang Mercury mao ang kinagamyan. Ang Earth mao ang kinadak-an sa batoon (rocky) nga mga planeta."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-sun-distance", "domain": "EARTH_SPACE", "topic": "distance to the sun", "grades": [6, 7, 8], "terms": ["Sun", "distance", "light minutes", "umaabot", "milyong", "minuto", "milyon", "moabot", "kilometro", "kanato", "atin", "loob", "sulod"], "fact": {"tl": "Ang Araw ay nasa mga 150 milyong kilometro mula sa Earth. Ang liwanag nito ay umaabot sa atin sa loob ng mga 8 minuto.", "en": "The Sun is about 150 million kilometers from Earth. Its light takes about 8 minutes to reach us.", "bis": "Ang Adlaw mga 150 ka milyon ka kilometro gikan sa Earth. Ang kahayag niini moabot kanato sulod sa mga 8 ka minuto."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-moon-distance", "domain": "EARTH_SPACE", "topic": "distance to the moon", "grades": [6, 7], "terms": ["Moon", "distance", "space", "pinakamalapit", "kilometro", "labing", "kawanangan", "kalawakan", "duol", "buwan", "bulan", "kanato", "atin"], "fact": {"tl": "Ang buwan ay nasa mga 384,000 kilometro mula sa Earth — ang pinakamalapit na bagay sa kalawakan sa atin.", "en": "The Moon is about 384,000 kilometers from Earth — the closest object in space to us.", "bis": "Ang bulan mga 384,000 ka kilometro gikan sa Earth — ang labing duol nga butang sa kawanangan kanato."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-earth-day-year", "domain": "EARTH_SPACE", "topic": "earth's day and year", "grades": [4, 5, 6], "terms": ["rotation", "revolution", "day", "year", "kausa", "oras", "beses", "taon", "tuig", "molibot", "umiikot", "loob", "sulod"], "fact": {"tl": "Umiikot ang Earth nang isang beses sa loob ng mga 24 oras (isang araw) at umiikot sa Araw nang isang beses sa loob ng mga 365 araw (isang taon).", "en": "Earth turns once in about 24 hours (one day) and goes around the Sun once in about 365 days (one year).", "bis": "Molibot ang Earth kausa sulod sa mga 24 ka oras (usa ka adlaw) ug molibot sa Adlaw kausa sulod sa mga 365 ka adlaw (usa ka tuig)."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-earth-water-surface", "domain": "EARTH_SPACE", "topic": "earth's surface is mostly water", "grades": [4, 5, 6], "terms": ["water", "surface", "ocean", "blue", "natatakpan", "tingnan", "awon", "gitabonan", "asul", "kawanangan", "kalawakan", "nawong", "itong", "ibabaw"], "fact": {"tl": "Mga 71% ng ibabaw ng Earth ay natatakpan ng tubig, kaya asul itong tingnan mula sa kalawakan.", "en": "About 71% of Earth's surface is covered by water, which is why it looks blue from space.", "bis": "Mga 71% sa nawong sa Earth gitabonan og tubig, mao nga asul kini tan-awon gikan sa kawanangan."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-mars-red", "domain": "EARTH_SPACE", "topic": "why Mars is red", "grades": [4, 5, 6], "terms": ["Mars", "red planet", "iron", "rust", "kinalawang", "gitaya", "mayaman", "mapula", "dato", "puthaw", "bakal", "kolor", "kulay", "tinatawag"], "fact": {"tl": "Ang Mars ay tinatawag na Red Planet dahil ang lupa nito ay mayaman sa bakal (iron) na kinalawang, kaya mapula ang kulay nito.", "en": "Mars is called the Red Planet because its soil is rich in iron that has rusted, giving it a reddish color.", "bis": "Ang Mars gitawag og Red Planet kay ang yuta niini dato sa puthaw (iron) nga gitaya, mao nga mapula ang kolor niini."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-saturn-rings", "domain": "EARTH_SPACE", "topic": "saturn's rings", "grades": [4, 5, 6], "terms": ["Saturn", "rings", "ice", "planet", "maliliwanag", "singsing", "masanag", "nagtuyok", "piraso", "karamihan", "kasagaran", "hinimo", "gawa", "planeta"], "fact": {"tl": "Ang Saturn ay may maliliwanag na singsing (rings) na gawa karamihan sa yelo at piraso ng bato na umiikot sa planeta.", "en": "Saturn has bright rings made mostly of ice and rock pieces orbiting the planet.", "bis": "Ang Saturn adunay masanag nga mga singsing (rings) nga hinimo kasagaran sa yelo ug piraso sa bato nga nagtuyok sa planeta."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-sun-is-star", "domain": "EARTH_SPACE", "topic": "the sun is a star", "grades": [4, 5, 6], "terms": ["Sun", "star", "closest", "mukha", "pinakamalapit", "masanag", "maliwanag", "malaki", "labing", "malapit", "morag", "duol", "bituin"], "fact": {"tl": "Ang Araw ay isang bituin (star) — ang pinakamalapit sa atin. Mukha itong mas malaki at maliwanag kaysa ibang bituin dahil lang mas malapit ito sa atin.", "en": "The Sun is a star — the closest one to us. It looks bigger and brighter than other stars only because it is so much closer.", "bis": "Ang Adlaw usa ka bituon (star) — ang labing duol kanato. Morag mas dako ug masanag kini kaysa ubang bituon tungod lang kay mas duol kini kanato."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-blue-sky", "domain": "EARTH_SPACE", "topic": "why the sky is blue", "grades": [5, 6, 7], "terms": ["sky", "blue", "scattering", "light", "sunlight", "gikatag", "ikinakalat", "asul", "marami", "kumakalat", "langit", "mokatag", "daghan", "buong", "ubang"], "fact": {"tl": "Asul ang langit dahil ikinakalat (scattering) ng hangin ang liwanag ng araw, at mas marami nitong ikinakalat ang asul na kulay kaysa ibang kulay, kaya kumakalat ang asul sa buong langit.", "en": "The sky looks blue because air scatters sunlight, and it scatters the blue light (scattering) more than the other colors, spreading blue across the whole sky.", "bis": "Asul ang langit kay gikatag (scattering) sa hangin ang kahayag sa adlaw, ug mas daghan niini nga gikatag ang asul nga kolor kaysa ubang kolor, mao nga mokatag ang asul sa tibuok langit."}, "source": "AAAS BSL Ch.4F (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-sunset-red", "domain": "EARTH_SPACE", "topic": "why sunsets are red", "grades": [5, 6, 7], "terms": ["sunset", "red", "orange", "scattering"], "fact": {"tl": "Sa paglubog ng araw, mas makapal na hangin ang dinadaanan ng liwanag, kaya naikakalat (scattering) ang asul at natitira ang pula at kahel — kaya mapula ang langit.", "en": "At sunset, sunlight passes through more air, which scatters away the blue and leaves the reds and oranges, so the sky looks red.", "bis": "Sa pagsalop sa adlaw, mas baga nga hangin ang giagian sa kahayag, mao nga gikatag (scattering) ang asul ug nahibilin ang pula ug kahel — mao nga mapula ang langit."}, "source": "AAAS BSL Ch.4F (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-stars-twinkle", "domain": "EARTH_SPACE", "topic": "why stars twinkle", "grades": [5, 6, 7], "terms": ["stars", "twinkle", "atmosphere", "light", "parito", "paroo", "bend", "kumikislap", "mokislap", "nagbabaluktot", "bahagyang", "mobawog", "dumadaan", "moagi"], "fact": {"tl": "Kumikislap ang mga bituin dahil ang liwanag nila ay dumadaan sa gumagalaw na hangin sa atmosphere, na bahagyang nagbabaluktot (bend) sa liwanag paroo't parito.", "en": "Stars twinkle because their light passes through moving layers of air in our atmosphere, which bends the light a little this way and that.", "bis": "Mokislap ang mga bituon kay ang ilang kahayag moagi sa naglihok nga hangin sa atmosphere, nga gamay nga mobawog (bend) sa kahayag balik-balik."}, "source": "AAAS BSL Ch.4A/4F", "generator": "claude", "reviewed": false},
  {"id": "faq-where-rain-comes-from", "domain": "EARTH_SPACE", "topic": "where rain comes from", "grades": [3, 4, 5], "terms": ["rain", "water cycle", "clouds", "evaporation", "pinasisingaw", "gipaalisngaw", "naggikan", "mabug", "bumabagsak", "tumataas", "galing", "mosaka", "panganod", "mahulog"], "fact": {"tl": "Galing ang ulan sa water cycle: pinasisingaw ng araw ang tubig, tumataas ito at nagiging ulap, at kapag mabigat na ang ulap, bumabagsak ang tubig bilang ulan.", "en": "Rain comes from the water cycle: the sun evaporates water, it rises and cools into clouds, and when the clouds get heavy the water falls as rain.", "bis": "Naggikan ang ulan sa water cycle: gipaalisngaw sa adlaw ang tubig, mosaka kini ug mahimong panganod, ug kung mabug-at na ang panganod, mahulog ang tubig isip ulan."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "faq-why-boats-float", "domain": "FORCE_MOTION_ENERGY", "topic": "why boats float", "grades": [4, 5, 6], "terms": ["float", "buoyancy", "water", "boat", "sakayan", "bangka", "hangga", "basta", "gitulod", "palayo", "itinutulak", "pabalik", "magaan", "gaan"], "fact": {"tl": "Lumulutang ang bangka dahil itinutulak nito palayo ang tubig at itinutulak naman ito pabalik ng tubig (buoyancy). Hangga't mas magaan ang bangka kaysa tubig na itinutulak nito, lumulutang ito.", "en": "A boat floats because it pushes water aside and the water pushes back up (buoyancy). As long as the boat is lighter than the water it pushes aside, it floats.", "bis": "Molutaw ang sakayan kay gitulod niini palayo ang tubig ug gitulod usab kini balik sa tubig (buoyancy). Basta mas gaan ang sakayan kaysa tubig nga gitulod niini, molutaw kini."}, "source": "NRC PS2.B (forces)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-ice-floats", "domain": "MATTER", "topic": "why ice floats", "grades": [5, 6, 7], "terms": ["ice", "float", "density", "water", "likidong", "nayelo", "nagyelong", "bumababa", "nagyeyelo", "modako", "mokunhod", "magaan", "gaan", "lumulutang"], "fact": {"tl": "Lumulutang ang yelo dahil lumalaki ang tubig at bumababa ang density nito kapag nagyeyelo, kaya mas magaan ang nagyelong tubig kaysa likidong tubig.", "en": "Ice floats because water expands and becomes less dense (density) when it freezes, so frozen water is lighter than liquid water.", "bis": "Molutaw ang yelo kay modako ang tubig ug mokunhod ang density niini kung mo-yelo, mao nga mas gaan ang nayelo nga tubig kaysa likido nga tubig."}, "source": "AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "faq-why-leaves-green", "domain": "LIVING_THINGS", "topic": "why leaves are green", "grades": [3, 4, 5], "terms": ["leaves", "green", "chlorophyll", "photosynthesis", "itsura", "dagway", "gibalik", "berdeng", "ibinabalik", "berde", "humuhuli", "modakop", "dahon", "sangkap"], "fact": {"tl": "Berde ang mga dahon dahil sa chlorophyll, ang sangkap na humuhuli ng liwanag para sa photosynthesis. Ibinabalik nito ang berdeng liwanag, kaya berde ang itsura ng dahon.", "en": "Leaves are green because of chlorophyll, the substance that captures sunlight for photosynthesis. It reflects green light, so leaves look green.", "bis": "Berde ang mga dahon tungod sa chlorophyll, ang sustansya nga modakop sa kahayag para sa photosynthesis. Gibalik niini ang berde nga kahayag, mao nga berde ang dagway sa dahon."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "faq-why-leaves-change-color", "domain": "LIVING_THINGS", "topic": "why leaves turn yellow", "grades": [4, 5, 6], "terms": ["leaves", "yellow", "brown", "chlorophyll", "kapehon", "kayumanggi", "nasisira", "tigulang", "kulang", "dilaw", "dalag", "berdeng", "matanda", "maguba"], "fact": {"tl": "Nagiging dilaw o kayumanggi ang dahon kapag nasisira ang berdeng chlorophyll — halimbawa kapag matanda na ang dahon o kulang sa tubig o liwanag ang halaman.", "en": "Leaves turn yellow or brown when the green chlorophyll breaks down — for example when a leaf is old or the plant lacks water or light.", "bis": "Mahimong dalag o kapehon ang dahon kung maguba ang berde nga chlorophyll — pananglitan kung tigulang na ang dahon o kulang sa tubig o kahayag ang tanom."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-breathe", "domain": "LIVING_THINGS", "topic": "why we breathe", "grades": [3, 4, 5], "terms": ["breathe", "oxygen", "carbon dioxide", "energy", "magpalabas", "mopagawas", "ilabas", "ipagawas", "humihinga", "makakuha", "hugaw", "moginhawa", "cell", "gigamit"], "fact": {"tl": "Humihinga tayo para makakuha ng oxygen, na ginagamit ng ating mga cell para magpalabas ng enerhiya mula sa pagkain, at para ilabas ang carbon dioxide, isang waste na gas.", "en": "We breathe to take in oxygen, which our cells use to release energy from food, and to breathe out carbon dioxide, a waste gas.", "bis": "Moginhawa ta aron makakuha og oxygen, nga gigamit sa atong mga cell aron mopagawas og enerhiya gikan sa pagkaon, ug aron ipagawas ang carbon dioxide, usa ka hugaw nga gas."}, "source": "AAAS BSL Ch.6; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "faq-why-moon-changes-shape", "domain": "EARTH_SPACE", "topic": "why the moon changes shape", "grades": [4, 5, 6], "terms": ["moon", "phases", "shape", "orbit", "naliliwanagan", "gilamdagan", "lainlain", "gyud", "nagkakaroon", "nating", "molibot", "bahagi", "buwan", "bulan"], "fact": {"tl": "Hindi talaga nagbabago ng hugis ang buwan — iba-iba lang ang nakikita nating bahagi nito na naliliwanagan ng araw habang umiikot ito sa Earth, kaya nagkakaroon ng phases.", "en": "The Moon does not really change shape — we see different amounts of its sunlit side as it orbits Earth, which makes its phases.", "bis": "Dili gyud mausab og porma ang bulan — lainlain lang ang atong makita nga bahin niini nga gilamdagan sa adlaw samtang molibot kini sa Earth, mao nga adunay phases."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-shadows", "domain": "FORCE_MOTION_ENERGY", "topic": "why shadows form", "grades": [3, 4, 5], "terms": ["shadow", "light", "block", "straight line", "makakaliko", "makaliko", "baktas", "lakad", "luyo", "humaharang", "ngitngit", "tuwid", "likod", "moali"], "fact": {"tl": "Nabubuo ang anino kapag may bagay na humaharang sa liwanag. Dahil tuwid ang lakad ng liwanag, hindi ito makakaliko sa bagay, kaya may madilim na hugis (shadow) sa likod nito.", "en": "A shadow forms when an object blocks light. Because light travels in straight lines, it cannot bend around the object, leaving a dark shape behind it.", "bis": "Maporma ang anino kung adunay butang nga moali sa kahayag. Tungod kay tul-id ang baktas sa kahayag, dili kini makaliko sa butang, mao nga adunay ngitngit nga porma (shadow) sa luyo niini."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-iron-rusts", "domain": "MATTER", "topic": "why iron rusts", "grades": [5, 6, 7], "terms": ["iron", "rust", "oxygen", "chemical change", "kinakalawang", "nakikipag", "kalawang", "mataya", "takip", "tabon", "taya", "paglipas", "paglabay", "pulang"], "fact": {"tl": "Kinakalawang ang bakal kapag nakikipag-react ito sa oxygen at tubig sa paglipas ng panahon (chemical change), na bumubuo ng mapula-pulang takip na tinatawag na kalawang (rust).", "en": "Iron rusts when it reacts with oxygen and water over time (a chemical change), forming a reddish-brown coating called rust.", "bis": "Mataya ang puthaw kung mo-react kini sa oxygen ug tubig sa paglabay sa panahon (chemical change), nga maghimo og mapula-pula nga tabon nga gitawag og taya (rust)."}, "source": "AAAS BSL Ch.4D (chemical change)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-cold-when-wet", "domain": "FORCE_MOTION_ENERGY", "topic": "why we feel cold when wet", "grades": [5, 6, 7], "terms": ["evaporation", "cooling", "heat", "wet", "basang", "bation", "gikuha", "pakiramdam", "basa", "kinukuha", "sumisingaw", "alisngaw", "malamig", "bugnaw"], "fact": {"tl": "Malamig ang pakiramdam ng basang balat dahil habang sumisingaw (evaporation) ang tubig, kinukuha nito ang init mula sa iyong balat.", "en": "Wet skin feels cold because as the water evaporates it takes heat away from your skin (evaporation cools things down).", "bis": "Bugnaw ang bation sa basa nga panit kay samtang mo-alisngaw (evaporation) ang tubig, gikuha niini ang kainit gikan sa imong panit."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-sun-hot", "domain": "EARTH_SPACE", "topic": "why the sun is hot", "grades": [6, 7, 8], "terms": ["sun", "heat", "nuclear fusion", "hydrogen", "kaloob", "looban", "kinasuloran", "nagsasama", "bumuo", "napakaraming", "magtapok", "mobuga", "naglalabas", "daghan"], "fact": {"tl": "Mainit ang araw dahil sa kaloob-looban nito, nagsasama ang hydrogen para bumuo ng helium (nuclear fusion), na naglalabas ng napakaraming enerhiya bilang init at liwanag.", "en": "The Sun is hot because deep inside it, hydrogen joins to form helium (nuclear fusion), releasing enormous energy as heat and light.", "bis": "Init ang adlaw kay sa kinasuloran niini, magtapok ang hydrogen aron maporma ang helium (nuclear fusion), nga mobuga og daghan kaayong enerhiya isip kainit ug kahayag."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-magnet-sticks", "domain": "FORCE_MOTION_ENERGY", "topic": "why magnets stick to the fridge", "grades": [4, 5, 6], "terms": ["magnet", "iron", "attract", "fridge", "refrigerator", "pultahan", "pinto", "dumidikit", "modikit", "gibira", "hinihila", "puthaw", "bakal", "loob"], "fact": {"tl": "Dumidikit ang magnet sa refrigerator dahil may bakal (iron) sa loob ng pinto nito, at hinihila ng magnet ang bakal.", "en": "A magnet sticks to the fridge because the fridge door has iron inside, and magnets attract iron.", "bis": "Modikit ang magnet sa refrigerator kay adunay puthaw (iron) sa sulod sa pultahan niini, ug gibira sa magnet ang puthaw."}, "source": "NRC PS2.B (magnetism)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-plants-need-sun", "domain": "LIVING_THINGS", "topic": "why plants need sunlight", "grades": [3, 4, 5], "terms": ["plants", "sunlight", "photosynthesis", "food", "makakagawa", "manghihina", "mohuyang", "gumawa", "nagkinahanglan", "kadaghanan", "karamihan", "sariling", "kailangan", "sikat"], "fact": {"tl": "Kailangan ng halaman ang sikat ng araw dahil ginagamit nila ang enerhiya nito sa photosynthesis para gumawa ng sariling pagkain. Kung walang liwanag, hindi makakagawa ng pagkain ang karamihan ng halaman at manghihina.", "en": "Plants need sunlight because they use its energy in photosynthesis to make their own food. Without light, most plants cannot make food and will weaken.", "bis": "Nagkinahanglan ang tanom og kahayag sa adlaw kay gigamit nila ang enerhiya niini sa photosynthesis aron maghimo og kaugalingong pagkaon. Kung walay kahayag, dili makahimo og pagkaon ang kadaghanan sa tanom ug mohuyang."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "faq-why-things-fall", "domain": "FORCE_MOTION_ENERGY", "topic": "why things fall down", "grades": [3, 4, 5], "terms": ["gravity", "fall", "down", "Earth", "gibira", "hinihila", "bumabagsak", "gitna", "tanan", "tunga", "mahulog", "paubos", "pababa", "silang"], "fact": {"tl": "Bumabagsak pababa ang mga bagay dahil hinihila silang lahat ng gravity ng Earth papunta sa gitna ng planeta.", "en": "Things fall down because Earth's gravity pulls everything toward the center of the planet.", "bis": "Mahulog paubos ang mga butang kay gibira silang tanan sa gravity sa Earth paingon sa tunga sa planeta."}, "source": "NRC PS2.B (gravity)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-day-night", "domain": "EARTH_SPACE", "topic": "why we have day and night", "grades": [3, 4, 5], "terms": ["day", "night", "rotation", "Earth", "nakatalikod", "nagtalikod", "bahaging", "nakaharap", "atubang", "gabii", "gabi", "molibot", "umiikot", "bahin"], "fact": {"tl": "May araw at gabi tayo dahil umiikot ang Earth (rotation). Ang bahaging nakaharap sa Araw ay may araw; ang bahaging nakatalikod ay may gabi.", "en": "We have day and night because Earth spins (rotation). The side facing the Sun has day; the side facing away has night.", "bis": "Adunay adlaw ug gabii ta kay molibot ang Earth (rotation). Ang bahin nga nag-atubang sa Adlaw adunay adlaw; ang bahin nga nagtalikod adunay gabii."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-sweat", "domain": "LIVING_THINGS", "topic": "why we sweat", "grades": [4, 5, 6], "terms": ["sweat", "cool", "evaporation", "temperature"], "fact": {"tl": "Pumapawis tayo para palamigin ang katawan: habang sumisingaw (evaporation) ang pawis sa balat, kinukuha nito ang init, kaya bumababa ang temperatura natin.", "en": "We sweat to cool the body: as sweat evaporates from the skin it carries heat away, lowering our temperature.", "bis": "Mosingot ta aron bugnawon ang lawas: samtang mo-alisngaw (evaporation) ang singot sa panit, gikuha niini ang kainit, mao nga mokunhod ang atong temperatura."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "faq-why-sea-salty", "domain": "EARTH_SPACE", "topic": "why the sea is salty", "grades": [5, 6, 7], "terms": ["sea", "salt", "ocean", "rivers", "naiiwan", "mabilin", "ilog", "suba", "maalat", "parat", "kaunting", "asin", "natunaw", "sumisingaw"], "fact": {"tl": "Maalat ang dagat dahil ang mga ilog ay nagdadala ng kaunting natunaw na asin mula sa bato at lupa papunta sa dagat, at naiiwan ang asin habang sumisingaw ang tubig-dagat.", "en": "The sea is salty because rivers carry tiny amounts of dissolved salt from rocks and soil into the ocean, and the salt stays behind as seawater evaporates.", "bis": "Parat ang dagat kay ang mga suba modala og gamay nga natunaw nga asin gikan sa bato ug yuta ngadto sa dagat, ug mabilin ang asin samtang mo-alisngaw ang tubig-dagat."}, "source": "AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "faq-thunder-after-lightning", "domain": "EARTH_SPACE", "topic": "why thunder comes after lightning", "grades": [5, 6, 7], "terms": ["thunder", "lightning", "sound", "light", "speed", "maglakbay", "dalugdog", "nauuna", "kulog", "dungan", "sabay", "nangyayari", "mobaktas", "kidlat", "kilat"], "fact": {"tl": "Sabay nangyayari ang kidlat at kulog, pero nauuna mong makita ang kidlat dahil mas mabilis maglakbay ang liwanag kaysa tunog.", "en": "Lightning and thunder happen at the same time, but you see the lightning first because light travels much faster than sound.", "bis": "Dungan mahitabo ang kilat ug dalugdog, apan makita una nimo ang kilat kay mas paspas mobaktas ang kahayag kaysa tingog."}, "source": "NRC PS4 (light vs sound speed)", "generator": "claude", "reviewed": false},
  {"id": "faq-helium-balloon", "domain": "MATTER", "topic": "why helium balloons float up", "grades": [4, 5, 6], "terms": ["helium", "balloon", "density", "float"], "fact": {"tl": "Lumulutang pataas ang lobong may helium dahil mas magaan (mas mababa ang density) ang helium gas kaysa hanging nakapaligid, kaya itinutulak ito pataas ng hangin.", "en": "A helium balloon floats up because helium gas is lighter (less dense) than the air around it, so the air pushes it upward.", "bis": "Molutaw pataas ang lobo nga adunay helium kay mas gaan (mas ubos ang density) ang helium gas kaysa hangin sa palibot, mao nga gitulod kini pataas sa hangin."}, "source": "AAAS BSL Ch.4D (density)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-rainbow", "domain": "FORCE_MOTION_ENERGY", "topic": "why we see rainbows", "grades": [5, 6, 7], "terms": ["rainbow", "refraction", "light", "colors", "raindrops", "bahaghari", "naghahati", "balangaw", "mobahin", "dumaan", "nagbabaluktot", "mobawog", "moagi", "patak", "ulan"], "fact": {"tl": "Nabubuo ang bahaghari kapag dumaan ang liwanag ng araw sa mga patak ng ulan, na nagbabaluktot at naghahati sa liwanag sa mga kulay nito (refraction).", "en": "A rainbow forms when sunlight passes through raindrops, which bend and split the light into its colors (refraction).", "bis": "Maporma ang balangaw kung moagi ang kahayag sa adlaw sa mga tulo sa ulan, nga mobawog ug mobahin sa kahayag ngadto sa mga kolor niini (refraction)."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-volcano-erupts", "domain": "EARTH_SPACE", "topic": "why volcanoes erupt", "grades": [6, 7, 8], "terms": ["volcano", "magma", "eruption", "pressure", "bumubuga", "bunganga", "magtigom", "tunaw", "iipon", "sumasabog", "presyur", "pagawas", "palabas", "mobuto"], "fact": {"tl": "Sumasabog ang bulkan kapag ang mainit na tunaw na bato (magma) at mga gas sa ilalim ng lupa ay nag-iipon ng presyon at bumubuga palabas sa bunganga sa crust ng Earth.", "en": "A volcano erupts when hot melted rock (magma) and gases deep underground build up pressure and burst out through an opening in the Earth's crust.", "bis": "Mobuto ang bulkan kung ang init nga natunaw nga bato (magma) ug mga gas sa ilalom sa yuta magtigom og presyur ug mobuga pagawas agi sa baba sa crust sa Earth."}, "source": "NRC ESS2.B (plate tectonics)", "generator": "claude", "reviewed": false},
  {"id": "living-five-senses-g3", "domain": "LIVING_THINGS", "topic": "the five senses", "grades": [3, 4], "terms": ["senses", "sight", "hearing", "smell", "taste", "touch", "panimaho", "nahitabo", "panlasa", "mahibaloan", "pandungog", "pandinig", "igbalati", "paghikap", "pandama", "limang"], "fact": {"tl": "Ang tao ay may limang pandama (senses): paningin (mata), pandinig (tainga), pang-amoy (ilong), panlasa (dila), at pang-hipo (balat). Tumutulong ang mga ito para malaman natin ang nangyayari sa paligid.", "en": "Humans have five senses: sight (eyes), hearing (ears), smell (nose), taste (tongue), and touch (skin). They help us learn what is happening around us.", "bis": "Ang tawo adunay lima ka igbalati (senses): panan-aw (mata), pandungog (dalunggan), panimaho (ilong), panlasa (dila), ug paghikap (panit). Motabang kini aron mahibaloan nato ang nahitabo sa palibot."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-vertebrate-classes-g5", "domain": "LIVING_THINGS", "topic": "vertebrate groups", "grades": [5, 6], "terms": ["mammals", "birds", "fish", "reptiles", "amphibians", "vertebrate"], "fact": {"tl": "Ang mga vertebrate (may backbone) ay nahahati sa limang grupo: mammals (gatas at balahibo, tulad ng aso), birds (pakpak at balahibo), fish (kaliskis at hasang), reptiles (tuyong kaliskis, tulad ng ahas), at amphibians (basa ang balat, tulad ng palaka).", "en": "Vertebrates (animals with a backbone) fall into five groups: mammals (milk and fur, like dogs), birds (wings and feathers), fish (scales and gills), reptiles (dry scales, like snakes), and amphibians (moist skin, like frogs).", "bis": "Ang mga vertebrate (adunay backbone) nabahin sa lima ka grupo: mammals (gatas ug balhibo, sama sa iro), birds (pako ug balhibo), fish (himbis ug hasang), reptiles (uga nga himbis, sama sa bitin), ug amphibians (basa ang panit, sama sa baki)."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-herbivore-carnivore-g4", "domain": "LIVING_THINGS", "topic": "herbivore carnivore omnivore", "grades": [4, 5], "terms": ["herbivore", "carnivore", "omnivore", "eat", "kinakain", "kalabaw", "gikaon", "baboy", "kabaw", "iring", "pusa", "kumakain", "sumala", "mokaon"], "fact": {"tl": "Ayon sa kinakain: ang herbivore ay kumakain ng halaman (tulad ng kalabaw), ang carnivore ay kumakain ng ibang hayop (tulad ng pusa), at ang omnivore ay kumakain ng halaman at hayop (tulad ng tao at baboy).", "en": "By what they eat: a herbivore eats plants (like a carabao), a carnivore eats other animals (like a cat), and an omnivore eats both plants and animals (like humans and pigs).", "bis": "Sumala sa gikaon: ang herbivore mokaon og tanom (sama sa kabaw), ang carnivore mokaon og ubang hayop (sama sa iring), ug ang omnivore mokaon og tanom ug hayop (sama sa tawo ug baboy)."}, "source": "AAAS BSL Ch.5; NRC LS2.A", "generator": "claude", "reviewed": false},
  {"id": "living-animal-adaptations-g5", "domain": "LIVING_THINGS", "topic": "animal adaptations", "grades": [5, 6], "terms": ["adaptation", "camouflage", "hibernation", "migration", "pagtago", "nagbago", "katulog", "pagbalhin", "paglipat", "paraan", "paagi", "tingtugnaw", "mahabang", "taglamig"], "fact": {"tl": "May mga espesyal na paraan ang hayop para mabuhay (adaptations): ang camouflage (pagtago sa pamamagitan ng kulay tulad ng chameleon), ang hibernation (mahabang tulog sa taglamig), at ang migration (paglipat sa ibang lugar kapag nagbago ang panahon).", "en": "Animals have special ways to survive (adaptations): camouflage (hiding by color, like a chameleon), hibernation (a long winter sleep), and migration (moving to another place when the season changes).", "bis": "Adunay espesyal nga paagi ang hayop aron mabuhi (adaptations): ang camouflage (pagtago pinaagi sa kolor sama sa chameleon), ang hibernation (taas nga katulog sa tingtugnaw), ug ang migration (pagbalhin sa laing dapit kung mausab ang panahon)."}, "source": "AAAS BSL Ch.5; NRC LS4.C", "generator": "claude", "reviewed": false},
  {"id": "living-plant-adaptations-g5", "domain": "LIVING_THINGS", "topic": "plant adaptations", "grades": [5, 6], "terms": ["adaptation", "cactus", "mangrove", "environment"], "fact": {"tl": "May mga halaman na may espesyal na adaptation sa kanilang kapaligiran: ang cactus ay may makapal na tangkay para mag-imbak ng tubig sa disyerto, at ang bakawan (mangrove) ay may ugat na kayang tumayo sa maalat na tubig sa baybayin.", "en": "Some plants have special adaptations to their environment: a cactus has a thick stem to store water in the desert, and a mangrove has roots that can stand in the salty water of the shore.", "bis": "Adunay mga tanom nga may espesyal nga adaptation sa ilang palibot: ang cactus adunay baga nga punoan aron magtipig og tubig sa disyerto, ug ang bakhaw (mangrove) adunay gamot nga makabarog sa parat nga tubig sa baybayon."}, "source": "AAAS BSL Ch.5; NRC LS4.C", "generator": "claude", "reviewed": false},
  {"id": "living-germination-g4", "domain": "LIVING_THINGS", "topic": "seed germination", "grades": [4, 5], "terms": ["germination", "seed", "sprout", "grow", "paitaas", "usbong", "usbod", "tapos", "papuntang", "dayon", "lumalabas", "igong", "liso", "mogawas"], "fact": {"tl": "Sa germination, tumutubo ang buto (seed) papuntang bagong halaman kapag may sapat na tubig, hangin, at init. Unang lumalabas ang ugat pababa, tapos ang usbong (shoot) paitaas papunta sa liwanag.", "en": "In germination, a seed grows into a new plant when there is enough water, air, and warmth. First the root comes out downward, then the shoot grows upward toward the light.", "bis": "Sa germination, motubo ang liso (seed) ngadto sa bag-ong tanom kung adunay igong tubig, hangin, ug kainit. Una mogawas ang gamot paubos, dayon ang usbod (shoot) motubo pataas paingon sa kahayag."}, "source": "AAAS BSL Ch.5; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "living-fungi-g6", "domain": "LIVING_THINGS", "topic": "fungi", "grades": [6, 7], "terms": ["fungi", "mushroom", "mold", "decomposer"], "fact": {"tl": "Ang fungi (tulad ng kabute o mushroom at amag o mold) ay hindi halaman o hayop — sariling grupo sila. Hindi sila gumagawa ng sariling pagkain; kumukuha sila ng sustansya mula sa patay o nabubulok na bagay, kaya mahalaga sila bilang decomposers.", "en": "Fungi (like mushrooms and mold) are not plants or animals — they are their own group. They do not make their own food; they take nutrients from dead or rotting matter, so they are important decomposers.", "bis": "Ang fungi (sama sa uhong o mushroom ug agup-op o mold) dili tanom o hayop — kaugalingon silang grupo. Wala sila maghimo og kaugalingong pagkaon; mokuha sila og sustansya gikan sa patay o nadunot nga butang, mao nga importante sila isip decomposers."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-food-web-g6", "domain": "LIVING_THINGS", "topic": "food web", "grades": [6, 7], "terms": ["food web", "food chain", "ecosystem", "energy", "kumain", "kainin", "ipinapakita", "gipakita", "chain", "magkakaugnay", "maaaring", "magkadugtong", "marami", "mokaon"], "fact": {"tl": "Ang food web ay grupo ng maraming food chain na magkakaugnay sa isang ecosystem. Ipinapakita nito na ang isang hayop ay maaaring kumain ng maraming uri ng pagkain, at ang isang halaman o hayop ay maaaring kainin ng marami.", "en": "A food web is a group of many connected food chains in an ecosystem. It shows that one animal may eat many kinds of food, and one plant or animal may be eaten by many.", "bis": "Ang food web usa ka grupo sa daghang food chain nga magkadugtong sa usa ka ecosystem. Gipakita niini nga ang usa ka hayop mahimong mokaon og daghang klase sa pagkaon, ug ang usa ka tanom o hayop mahimong kan-on sa daghan."}, "source": "NRC LS2.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-decomposers-g5", "domain": "LIVING_THINGS", "topic": "decomposers", "grades": [5, 6], "terms": ["decomposer", "bacteria", "fungi", "nutrients", "magamit", "bulate", "naglalansag", "moguba", "ibalik", "siklo", "ulod", "ibinabalik", "patay", "mahalaga"], "fact": {"tl": "Ang mga decomposers (tulad ng bacteria, fungi, at bulate) ang naglalansag sa mga patay na halaman at hayop. Ibinabalik nila ang sustansya sa lupa para magamit muli ng mga halaman — kaya mahalaga sila sa siklo ng buhay.", "en": "Decomposers (like bacteria, fungi, and worms) break down dead plants and animals. They return nutrients to the soil for plants to use again — so they are important in the cycle of life.", "bis": "Ang mga decomposers (sama sa bacteria, fungi, ug ulod) maoy moguba sa patay nga tanom ug hayop. Ibalik nila ang sustansya sa yuta aron magamit pag-usab sa mga tanom — mao nga importante sila sa siklo sa kinabuhi."}, "source": "NRC LS2.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-endangered-ph-g6", "domain": "LIVING_THINGS", "topic": "endangered species", "grades": [6, 7], "terms": ["endangered", "extinction", "Philippine eagle", "tamaraw", "conservation", "tinutulungan", "pangangalaga", "nanganganib", "pagpangayam", "pangangaso", "matabangan", "pagkasira", "nameligro", "pagkaguba", "tuluyan"], "fact": {"tl": "Ang ilang hayop ay endangered — nanganganib mawala nang tuluyan (extinction) dahil sa pagkasira ng tirahan at pangangaso. Sa Pilipinas, kabilang dito ang Philippine eagle at ang tamaraw. Tinutulungan natin sila sa pamamagitan ng pangangalaga sa kanilang habitat.", "en": "Some animals are endangered — at risk of disappearing forever (extinction) because of habitat loss and hunting. In the Philippines these include the Philippine eagle and the tamaraw. We help them by protecting their habitats.", "bis": "Ang ubang hayop endangered — nameligro nga mawala hangtod (extinction) tungod sa pagkaguba sa puy-anan ug pagpangayam. Sa Pilipinas, lakip niini ang Philippine eagle ug ang tamaraw. Matabangan nato sila pinaagi sa pag-amping sa ilang habitat."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "fme-renewable-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "renewable energy", "grades": [6, 7], "terms": ["renewable energy", "solar", "wind", "hydro", "pinagkukunan", "polusyon", "malinis", "limpyo", "tinubdan", "nagaagos", "nauubos", "mahurot", "karbon", "pagsunog"], "fact": {"tl": "Ang renewable energy ay galing sa pinagkukunan na hindi nauubos: solar (araw), wind (hangin), at hydro (umaagos na tubig). Mas malinis ito kaysa pagsunog ng langis o karbon na nagdudulot ng polusyon.", "en": "Renewable energy comes from sources that do not run out: solar (sun), wind, and hydro (flowing water). It is cleaner than burning oil or coal, which causes pollution.", "bis": "Ang renewable energy gikan sa tinubdan nga dili mahurot: solar (adlaw), wind (hangin), ug hydro (nagaagos nga tubig). Mas limpyo kini kaysa pagsunog og lana o karbon nga maghatag og polusyon."}, "source": "NRC PS3; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "fme-static-electricity-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "static electricity", "grades": [5, 6], "terms": ["static electricity", "charge", "rub", "shock"], "fact": {"tl": "Ang static electricity ay nabubuo kapag nagkiskisan ang dalawang bagay at lumilipat ang maliliit na charge. Kaya dumidikit ang buhok sa suklay o may maliit na 'kuryente' kang maramdaman kapag humawak ka pagkatapos magkiskis.", "en": "Static electricity builds up when two objects rub and tiny charges move between them. That is why hair sticks to a comb, or you feel a small 'shock' after rubbing.", "bis": "Ang static electricity matukod kung magkuskos ang duha ka butang ug mobalhin ang gagmay nga charge. Mao nga modikit ang buhok sa sudlay, o adunay gamay nga 'kuryente' nga imong bation kung mohikap ka human magkuskos."}, "source": "NRC PS2.B; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-how-we-see-color-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how we see color", "grades": [6, 7], "terms": ["color", "reflect", "absorb", "light", "gisuyop", "mansanas", "gibalik", "pulang", "sinisipsip", "pula", "ibinabalik", "uban", "ubang", "nato"], "fact": {"tl": "Nakikita natin ang kulay dahil ibinabalik (reflect) ng mga bagay ang ilang kulay ng liwanag at sinisipsip (absorb) ang iba. Halimbawa, pula ang mansanas dahil ibinabalik nito ang pulang liwanag at sinisipsip ang ibang kulay.", "en": "We see color because objects reflect some colors of light and absorb others. For example, an apple looks red because it reflects red light and absorbs the other colors.", "bis": "Makita nato ang kolor kay gibalik (reflect) sa mga butang ang ubang kolor sa kahayag ug gisuyop (absorb) ang uban. Pananglitan, pula ang mansanas kay gibalik niini ang pula nga kahayag ug gisuyop ang ubang kolor."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "fme-heat-conductors-insulators-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat conductors and insulators", "grades": [6, 7], "terms": ["conductor", "insulator", "heat", "metal", "magpadaloy", "kaserola", "kuptanan", "kaldero", "panapton", "hawakan", "tela", "magpadala", "plastik", "kamay"], "fact": {"tl": "Ang heat conductors (tulad ng metal) ay mabilis magpadaloy ng init; ang heat insulators (tulad ng kahoy, plastik, at tela) ay mabagal. Kaya kahoy o plastik ang hawakan ng kaserola — para hindi mainit ang kamay.", "en": "Heat conductors (like metal) let heat flow quickly; heat insulators (like wood, plastic, and cloth) are slow. That is why a pot handle is wood or plastic — so your hand does not get hot.", "bis": "Ang heat conductors (sama sa metal) paspas magpadala og kainit; ang heat insulators (sama sa kahoy, plastik, ug panapton) hinay. Mao nga kahoy o plastik ang kuptanan sa kaldero — aron dili mainit ang kamot."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "fme-echo-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "echoes", "grades": [5, 6], "terms": ["echo", "sound", "reflect", "bounce", "alingawngaw", "pangpang", "bumalik", "umuulit", "bangin", "pader", "boses", "lanog", "paril", "naririnig"], "fact": {"tl": "Ang echo (alingawngaw) ay nangyayari kapag ang tunog ay tumama sa isang malaking ibabaw tulad ng bundok o pader at bumalik sa atin. Kaya naririnig mong umuulit ang iyong boses sa malaking silid o bangin.", "en": "An echo happens when sound hits a large surface like a mountain or wall and bounces back to us. That is why you hear your voice repeat in a big room or canyon.", "bis": "Ang echo (lanog) mahitabo kung ang tingog motama sa dako nga nawong sama sa bukid o paril ug mobalik kanato. Mao nga madungog nimo nga mobalik-balik ang imong tingog sa dako nga kwarto o pangpang."}, "source": "NRC PS4.A (sound)", "generator": "claude", "reviewed": false},
  {"id": "fme-battery-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how a battery works", "grades": [5, 6], "terms": ["battery", "chemical energy", "electrical energy", "circuit", "patakbuhin", "padaganon", "iimbak", "remote", "magtipig", "himoon", "flashlight", "baterya", "ginagawa", "dumadaloy"], "fact": {"tl": "Ang baterya (battery) ay nag-iimbak ng chemical energy at ginagawa itong electrical energy para patakbuhin ang mga gamit tulad ng flashlight at remote. Dumadaloy ang kuryente mula sa baterya papunta sa gamit at pabalik sa isang circuit.", "en": "A battery stores chemical energy and turns it into electrical energy to power devices like flashlights and remotes. Current flows from the battery to the device and back in a circuit.", "bis": "Ang baterya (battery) magtipig og chemical energy ug himoon kining electrical energy aron padaganon ang mga gamit sama sa flashlight ug remote. Moagos ang kuryente gikan sa baterya ngadto sa gamit ug balik sa usa ka circuit."}, "source": "NRC PS3.A", "generator": "claude", "reviewed": false},
  {"id": "earth-typhoon-g5", "domain": "EARTH_SPACE", "topic": "typhoons", "grades": [5, 6], "terms": ["typhoon", "storm", "wind", "rain", "karagatan", "kadagatan", "handa", "andam", "mahalagang", "dumaan", "unos", "nagtuyok", "madalas", "moagi"], "fact": {"tl": "Ang bagyo (typhoon) ay isang malakas na bagyo na may umiikot na hangin at malakas na ulan, na nabubuo sa mainit na karagatan. Madalas dumaan ang bagyo sa Pilipinas, kaya mahalagang maging handa.", "en": "A typhoon is a powerful storm with spinning winds and heavy rain that forms over warm oceans. Typhoons often pass through the Philippines, so it is important to be prepared.", "bis": "Ang bagyo (typhoon) usa ka kusog nga unos nga adunay nagtuyok nga hangin ug kusog nga ulan, nga maporma sa init nga kadagatan. Kanunay moagi ang bagyo sa Pilipinas, mao nga importante nga andam."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-clouds-g5", "domain": "EARTH_SPACE", "topic": "types of clouds", "grades": [5, 6], "terms": ["clouds", "cumulus", "cirrus", "nimbus", "naglutaw", "maputi", "abuhon", "himpapawid", "kahanginan", "kristal", "gapas", "puti", "morag", "bulak"], "fact": {"tl": "Ang ulap (clouds) ay gawa sa maliliit na patak ng tubig o kristal ng yelo na lumulutang sa himpapawid. May iba't ibang uri: ang maputi at parang bulak (cumulus), ang manipis at mataas (cirrus), at ang makapal na kulay-abo na nagdadala ng ulan (nimbus).", "en": "Clouds are made of tiny water droplets or ice crystals floating in the air. There are different types: white and puffy (cumulus), thin and high (cirrus), and thick gray ones that bring rain (nimbus).", "bis": "Ang panganod (clouds) hinimo sa gagmay nga tulo sa tubig o kristal sa yelo nga naglutaw sa kahanginan. Adunay nagkalainlaing klase: ang puti ug morag gapas (cumulus), ang nipis ug taas (cirrus), ug ang baga nga abuhon nga modala og ulan (nimbus)."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-ph-seasons-g4", "domain": "EARTH_SPACE", "topic": "seasons in the Philippines", "grades": [4, 5], "terms": ["seasons", "dry season", "wet season", "tropical", "nobyembre", "mayo", "tayong", "marso", "hunyo", "ting", "tingtugnaw", "taglamig", "pangunahing", "klima"], "fact": {"tl": "Sa Pilipinas, may dalawang pangunahing panahon: ang tag-init o tag-araw (dry season, mga Marso hanggang Mayo) at ang tag-ulan (wet season, mga Hunyo hanggang Nobyembre). Wala tayong taglamig dahil tropical ang ating klima.", "en": "In the Philippines there are two main seasons: the dry season (about March to May) and the wet/rainy season (about June to November). We have no winter because our climate is tropical.", "bis": "Sa Pilipinas, adunay duha ka nag-unang panahon: ang ting-init (dry season, mga Marso hangtod Mayo) ug ang ting-ulan (wet season, mga Hunyo hangtod Nobyembre). Wala tay tingtugnaw kay tropical ang atong klima."}, "source": "NRC ESS2.D (climate)", "generator": "claude", "reviewed": false},
  {"id": "earth-tides-g6", "domain": "EARTH_SPACE", "topic": "tides", "grades": [6, 7], "terms": ["tides", "moon", "gravity", "sea", "pagkanaog", "pagbaba", "bahagya", "pagsaka", "sanhi", "hunas", "taog", "kati", "taob", "pagtaas"], "fact": {"tl": "Ang taog at kati (tides) ay ang pagtaas at pagbaba ng tubig-dagat. Sanhi ito ng hila ng gravity ng buwan (at bahagya ng araw) sa tubig ng Earth habang umiikot ang planeta.", "en": "Tides are the rising and falling of the sea. They are caused by the pull of the Moon's gravity (and partly the Sun's) on Earth's water as the planet turns.", "bis": "Ang taob ug hunas (tides) mao ang pagsaka ug pagkanaog sa tubig-dagat. Hinungdan niini ang bira sa gravity sa bulan (ug gamay sa adlaw) sa tubig sa Earth samtang molibot ang planeta."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-fossils-g6", "domain": "EARTH_SPACE", "topic": "fossils", "grades": [6, 7], "terms": ["fossil", "remains", "rock", "ancient", "napreserbar", "napreserba", "nakalipas", "nabuhay", "milabay", "nabuhi", "bakas", "salin", "labi", "siyentista"], "fact": {"tl": "Ang fossils ay mga labi o bakas ng mga halaman at hayop noong unang panahon na napreserba sa bato. Tumutulong ang mga ito sa mga siyentista na malaman kung anong nabuhay sa Earth milyon-milyong taon na ang nakalipas.", "en": "Fossils are the remains or traces of ancient plants and animals preserved in rock. They help scientists learn what lived on Earth millions of years ago.", "bis": "Ang fossils mao ang salin o timaan sa karaang tanom ug hayop nga napreserbar sa bato. Motabang kini sa mga siyentista nga mahibaloan kung unsa ang nabuhi sa Earth milyon-milyon ka tuig na ang milabay."}, "source": "NRC ESS1.C; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-meteors-comets-g6", "domain": "EARTH_SPACE", "topic": "asteroids comets meteors", "grades": [6, 7], "terms": ["asteroid", "comet", "meteor", "shooting star", "lumalapit", "buntot", "moduol", "ikog", "nasusunog", "masunog", "pumapasok", "mosulod", "malaking", "alikabok"], "fact": {"tl": "Sa kalawakan, ang asteroid ay malaking bato na umiikot sa Araw; ang comet ay bola ng yelo at alikabok na may buntot kapag lumalapit sa Araw; at ang meteor ('shooting star') ay maliit na bato na nasusunog kapag pumapasok sa atmosphere ng Earth.", "en": "In space, an asteroid is a large rock orbiting the Sun; a comet is a ball of ice and dust with a tail when it nears the Sun; and a meteor ('shooting star') is a small rock that burns up entering Earth's atmosphere.", "bis": "Sa kawanangan, ang asteroid usa ka dako nga bato nga molibot sa Adlaw; ang comet usa ka bola sa yelo ug abog nga adunay ikog kung moduol sa Adlaw; ug ang meteor ('shooting star') usa ka gamay nga bato nga masunog kung mosulod sa atmosphere sa Earth."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-recycling-g4", "domain": "EARTH_SPACE", "topic": "recycling and conservation", "grades": [4, 5], "terms": ["recycle", "reduce", "reuse", "waste", "environment", "mababawasan", "maingatan", "maamping", "bawasan", "gamitin", "makunhuran", "kinaiyahan", "kalikasan", "gamiton", "basura"], "fact": {"tl": "Mababawasan natin ang basura at maingatan ang kalikasan sa pamamagitan ng 3 R's: Reduce (bawasan ang gamit), Reuse (gamitin muli), at Recycle (gawing bago ang lumang bagay tulad ng plastik at papel).", "en": "We can reduce waste and protect nature with the 3 R's: Reduce (use less), Reuse (use again), and Recycle (turn old things like plastic and paper into new ones).", "bis": "Makunhuran nato ang basura ug maamping ang kinaiyahan pinaagi sa 3 R's: Reduce (gamay nga gamiton), Reuse (gamiton pag-usab), ug Recycle (himoon nga bag-o ang daan nga butang sama sa plastik ug papel)."}, "source": "NRC ESS3.C", "generator": "claude", "reviewed": false},
  {"id": "matter-dissolving-factors-g6", "domain": "MATTER", "topic": "what makes things dissolve faster", "grades": [6, 7], "terms": ["dissolve", "temperature", "stir", "solute"], "fact": {"tl": "Mas mabilis matunaw (dissolve) ang isang solid sa likido kapag (1) iniinit ang likido, (2) hinahalo o kinakalog, at (3) pinino sa maliliit na piraso ang solid. Kaya mas mabilis matunaw ang asukal sa mainit na tubig na hinahalo.", "en": "A solid dissolves faster in a liquid when (1) the liquid is heated, (2) it is stirred, and (3) the solid is in smaller pieces. That is why sugar dissolves faster in hot water that is stirred.", "bis": "Mas paspas matunaw (dissolve) ang solid sa likido kung (1) initan ang likido, (2) kutawon, ug (3) dugmokon sa gagmay nga piraso ang solid. Mao nga mas paspas matunaw ang asukal sa init nga tubig nga gikutaw."}, "source": "NRC PS1.A; DepEd Science CG (Matter)", "generator": "claude", "reviewed": false},
  {"id": "living-cell-organelles-g8", "domain": "LIVING_THINGS", "topic": "cell organelles", "grades": [7, 8], "terms": ["organelle", "nucleus", "mitochondria", "membrane", "cytoplasm", "kumokontrol", "mokontrol", "kontrol", "tungkulin", "pumapasok", "mosulod", "sentro", "tahas", "bahagi", "likido"], "fact": {"tl": "Ang cell ay may maliliit na bahagi (organelles) na may tungkulin: ang nucleus (kontrol-sentro na may DNA), ang mitochondria (gumagawa ng enerhiya), ang cytoplasm (likido sa loob), at ang cell membrane (balat na kumokontrol kung ano ang pumapasok).", "en": "A cell has tiny parts (organelles) with jobs: the nucleus (control center holding DNA), the mitochondria (make energy), the cytoplasm (fluid inside), and the cell membrane (skin that controls what enters).", "bis": "Ang cell adunay gagmay nga bahin (organelles) nga may tahas: ang nucleus (sentro sa kontrol nga adunay DNA), ang mitochondria (maghimo og enerhiya), ang cytoplasm (likido sa sulod), ug ang cell membrane (panit nga mokontrol kung unsa ang mosulod)."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-dna-genes-g8", "domain": "LIVING_THINGS", "topic": "DNA and genes", "grades": [7, 8], "terms": ["DNA", "genes", "traits", "instructions", "partikular", "nagsasabi", "magsulti", "pagtukod", "gagana", "bubuo", "unsaon", "piho", "paglihok", "katangian"], "fact": {"tl": "Ang DNA ay parang 'instruction manual' sa loob ng bawat cell na nagsasabi kung paano bubuo at gagana ang katawan. Ang genes ay maliliit na bahagi ng DNA na nagdadala ng partikular na katangian, tulad ng kulay ng mata.", "en": "DNA is like an 'instruction manual' inside every cell that tells the body how to build and work. Genes are small sections of DNA that carry particular traits, like eye color.", "bis": "Ang DNA sama sa 'instruction manual' sa sulod sa matag cell nga magsulti kung unsaon pagtukod ug paglihok sa lawas. Ang genes gagmay nga bahin sa DNA nga modala og piho nga kinaiya, sama sa kolor sa mata."}, "source": "NRC LS3.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-immune-system-g7", "domain": "LIVING_THINGS", "topic": "immune system", "grades": [6, 7, 8], "terms": ["immune system", "germs", "white blood cells", "disease", "nagtatanggol", "modepensa", "germ", "masustansyang", "masustansya", "paghuhugas", "lumalaban", "paghugas", "mosukol", "virus"], "fact": {"tl": "Ang immune system ang nagtatanggol sa katawan laban sa mga germ (bacteria at virus). Ang mga white blood cells ang lumalaban sa mga ito. Ang madalas na paghuhugas ng kamay, sapat na tulog, at masustansyang pagkain ay tumutulong para manatiling malakas ito.", "en": "The immune system defends the body against germs (bacteria and viruses). White blood cells fight them off. Frequent handwashing, enough sleep, and nutritious food help keep it strong.", "bis": "Ang immune system maoy modepensa sa lawas batok sa mga germ (bacteria ug virus). Ang mga white blood cells maoy mosukol niini. Ang kanunay nga paghugas sa kamot, igong tulog, ug masustansya nga pagkaon motabang aron magpabilin kining lig-on."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-nutrition-food-groups-g4", "domain": "LIVING_THINGS", "topic": "balanced diet and food groups", "grades": [4, 5], "terms": ["nutrition", "food groups", "go grow glow", "balanced diet", "hatiin", "bahina", "utanon", "gulay", "kinahanglan", "bitamina", "protina", "paglaki", "pagtubo", "kanin"], "fact": {"tl": "Para maging malusog, kailangan ng balanced diet. Sa Pinggang Pinoy, hatiin ang pagkain sa: GO (carbohydrates para sa enerhiya, tulad ng kanin), GROW (protina para sa paglaki, tulad ng isda at itlog), at GLOW (gulay at prutas para sa bitamina).", "en": "To be healthy you need a balanced diet. In the Filipino 'Pinggang Pinoy', divide food into: GO foods (carbohydrates for energy, like rice), GROW foods (protein for growth, like fish and eggs), and GLOW foods (vegetables and fruits for vitamins).", "bis": "Aron mahimong himsog, kinahanglan og balanced diet. Sa Pinggang Pinoy, bahina ang pagkaon sa: GO (carbohydrates para sa enerhiya, sama sa kan-on), GROW (protina para sa pagtubo, sama sa isda ug itlog), ug GLOW (utanon ug prutas para sa bitamina)."}, "source": "DepEd Health/Science; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-plant-tropism-g6", "domain": "LIVING_THINGS", "topic": "plant tropism", "grades": [6, 7], "terms": ["tropism", "phototropism", "gravitropism", "respond", "laging", "tumutugon", "motubag", "nakaharap", "atubang", "tumutubo", "paligid", "gamot", "paubos", "dahon"], "fact": {"tl": "Tumutugon ang halaman sa paligid nito (tropism): tumutubo ito papunta sa liwanag (phototropism) at tumutubo ang ugat pababa dahil sa gravity (gravitropism). Kaya laging nakaharap sa araw ang mga dahon.", "en": "Plants respond to their surroundings (tropism): they grow toward light (phototropism) and their roots grow downward because of gravity (gravitropism). That is why leaves always face the sun.", "bis": "Motubag ang tanom sa palibot niini (tropism): motubo kini paingon sa kahayag (phototropism) ug motubo ang gamot paubos tungod sa gravity (gravitropism). Mao nga kanunay nag-atubang sa adlaw ang mga dahon."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "matter-chemical-reaction-g7", "domain": "MATTER", "topic": "chemical reactions", "grades": [7, 8], "terms": ["chemical reaction", "new substance", "signs", "pagkalawang", "pagpagawas", "pagkataya", "paglabas", "pagporma", "pagbula", "pagbuo", "tanda", "baho", "pagsusunog"], "fact": {"tl": "Sa chemical reaction, ang mga sangkap ay nagbabago at bumubuo ng bagong sangkap. Mga tanda nito: pagbabago ng kulay, paglabas ng init o liwanag, pagbula (gas), o pagbuo ng usok o amoy. Halimbawa: pagsusunog at pagkalawang.", "en": "In a chemical reaction, substances change and form new substances. Signs of it: a color change, giving off heat or light, bubbling (gas), or forming smoke or a smell. Examples: burning and rusting.", "bis": "Sa chemical reaction, ang mga sustansya mausab ug maghimo og bag-ong sustansya. Mga timaan: pagbag-o sa kolor, pagpagawas og kainit o kahayag, pagbula (gas), o pagporma og aso o baho. Pananglitan: pagsunog ug pagkataya."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-combustion-g7", "domain": "MATTER", "topic": "combustion", "grades": [6, 7], "terms": ["combustion", "fire", "fuel", "oxygen", "heat", "nangangailangan", "mamamatay", "mapalong", "gatong", "alisin", "sugnod", "taboni", "kuhaa", "apoy", "pagsusunog"], "fact": {"tl": "Ang combustion (pagsusunog) ay isang chemical reaction na nangangailangan ng tatlong bagay (fire triangle): gatong (fuel), oxygen, at init. Alisin ang isa — halimbawa, takpan ang apoy para mawala ang oxygen — at mamamatay ang apoy.", "en": "Combustion (burning) is a chemical reaction that needs three things (the fire triangle): fuel, oxygen, and heat. Remove one — for example, cover a flame to cut off oxygen — and the fire goes out.", "bis": "Ang combustion (pagsunog) usa ka chemical reaction nga nagkinahanglan og tulo ka butang (fire triangle): sugnod (fuel), oxygen, ug kainit. Kuhaa ang usa — pananglitan, taboni ang kalayo aron mawala ang oxygen — ug mapalong ang kalayo."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-plastics-synthetic-g6", "domain": "MATTER", "topic": "natural and synthetic materials", "grades": [6, 7], "terms": ["natural", "synthetic", "plastic", "materials", "mabulok", "basura", "gapas", "materyales", "karaniwang", "madunot", "plastik", "matibay", "galing", "bulak"], "fact": {"tl": "Ang ilang materyales ay natural (tulad ng kahoy, bulak, at bakal mula sa lupa); ang iba ay synthetic o gawa ng tao (tulad ng plastik at nylon, na karaniwang galing sa langis). Matibay ang plastik pero mabagal mabulok, kaya nagiging basura.", "en": "Some materials are natural (like wood, cotton, and metal from the earth); others are synthetic or human-made (like plastic and nylon, usually made from oil). Plastic is durable but breaks down very slowly, so it becomes waste.", "bis": "Ang ubang materyales natural (sama sa kahoy, gapas, ug puthaw gikan sa yuta); ang uban synthetic o hinimo sa tawo (sama sa plastik ug nylon, kasagaran gikan sa lana). Lig-on ang plastik apan hinay madunot, mao nga mahimong basura."}, "source": "DepEd Science CG (Matter); NRC PS1", "generator": "claude", "reviewed": false},
  {"id": "fme-pressure-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "pressure", "grades": [6, 7, 8], "terms": ["pressure", "force", "area", "needle", "nagbabawas", "tumutusok", "gipunting", "nakatuon", "talinis", "motusok", "matalas", "karayom", "dagom", "malapad"], "fact": {"tl": "Ang pressure ay ang force na nakatuon sa isang lugar (force kada area). Mas matalas na bagay = mas maliit na area = mas malakas na pressure, kaya tumutusok ang karayom. Ang malapad na area (tulad ng snowshoes o gulong) ay nagbabawas ng pressure.", "en": "Pressure is force concentrated on an area (force per area). A sharper object = smaller area = greater pressure, which is why a needle pokes through. A wider area (like snowshoes or tires) lowers the pressure.", "bis": "Ang pressure mao ang force nga gipunting sa usa ka dapit (force kada area). Mas talinis nga butang = mas gamay nga area = mas kusog nga pressure, mao nga motusok ang dagom. Ang lapad nga area (sama sa snowshoes o ligid) mokunhod sa pressure."}, "source": "NRC PS2; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-momentum-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "momentum", "grades": [8, 9, 10], "terms": ["momentum", "mass", "speed", "motion", "nakadepende", "nagdepende", "pahunongon", "pahintuin", "trak", "mapanganib", "peligroso", "mahirap", "katulin", "bilis"], "fact": {"tl": "Ang momentum ay ang lakas ng galaw ng isang bagay — nakadepende sa mass at bilis nito. Mas mahirap pahintuin ang mabigat at mabilis na bagay (tulad ng trak) kaysa magaan o mabagal — kaya mas mapanganib ito.", "en": "Momentum is the strength of an object's motion — it depends on its mass and speed. A heavy, fast object (like a truck) is harder to stop than a light or slow one — which is why it is more dangerous.", "bis": "Ang momentum mao ang kakusog sa lihok sa usa ka butang — nagdepende sa mass ug katulin niini. Mas lisod pahunongon ang bug-at ug paspas nga butang (sama sa trak) kaysa gaan o hinay — mao nga mas peligroso kini."}, "source": "NRC PS2.A", "generator": "claude", "reviewed": false},
  {"id": "fme-lever-fulcrum-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lever and fulcrum", "grades": [5, 6, 7], "terms": ["lever", "fulcrum", "simple machine", "force", "panghukay", "magbuhat", "gunting", "barita", "punto", "olang", "bara", "alsa", "kaunting", "matigas"], "fact": {"tl": "Ang lever ay isang matigas na bara na gumagalaw sa isang punto na tinatawag na fulcrum. Ginagamit ito para magbuhat ng mabigat gamit ang mas kaunting force — tulad ng seesaw, gunting, o panghukay (crowbar).", "en": "A lever is a stiff bar that turns on a point called the fulcrum. It is used to lift heavy things with less force — like a seesaw, scissors, or a crowbar.", "bis": "Ang lever usa ka gahi nga olang nga molihok sa usa ka punto nga gitawag og fulcrum. Gigamit kini aron pag-alsa og bug-at gamit ang mas gamay nga force — sama sa seesaw, gunting, o barita (crowbar)."}, "source": "DepEd Science CG (FME); AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "fme-lenses-mirrors-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lenses and mirrors", "grades": [6, 7], "terms": ["lens", "mirror", "light", "reflection", "magnify", "nagbabalik", "repleksyon", "palakihin", "antiyohos", "materyal", "padakuon", "pokuhin", "larawan", "reflect", "nagbabaluktot"], "fact": {"tl": "Ang lens ay malinaw na materyal (tulad ng salamin) na nagbabaluktot ng liwanag para palakihin o pa-pokuhin ang larawan — ginagamit sa salamin sa mata at magnifying glass. Ang mirror naman ay nagbabalik (reflect) ng liwanag para makita natin ang repleksyon.", "en": "A lens is a clear material (like glass) that bends light to enlarge or focus an image — used in eyeglasses and magnifying glasses. A mirror reflects light so we see a reflection.", "bis": "Ang lens usa ka tin-aw nga materyal (sama sa salamin) nga mobawog sa kahayag aron padakuon o i-focus ang hulagway — gigamit sa antiyohos ug magnifying glass. Ang mirror mobalik (reflect) sa kahayag aron makita nato ang repleksyon."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "fme-electromagnet-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnet", "grades": [7, 8], "terms": ["electromagnet", "electricity", "magnetism", "coil", "nakapulupot", "pinatay", "giliyok", "patyon", "pagka", "motor", "crane", "gihimo", "dumaloy", "nawawala"], "fact": {"tl": "Ang electromagnet ay magnet na gawa gamit ang kuryente — kapag dumaloy ang kuryente sa wire na nakapulupot sa bakal, nagiging magnet ito; kapag pinatay ang kuryente, nawawala ang pagka-magnet. Ginagamit ito sa mga motor at junkyard crane.", "en": "An electromagnet is a magnet made using electricity — when current flows through a wire coiled around iron, it becomes a magnet; turn the current off and the magnetism stops. It is used in motors and junkyard cranes.", "bis": "Ang electromagnet usa ka magnet nga gihimo gamit ang kuryente — kung moagos ang kuryente sa wire nga giliyok sa puthaw, mahimo kining magnet; kung patyon ang kuryente, mawala ang pagka-magnet. Gigamit kini sa mga motor ug junkyard crane."}, "source": "NRC PS2.B; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-friction-uses-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "useful and harmful friction", "grades": [5, 6], "terms": ["friction", "grip", "brakes", "wear", "nadaragdagan", "nakakaabala", "nagpapaubos", "nababawasan", "madugangan", "makasamok", "mokutkot", "sapatos", "preno", "pakinabang"], "fact": {"tl": "Minsan kapaki-pakinabang ang friction (tulad ng grip ng sapatos at preno ng sasakyan), at minsan nakakaabala (nagpapaubos ng gamit at gumagawa ng init). Nababawasan ang friction gamit ang langis o gulong; nadaragdagan gamit ang magaspang na ibabaw.", "en": "Sometimes friction is useful (like the grip of shoes and a car's brakes), and sometimes it is a nuisance (it wears things out and makes heat). Friction is reduced with oil or wheels; it is increased with rough surfaces.", "bis": "Usahay mapuslanon ang friction (sama sa grip sa sapatos ug preno sa sakyanan), ug usahay makasamok (mokutkot sa gamit ug maghimo og kainit). Makunhuran ang friction gamit ang lana o ligid; madugangan gamit ang gansang nga nawong."}, "source": "NRC PS2.A", "generator": "claude", "reviewed": false},
  {"id": "earth-groundwater-g6", "domain": "EARTH_SPACE", "topic": "groundwater", "grades": [6, 7], "terms": ["groundwater", "well", "underground", "water"], "fact": {"tl": "Ang ilang tubig-ulan ay sumisipsip sa lupa at naiimbak sa ilalim sa pagitan ng mga bato at buhangin — ito ang groundwater. Kinukuha natin ito gamit ang poso o balon (well) para inumin at pang-irigasyon.", "en": "Some rainwater soaks into the ground and is stored underground between rocks and sand — this is groundwater. We get it using wells for drinking and irrigation.", "bis": "Ang ubang tubig-ulan mosuyop sa yuta ug matipig sa ilalom taliwala sa mga bato ug balas — kini ang groundwater. Kuhaon nato kini gamit ang atabay (well) para imnon ug irigasyon."}, "source": "NRC ESS2.C", "generator": "claude", "reviewed": false},
  {"id": "earth-ocean-currents-g7", "domain": "EARTH_SPACE", "topic": "ocean currents", "grades": [7, 8], "terms": ["ocean current", "heat", "climate", "sea", "kaparat", "nakakaapekto", "makaapekto", "kalainan", "magdala", "ilog", "alat", "suba", "pagkakaiba", "kalibutan"], "fact": {"tl": "Ang ocean currents ay parang mga 'ilog' sa loob ng dagat na gumagalaw dahil sa hangin, init, at pagkakaiba ng alat at temperatura. Nagdadala ang mga ito ng init sa buong mundo at nakakaapekto sa klima.", "en": "Ocean currents are like 'rivers' within the sea that move because of wind, heat, and differences in saltiness and temperature. They carry heat around the world and affect climate.", "bis": "Ang ocean currents sama sa mga 'suba' sa sulod sa dagat nga molihok tungod sa hangin, kainit, ug kalainan sa kaparat ug temperatura. Magdala kini og kainit sa tibuok kalibutan ug makaapekto sa klima."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "earth-habagat-amihan-g6", "domain": "EARTH_SPACE", "topic": "monsoons habagat and amihan", "grades": [5, 6, 7], "terms": ["monsoon", "habagat", "amihan", "wind", "season"], "fact": {"tl": "Sa Pilipinas, may dalawang monsoon: ang habagat (timog-kanlurang hangin, mga Hunyo–Setyembre, nagdadala ng ulan) at ang amihan (hilagang-silangang hangin, mga Oktubre–Marso, malamig at tuyo). Ang mga ito ang nagtatakda ng panahon natin.", "en": "In the Philippines there are two monsoons: the habagat (southwest wind, about June–September, bringing rain) and the amihan (northeast wind, about October–March, cool and dry). They set our seasons.", "bis": "Sa Pilipinas, adunay duha ka monsoon: ang habagat (habagatan-kasadpan nga hangin, mga Hunyo–Setyembre, modala og ulan) ug ang amihan (amihanan-sidlakan nga hangin, mga Oktubre–Marso, bugnaw ug uga). Kini maoy magtakda sa atong panahon."}, "source": "NRC ESS2.D (climate); DepEd Science CG", "generator": "claude", "reviewed": false},
  {"id": "earth-ph-volcanoes-g6", "domain": "EARTH_SPACE", "topic": "Philippine volcanoes", "grades": [5, 6, 7], "terms": ["volcano", "Mayon", "Taal", "Pinatubo", "Ring of Fire", "pinakagamay", "perpektong", "bantogan", "kilala", "mibuto", "ilado", "niadtong", "hapit", "kono", "sumabog"], "fact": {"tl": "Maraming bulkan sa Pilipinas dahil nasa Pacific Ring of Fire ito. Kabilang sa mga sikat: ang Mayon (kilala sa halos perpektong hugis-kono), ang Taal (isa sa pinakamaliit sa mundo), at ang Pinatubo (sumabog nang malakas noong 1991).", "en": "The Philippines has many volcanoes because it sits on the Pacific Ring of Fire. Famous ones include Mayon (known for its near-perfect cone shape), Taal (one of the smallest in the world), and Pinatubo (which erupted powerfully in 1991).", "bis": "Daghang bulkan sa Pilipinas kay anaa kini sa Pacific Ring of Fire. Lakip sa bantogan: ang Mayon (ilado sa hapit hingpit nga porma-kono), ang Taal (usa sa pinakagamay sa kalibutan), ug ang Pinatubo (mibuto og kusog niadtong 1991)."}, "source": "NRC ESS2.B; DepEd Science CG", "generator": "claude", "reviewed": false},
  {"id": "earth-minerals-vs-rocks-g6", "domain": "EARTH_SPACE", "topic": "minerals and rocks", "grades": [6, 7], "terms": ["mineral", "rock", "quartz", "composition", "komposisyon", "magkakasama", "magkauban", "kuwarts", "bulawan", "ginto", "iisang", "higit", "asin", "hinimo"], "fact": {"tl": "Ang mineral ay natural na solid na may iisang uri ng komposisyon (tulad ng kuwarts, ginto, at asin-bato). Ang bato (rock) ay gawa sa isa o higit pang mineral na magkakasama. Kaya ang mineral ang building blocks ng mga bato.", "en": "A mineral is a natural solid with one kind of composition (like quartz, gold, and rock salt). A rock is made of one or more minerals together. So minerals are the building blocks of rocks.", "bis": "Ang mineral usa ka natural nga solid nga adunay usa ka klase nga komposisyon (sama sa kuwarts, bulawan, ug asin-bato). Ang bato (rock) hinimo sa usa o sobra pa nga mineral nga magkauban. Mao nga ang mineral mao ang building blocks sa mga bato."}, "source": "NRC ESS2.A", "generator": "claude", "reviewed": false},
  {"id": "earth-constellations-g5", "domain": "EARTH_SPACE", "topic": "constellations", "grades": [5, 6], "terms": ["constellation", "stars", "pattern", "Orion", "paglalakbay", "sinaunang", "pagsasaka", "ginganlan", "pagbiyahe", "binigyan", "pangalan", "kaniadto", "gabay", "noon"], "fact": {"tl": "Ang constellation ay grupo ng mga bituin na bumubuo ng parang larawan sa langit, na binigyan ng pangalan ng mga sinaunang tao (tulad ng Orion at Southern Cross). Ginagamit ito noon bilang gabay sa paglalakbay at pagsasaka.", "en": "A constellation is a group of stars that forms a picture-like pattern in the sky, named by ancient people (like Orion and the Southern Cross). It was once used as a guide for travel and farming.", "bis": "Ang constellation usa ka grupo sa mga bituon nga maghimo og morag hulagway sa langit, nga ginganlan sa karaang mga tawo (sama sa Orion ug Southern Cross). Gigamit kini kaniadto isip giya sa pagbiyahe ug pag-uma."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-where-sun-goes-night", "domain": "EARTH_SPACE", "topic": "where the sun goes at night", "grades": [3, 4], "terms": ["sun", "night", "rotation", "Earth", "umaalis", "mobiya", "tumatalikod", "motalikod", "panig", "kalibutan", "pikas", "gyud", "kabilang", "mundo"], "fact": {"tl": "Hindi talaga 'umaalis' ang araw sa gabi — umiikot lang ang Earth, kaya tumatalikod ang ating panig sa araw. Habang gabi sa atin, araw naman sa kabilang panig ng mundo.", "en": "The sun does not really 'go away' at night — the Earth just turns, so our side faces away from the sun. While it is night for us, it is day on the other side of the world.", "bis": "Wala gyud 'mobiya' ang adlaw sa gabii — molibot lang ang Earth, mao nga motalikod ang atong bahin sa adlaw. Samtang gabii kanato, adlaw sa pikas bahin sa kalibutan."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-how-electricity-made", "domain": "FORCE_MOTION_ENERGY", "topic": "how electricity is generated", "grades": [6, 7], "terms": ["electricity", "generator", "turbine", "power plant", "pinapaikot", "gipatuyok", "pagtuyok", "ikot", "nagaagos", "gihimo", "bahay", "balay", "wire", "kadaghanan"], "fact": {"tl": "Karamihan ng kuryente ay ginagawa sa power plant gamit ang generator: pinapaikot ang isang turbine (gamit ang singaw, umaagos na tubig, o hangin), at ang pag-ikot na ito ay nagbibigay ng electrical energy na dumadaloy sa mga wire papunta sa ating mga bahay.", "en": "Most electricity is made in a power plant using a generator: a turbine is spun (by steam, flowing water, or wind), and that spinning produces electrical energy that flows through wires to our homes.", "bis": "Kadaghanan sa kuryente gihimo sa power plant gamit ang generator: gipatuyok ang usa ka turbine (gamit ang alisngaw, nagaagos nga tubig, o hangin), ug kana nga pagtuyok maghatag og electrical energy nga moagos sa mga wire paingon sa atong mga balay."}, "source": "NRC PS3.A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-metal-hot-in-sun", "domain": "FORCE_MOTION_ENERGY", "topic": "why metal feels hot in the sun", "grades": [5, 6], "terms": ["metal", "heat", "conductor", "sun", "sumipsip", "hikapon", "hawakan", "maayo", "mahusay", "uminit", "labas", "mosuyop", "parehas", "moinit"], "fact": {"tl": "Mas mabilis uminit ang metal sa araw dahil mahusay itong conductor ng init at mabilis sumipsip ng init mula sa araw. Kaya mas mainit hawakan ang metal kaysa kahoy kahit pareho silang nasa labas.", "en": "Metal heats up quickly in the sun because it is a good conductor of heat and absorbs the sun's heat fast. That is why metal feels hotter to touch than wood, even when both are outside.", "bis": "Mas paspas moinit ang metal sa adlaw kay maayo kining conductor sa kainit ug paspas mosuyop sa kainit gikan sa adlaw. Mao nga mas init hikapon ang metal kaysa kahoy bisan parehas silang naa sa gawas."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-water-steams", "domain": "MATTER", "topic": "why hot water steams", "grades": [5, 6], "terms": ["steam", "evaporation", "condensation", "vapor"], "fact": {"tl": "Umuusok ang mainit na tubig dahil sumisingaw (evaporation) ito, at kapag ang mainit na singaw ay tumama sa malamig na hangin, nagiging maliliit na patak ito muli (condensation) na nakikita natin bilang 'usok' o singaw.", "en": "Hot water 'steams' because it evaporates, and when the hot vapor meets cooler air it turns back into tiny droplets (condensation) that we see as 'steam'.", "bis": "Moaso ang init nga tubig kay mo-alisngaw (evaporation) kini, ug kung ang init nga alisngaw motagbo sa bugnaw nga hangin, mahimo kining gagmay nga tulo pag-usab (condensation) nga atong makita isip 'aso' o alisngaw."}, "source": "AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-eat", "domain": "LIVING_THINGS", "topic": "why we eat", "grades": [3, 4], "terms": ["kumakain", "kaon", "mokaon", "pagkaon", "eat", "food", "energy", "enerhiya", "nutrients", "sustansya"], "fact": {"tl": "Kumakain tayo para makakuha ng enerhiya at sustansya (nutrients) na kailangan ng katawan para gumalaw, lumaki, at ayusin ang sarili. Ang pagkain ang parang 'gasolina' ng katawan.", "en": "We eat to get energy and nutrients the body needs to move, grow, and repair itself. Food is like the body's 'fuel'.", "bis": "Mokaon ta aron makakuha og enerhiya ug sustansya (nutrients) nga gikinahanglan sa lawas aron molihok, motubo, ug ayohon ang kaugalingon. Ang pagkaon sama sa 'gasolina' sa lawas."}, "source": "AAAS BSL Ch.6; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-sleep", "domain": "LIVING_THINGS", "topic": "why we sleep", "grades": [3, 4], "terms": ["natutulog", "tulog", "matulog", "sleep", "rest", "pahinga", "utak", "utok", "brain"], "fact": {"tl": "Natutulog tayo para makapagpahinga at makabawi ang katawan at utak. Habang tulog, naaayos ang mga cell, lumalakas ang immune system, at iniimbak ng utak ang mga natutunan natin.", "en": "We sleep so the body and brain can rest and recover. During sleep, cells repair, the immune system strengthens, and the brain stores what we learned.", "bis": "Matulog ta aron makapahulay ug makabawi ang lawas ug utok. Samtang natulog, mareparar ang mga cell, molig-on ang immune system, ug tipigan sa utok ang atong nakat-unan."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "faq-how-birds-fly", "domain": "FORCE_MOTION_ENERGY", "topic": "how birds and planes fly", "grades": [5, 6], "terms": ["lumilipad", "lupad", "molupad", "fly", "ibon", "langgam", "bird", "eroplano", "airplane", "pakpak", "pako", "wings", "lift"], "fact": {"tl": "Lumilipad ang ibon at eroplano dahil sa hugis ng kanilang pakpak (wings): mas mabilis dumaloy ang hangin sa ibabaw ng pakpak kaysa sa ilalim, na lumilikha ng lift na nagtataas sa kanila.", "en": "Birds and planes fly because of the shape of their wings: air flows faster over the top of the wing than underneath, creating lift that pushes them up.", "bis": "Molupad ang langgam ug eroplano tungod sa porma sa ilang pako (wings): mas paspas moagos ang hangin sa ibabaw sa pako kaysa sa ilawom, nga maghimo og lift nga mopataas kanila."}, "source": "NRC PS2 (forces); AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "faq-why-rocks-sink", "domain": "MATTER", "topic": "why rocks sink", "grades": [4, 5], "terms": ["lumulubog", "lubog", "molunod", "sink", "bato", "rock", "density", "mabigat", "bug-at"], "fact": {"tl": "Lumulubog ang bato dahil mas siksik (mas mataas ang density) ito kaysa tubig — mas mabigat ang bato kaysa katumbas nitong dami ng tubig, kaya bumababa ito.", "en": "A rock sinks because it is denser (higher density) than water — the rock is heavier than the same amount of water, so it goes down.", "bis": "Molunod ang bato kay mas siksik (mas taas ang density) kini kaysa tubig — mas bug-at ang bato kaysa katumbas niini nga gidaghanon sa tubig, mao nga mokanaog kini."}, "source": "AAAS BSL Ch.4D (density)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-feel-cold", "domain": "FORCE_MOTION_ENERGY", "topic": "why we feel cold", "grades": [4, 5], "terms": ["nilalamig", "lamig", "tugnaw", "cold", "init", "heat", "temperatura", "nanginginig", "kurog", "shiver"], "fact": {"tl": "Nilalamig tayo kapag mas mababa ang temperatura ng paligid kaysa katawan, kaya tumatakas ang init mula sa atin. Nanginginig tayo para gumawa ng init at magpainit ng katawan.", "en": "We feel cold when the surroundings are colder than our body, so heat escapes from us. We shiver to make heat and warm the body.", "bis": "Tugnawon ta kung mas ubos ang temperatura sa palibot kaysa lawas, mao nga mogawas ang kainit gikan kanato. Mokurog ta aron maghimo og kainit ug painiton ang lawas."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-it-rains", "domain": "EARTH_SPACE", "topic": "why it rains", "grades": [3, 4], "terms": ["umuulan", "ulan", "moulan", "rain", "ulap", "panganod", "clouds", "patak", "tulo"], "fact": {"tl": "Umuulan kapag ang mga patak ng tubig sa ulap ay nagsasama-sama at lumalaki, hanggang sa maging masyadong mabigat para lumutang — kaya bumabagsak sila bilang ulan.", "en": "It rains when the tiny water droplets in clouds join and grow until they are too heavy to float — so they fall as rain.", "bis": "Moulan kung ang mga tulo sa tubig sa panganod magtapok ug modako, hangtod nga mabug-at na kaayo aron molutaw — mao nga mahulog sila isip ulan."}, "source": "AAAS BSL Ch.4B (water cycle)", "generator": "claude", "reviewed": false},
  {"id": "faq-where-wind-comes-from", "domain": "EARTH_SPACE", "topic": "where wind comes from", "grades": [4, 5], "terms": ["hangin", "wind", "init", "heat", "habagat", "amihan", "air", "galaw"], "fact": {"tl": "Galing ang hangin sa hindi pantay na pag-init ng araw sa Earth. Ang mainit na hangin ay tumataas, at ang malamig na hangin ay pumapalit dito — ang paggalaw na ito ng hangin ang tinatawag nating hangin.", "en": "Wind comes from the uneven heating of Earth by the sun. Warm air rises and cooler air moves in to take its place — that moving air is wind.", "bis": "Naggikan ang hangin sa dili patas nga pag-init sa adlaw sa Earth. Ang init nga hangin mosaka, ug ang bugnaw nga hangin mopuli niini — kana nga paglihok sa hangin mao ang gitawag natong hangin."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "faq-how-plants-grow", "domain": "LIVING_THINGS", "topic": "how plants grow", "grades": [3, 4], "terms": ["tumutubo", "tubo", "motubo", "grow", "halaman", "tanom", "plant", "buto", "liso", "seed", "photosynthesis"], "fact": {"tl": "Tumutubo ang halaman mula sa buto kapag may tubig, hangin, init, at liwanag. Gumagawa ito ng sariling pagkain sa photosynthesis, na nagpapalaki ng ugat, tangkay, at dahon.", "en": "A plant grows from a seed when there is water, air, warmth, and light. It makes its own food by photosynthesis, which grows its roots, stem, and leaves.", "bis": "Motubo ang tanom gikan sa liso kung adunay tubig, hangin, kainit, ug kahayag. Maghimo kini og kaugalingong pagkaon pinaagi sa photosynthesis, nga magpadako sa gamot, punoan, ug dahon."}, "source": "AAAS BSL Ch.5; NRC LS1", "generator": "claude", "reviewed": false},
  {"id": "faq-why-leaves-fall", "domain": "LIVING_THINGS", "topic": "why leaves fall", "grades": [4, 5], "terms": ["nalalagas", "laglag", "kahulog", "dahon", "leaves", "fall", "matanda", "tigulang"], "fact": {"tl": "Nalalagas ang mga dahon kapag matanda na ang mga ito o kapag kulang sa tubig at liwanag ang halaman — itinatapon ng halaman ang lumang dahon para makatipid ng enerhiya at makapagpalago ng bago.", "en": "Leaves fall when they grow old or when the plant lacks water and light — the plant drops old leaves to save energy and grow new ones.", "bis": "Mangahulog ang mga dahon kung tigulang na o kung kulang sa tubig ug kahayag ang tanom — ilabay sa tanom ang daan nga dahon aron makatipig og enerhiya ug makapatubo og bag-o."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "faq-why-sky-dark-night", "domain": "EARTH_SPACE", "topic": "why the sky is dark at night", "grades": [4, 5], "terms": ["madilim", "langit", "gabi", "ngitngit", "dark", "night", "liwanag", "araw", "sun"], "fact": {"tl": "Madilim ang langit sa gabi dahil tumatalikod ang ating panig ng Earth sa araw, kaya walang sikat ng araw na ikinakalat ng hangin para gawing maliwanag ang langit.", "en": "The sky is dark at night because our side of Earth faces away from the sun, so there is no sunlight for the air to scatter and brighten the sky.", "bis": "Ngitngit ang langit sa gabii kay motalikod ang atong bahin sa Earth sa adlaw, mao nga walay silaw sa adlaw nga ikatag sa hangin aron pahayagon ang langit."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-how-fish-breathe", "domain": "LIVING_THINGS", "topic": "how fish breathe", "grades": [4, 5], "terms": ["isda", "fish", "huminga", "ginhawa", "hasang", "gills", "oxygen", "tubig", "underwater"], "fact": {"tl": "Humihinga ang isda gamit ang hasang (gills), hindi baga. Dumadaan ang tubig sa hasang, at kinukuha nito ang oxygen na natunaw sa tubig — kaya nabubuhay ang isda sa ilalim ng tubig.", "en": "Fish breathe using gills, not lungs. Water passes through the gills, which take in the oxygen dissolved in the water — that is how fish live underwater.", "bis": "Moginhawa ang isda gamit ang hasang (gills), dili baga. Moagi ang tubig sa hasang, ug kuhaon niini ang oxygen nga natunaw sa tubig — mao nga mabuhi ang isda sa ilawom sa tubig."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-stars-not-day", "domain": "EARTH_SPACE", "topic": "why we don't see stars in daytime", "grades": [4, 5], "terms": ["bituin", "bituon", "stars", "araw", "day", "adlaw", "liwanag", "hayag"], "fact": {"tl": "Hindi natin nakikita ang mga bituin sa araw dahil masyadong maliwanag ang langit mula sa sikat ng araw. Naroon pa rin ang mga bituin — natatabunan lang sila ng maliwanag na langit.", "en": "We don't see stars in the daytime because the sky is too bright from sunlight. The stars are still there — they are just hidden by the bright sky.", "bis": "Dili nato makita ang mga bituon sa adlaw kay sobra ka hayag ang langit gikan sa silaw sa adlaw. Naa pa gihapon ang mga bituon — gitabonan lang sila sa hayag nga langit."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-astronauts-float", "domain": "EARTH_SPACE", "topic": "why astronauts float in space", "grades": [6, 7], "terms": ["astronaut", "lumulutang", "lutaw", "float", "space", "gravity", "weightless", "bigat"], "fact": {"tl": "Lumulutang ang astronaut dahil sila at ang kanilang spaceship ay parehong patuloy na 'nahuhulog' papunta sa Earth habang umiikot sa paligid nito — kaya wala silang nararamdamang bigat (weightless), hindi dahil walang gravity sa space.", "en": "Astronauts float because they and their spaceship are both constantly 'falling' toward Earth while circling around it — so they feel weightless. It is not because there is no gravity in space.", "bis": "Molutaw ang astronaut kay sila ug ang ilang spaceship parehong padayon nga 'nahulog' paingon sa Earth samtang molibot niini — mao nga wala silay bati nga gibug-aton (weightless), dili tungod kay walay gravity sa space."}, "source": "NRC PS2.B (gravity)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-moon-follows", "domain": "EARTH_SPACE", "topic": "why the moon seems to follow you", "grades": [4, 5], "terms": ["buwan", "bulan", "moon", "sumusunod", "sunod", "follow", "layo"], "fact": {"tl": "Parang sumusunod ang buwan habang naglalakad ka dahil napakalayo nito — hindi gaanong nagbabago ang anggulo ng tingin mo dito kahit gumagalaw ka, kaya mukhang kasabay mo ito.", "en": "The moon seems to follow you as you walk because it is so far away — your viewing angle to it barely changes even as you move, so it looks like it is keeping pace with you.", "bis": "Morag mosunod ang bulan samtang naglakaw ka kay layo kaayo kini — dili kaayo mausab ang anggulo sa imong pagtan-aw niini bisan molihok ka, mao nga morag kauban nimo kini."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-not-fall-off-earth", "domain": "EARTH_SPACE", "topic": "why we don't fall off the Earth", "grades": [4, 5], "terms": ["gravity", "Earth", "nahuhulog", "hulog", "fall", "bilog", "lingin", "round", "gitna", "tunga"], "fact": {"tl": "Hindi tayo nahuhulog mula sa Earth kahit bilog ito dahil hinihila tayo ng gravity papunta sa gitna ng planeta — kaya 'pababa' para sa atin ay laging papunta sa gitna ng Earth, saan man tayo nakatayo.", "en": "We don't fall off the Earth even though it is round because gravity pulls us toward the center of the planet — so 'down' for us is always toward Earth's center, no matter where we stand.", "bis": "Dili ta mahulog gikan sa Earth bisan lingin kini kay gibira ta sa gravity paingon sa tunga sa planeta — mao nga ang 'paubos' para kanato kanunay paingon sa tunga sa Earth, bisan asa ta magbarog."}, "source": "NRC PS2.B (gravity)", "generator": "claude", "reviewed": false},
  {"id": "living-digestion-enzymes-g6", "domain": "LIVING_THINGS", "topic": "digestion and enzymes", "grades": [6, 7], "terms": ["enzyme", "laway", "saliva", "digestion", "tunaw", "hilis", "starch", "almirol", "kanin"], "fact": {"tl": "Tumutulong ang mga enzyme sa pagtunaw ng pagkain. Halimbawa, may enzyme sa laway (saliva) na nagsisimulang maglansag ng starch (almirol) sa bibig — kaya tumatamis ang kanin kapag matagal mong nginuya.", "en": "Enzymes help digest food. For example, an enzyme in saliva begins breaking down starch in the mouth — which is why rice tastes sweet if you chew it for a while.", "bis": "Motabang ang mga enzyme sa paghilis sa pagkaon. Pananglitan, adunay enzyme sa laway (saliva) nga mosugod sa pagguba sa starch (almidor) sa baba — mao nga motam-is ang kan-on kung dugay nimong usapon."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-blood-cells-g7", "domain": "LIVING_THINGS", "topic": "blood cells", "grades": [7, 8], "terms": ["dugo", "blood", "red blood cells", "white blood cells", "platelets", "oxygen", "cell"], "fact": {"tl": "May tatlong uri ng cell sa dugo: ang red blood cells (nagdadala ng oxygen), ang white blood cells (lumalaban sa sakit), at ang platelets (tumutulong sa pamumuo ng dugo kapag may sugat).", "en": "There are three kinds of cells in blood: red blood cells (carry oxygen), white blood cells (fight disease), and platelets (help blood clot when there is a wound).", "bis": "Adunay tulo ka klase sa cell sa dugo: ang red blood cells (modala og oxygen), ang white blood cells (mosukol sa sakit), ug ang platelets (motabang sa pagmugna sa dugo kung adunay samad)."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "earth-dew-frost-g6", "domain": "EARTH_SPACE", "topic": "dew and frost", "grades": [5, 6], "terms": ["hamog", "yamog", "dew", "frost", "condensation", "yelo", "damo"], "fact": {"tl": "Ang hamog (dew) ay tubig na nabubuo kapag ang singaw sa hangin ay lumamig at nagiging patak sa mga damo sa umaga (condensation). Kapag napakalamig (below 0°C), nagiging frost o namuong yelo ito.", "en": "Dew is water that forms when vapor in the air cools and becomes droplets on grass in the morning (condensation). When it is very cold (below 0°C), it becomes frost (frozen dew).", "bis": "Ang yamog (dew) mao ang tubig nga maporma kung ang alisngaw sa hangin mobugnaw ug mahimong tulo sa mga sagbot sa buntag (condensation). Kung bugnaw kaayo (ubos sa 0°C), mahimo kining frost o nagyelo nga yamog."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-lightning-g6", "domain": "EARTH_SPACE", "topic": "how lightning forms", "grades": [6, 7], "terms": ["kidlat", "kilat", "lightning", "static electricity", "charge", "ulap", "panganod", "kuryente"], "fact": {"tl": "Ang kidlat (lightning) ay isang malaking static electricity na lumalabas sa pagitan ng mga ulap o sa pagitan ng ulap at lupa, kapag napakaraming charge na ang naipon sa loob ng bagyo.", "en": "Lightning is a giant spark of static electricity that jumps between clouds, or between a cloud and the ground, when a lot of charge has built up inside a storm.", "bis": "Ang kilat (lightning) usa ka dako nga static electricity nga mogawas tali sa mga panganod o tali sa panganod ug yuta, kung daghan na kaayong charge ang natigom sulod sa unos."}, "source": "AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "earth-fog-g5", "domain": "EARTH_SPACE", "topic": "fog", "grades": [5, 6], "terms": ["fog", "gabon", "ambon", "ulap", "panganod", "singaw", "alisngaw", "condensation"], "fact": {"tl": "Ang ulap-lupa o fog ay parang ulap na nasa lupa: nabubuo ito kapag ang singaw ng tubig sa malamig na hangin ay nagiging maliliit na patak na lumulutang malapit sa lupa, kaya nahihirapan tayong makakita.", "en": "Fog is like a cloud at ground level: it forms when water vapor in cool air becomes tiny droplets floating near the ground, making it hard to see.", "bis": "Ang gabon o fog sama sa panganod nga anaa sa yuta: maporma kini kung ang alisngaw sa tubig sa bugnaw nga hangin mahimong gagmay nga tulo nga molutaw duol sa yuta, mao nga maglisod ta og kita."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "matter-oil-water-g6", "domain": "MATTER", "topic": "why oil and water don't mix", "grades": [5, 6], "terms": ["langis", "oil", "tubig", "water", "halo", "sagol", "mix", "density", "lutaw"], "fact": {"tl": "Hindi naghahalo ang langis at tubig dahil magkaiba ang kanilang particle at hindi sila 'magkadikit' — kaya naghihiwalay sila. Lumulutang ang langis sa ibabaw dahil mas magaan (mas mababa ang density) ito kaysa tubig.", "en": "Oil and water do not mix because their particles are different and do not 'stick' to each other — so they separate. Oil floats on top because it is lighter (less dense) than water.", "bis": "Dili magsagol ang lana ug tubig kay lahi ang ilang particle ug dili sila 'magdikit' — mao nga magbulag sila. Molutaw ang lana sa ibabaw kay mas gaan (mas ubos ang density) kini kaysa tubig."}, "source": "AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-metals-expand-g7", "domain": "MATTER", "topic": "why metals expand when heated", "grades": [6, 7], "terms": ["metal", "expand", "lumalaki", "modako", "init", "heat", "particle", "urong", "contract"], "fact": {"tl": "Lumalaki (expand) ang metal kapag iniinit at umuurong kapag pinalamig, dahil mas mabilis gumalaw at lumalayo ang mga particle nito sa init. Kaya may maliliit na puwang sa mga tulay at riles ng tren para sa pag-expand.", "en": "Metal expands when heated and contracts when cooled, because its particles move faster and spread apart with heat. That is why bridges and train rails have small gaps to allow for expansion.", "bis": "Modako (expand) ang metal kung initan ug mokunhod kung bugnawon, kay mas paspas molihok ug magkalayo ang mga particle niini sa kainit. Mao nga adunay gamay nga luna sa mga taytayan ug riles sa tren para sa pag-expand."}, "source": "AAAS BSL Ch.4D; NRC PS3", "generator": "claude", "reviewed": false},
  {"id": "living-photosynthesis-respiration-pair-g7", "domain": "LIVING_THINGS", "topic": "photosynthesis and respiration", "grades": [7, 8], "terms": ["photosynthesis", "respiration", "oxygen", "carbon dioxide", "halaman", "tanom", "enerhiya", "siklo"], "fact": {"tl": "Magkaugnay ang photosynthesis at respiration: sa photosynthesis, gumagawa ang halaman ng pagkain at oxygen mula sa carbon dioxide at tubig; sa respiration, ginagamit ng halaman at hayop ang oxygen at pagkain para sa enerhiya at naglalabas ng carbon dioxide. Magkasalungat sila pero magkatuwang sa siklo ng buhay.", "en": "Photosynthesis and respiration are linked: in photosynthesis, plants make food and oxygen from carbon dioxide and water; in respiration, plants and animals use oxygen and food for energy and release carbon dioxide. They are opposites that together keep the cycle of life going.", "bis": "Magkadugtong ang photosynthesis ug respiration: sa photosynthesis, maghimo ang tanom og pagkaon ug oxygen gikan sa carbon dioxide ug tubig; sa respiration, gigamit sa tanom ug hayop ang oxygen ug pagkaon para sa enerhiya ug magbuga og carbon dioxide. Sukwahi sila apan magtinabangay sa siklo sa kinabuhi."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-why-we-grow", "domain": "LIVING_THINGS", "topic": "why we grow", "grades": [4, 5], "terms": ["lumalaki", "tubo", "motubo", "grow", "cell", "protina", "protein", "pagkaon", "building blocks"], "fact": {"tl": "Lumalaki tayo dahil dumarami at lumalaki ang mga cell sa ating katawan. Galing sa pagkain ang mga 'building blocks' (lalo na ang protina) na kailangan para magdagdag ng bagong cell — kaya mahalaga ang masustansyang pagkain sa paglaki.", "en": "We grow because the cells in our body multiply and get bigger. Food provides the 'building blocks' (especially protein) needed to make new cells — so nutritious food is important for growing.", "bis": "Motubo ta kay modaghan ug modako ang mga cell sa atong lawas. Gikan sa pagkaon ang mga 'building blocks' (ilabi na ang protina) nga gikinahanglan aron magdugang og bag-ong cell — mao nga importante ang masustansya nga pagkaon sa pagtubo."}, "source": "AAAS BSL Ch.6; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-soap-cleans-g4", "domain": "MATTER", "topic": "why soap cleans", "grades": [3, 4, 5], "terms": ["sabon", "soap", "langis", "grease", "oil", "dumi", "hugaw", "dirt", "linis", "limpyo", "clean", "molekula"], "fact": {"tl": "Ang sabon ay may mga molekula na ang isang dulo ay kumakapit sa tubig at ang kabilang dulo ay kumakapit sa langis. Kaya nahihila ng sabon ang mantika at dumi palayo sa balat o pinggan, at natatangay ng tubig kapag binanlawan.", "en": "Soap molecules have one end that clings to water and another end that clings to oil. So soap lifts grease and dirt off your skin or dishes, and the water rinses it all away.", "bis": "Ang sabon adunay mga molekula nga ang usa ka tumoy mokupot sa tubig ug ang pikas tumoy mokupot sa lana. Maong makuha sa sabon ang mantika ug hugaw gikan sa panit o plato, ug mabanlasan kini sa tubig."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-bubbles-round-g3", "domain": "MATTER", "topic": "why bubbles are round", "grades": [3, 4], "terms": ["bula", "bubble", "bilog", "lingin", "round", "surface tension", "sabon", "soap", "hangin", "hangin"], "fact": {"tl": "Bilog ang bula dahil hinihila ng surface tension ang manipis na pelikula ng sabon papunta sa pinakamaliit na hugis. Ang bilog (sphere) ang nakakahawak ng pinakamaraming hangin gamit ang pinakaliit na ibabaw.", "en": "Bubbles are round because surface tension pulls the thin soap film into the smallest shape possible, and a sphere holds the most air with the least surface area.", "bis": "Lingin ang bula tungod kay ang surface tension nagbira sa nipis nga pelikula sa sabon ngadto sa kinagamyan nga porma. Ang lingin (sphere) maoy makasulod sa kinadaghanan nga hangin gamit ang kinagamyan nga gawas."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "surface-tension-g4", "domain": "MATTER", "topic": "surface tension", "grades": [4, 5], "terms": ["surface tension", "tubig", "water", "patak", "tulo", "drop", "molekula", "balat ng tubig", "insekto", "insect"], "fact": {"tl": "Ang mga molekula ng tubig ay magkakahila-hila. Sa ibabaw, mas malakas ang hila pababa kaya parang may manipis na 'balat' ang tubig — kaya umaapaw nang kaunti sa basong puno, bumubuo ng patak, at nakakalakad dito ang maliliit na insekto.", "en": "Water molecules pull on each other. At the surface they pull inward and form a thin 'skin' called surface tension — that is why water beads into drops, can dome slightly above a full glass, and lets tiny insects walk on it.", "bis": "Ang mga molekula sa tubig nagbinira-bira sa usag usa. Sa ibabaw mas kusgan ang birahanay maong daw adunay nipis nga 'panit' ang tubig — mao nga maghimog tulo, makaawas gamay sa puno nga baso, ug makalakaw niini ang gagmayng insekto."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-glass-transparent-g5", "domain": "MATTER", "topic": "why glass is transparent", "grades": [5, 6], "terms": ["salamin", "baso", "glass", "transparent", "aninaw", "liwanag", "light", "kuryente? no", "dumadaan ang liwanag"], "fact": {"tl": "Naaaninaw ang salamin dahil hindi sinisipsip o ikinakalat ng mga particle nito ang nakikitang liwanag — dumadaan ang liwanag nang diretso, kaya nakikita natin ang nasa kabila.", "en": "Glass is transparent because its particles do not absorb or scatter visible light — the light passes straight through, so we can see what is on the other side.", "bis": "Aninaw ang salamin tungod kay ang mga partikulo niini dili mosuyop o magkatag sa makita nga kahayag — molahos ang kahayag deretso, maong makita nato ang anaa sa pikas."}, "source": "AAAS BSL Ch.4; NRC PS4.B", "generator": "claude", "reviewed": false},
  {"id": "transparent-translucent-opaque-g4", "domain": "MATTER", "topic": "transparent translucent opaque", "grades": [4, 5], "terms": ["transparent", "translucent", "opaque", "aninaw", "malabo", "makapal", "liwanag", "light", "materyales", "materyal"], "fact": {"tl": "May tatlong uri ng materyales ayon sa pagdaan ng liwanag: transparent (aninaw, malinaw na nakikita tulad ng salamin), translucent (bahagyang dumadaan ang liwanag pero malabo tulad ng papel o frosted glass), at opaque (hindi dumadaan ang liwanag tulad ng kahoy o metal).", "en": "Materials are grouped by how light passes through them: transparent (clear, you see right through, like glass), translucent (some light passes but blurry, like paper or frosted glass), and opaque (no light passes, like wood or metal).", "bis": "Adunay tulo ka klase sa materyales sumala sa pag-agi sa kahayag: transparent (aninaw, klaro makita sama sa salamin), translucent (gamay ra mga-agi ang kahayag apan hanap sama sa papel), ug opaque (walay molahos nga kahayag sama sa kahoy o metal)."}, "source": "AAAS BSL Ch.4; DepEd CG", "generator": "claude", "reviewed": false},
  {"id": "sublimation-g6", "domain": "MATTER", "topic": "sublimation", "grades": [6, 7, 8], "terms": ["sublimation", "solid", "gas", "yelo", "dry ice", "naphthalene", "mothball", "singaw", "aso", "usok"], "fact": {"tl": "Sa sublimation, ang solid ay direktang nagiging gas nang hindi muna nagiging likido. Halimbawa: ang 'dry ice' na parang umuusok, o ang naphthalene balls (alkampor) na unti-unting lumiliit hanggang mawala.", "en": "In sublimation, a solid turns straight into a gas without first becoming a liquid. Examples are dry ice that seems to 'smoke', and mothballs that slowly shrink until they disappear.", "bis": "Sa sublimation, ang solid direktang mahimong gas nga dili una mahimong likido. Pananglitan: ang 'dry ice' nga daw nag-aso, o ang mothballs (alkampor) nga hinay-hinayng mokunhod hangtod mawala."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-we-smell-diffusion-g4", "domain": "MATTER", "topic": "why we can smell things", "grades": [3, 4, 5], "terms": ["amoy", "baho", "kahumot", "smell", "ilong", "ilong", "nose", "diffusion", "particle", "hangin", "kumalat"], "fact": {"tl": "Nakakaamoy tayo dahil may napakaliliit na particle na pumupulas mula sa bagay at kumakalat sa hangin (diffusion) hanggang umabot sa loob ng ating ilong. Kaya naaamoy mo ang ulam kahit nasa kabilang silid ka pa.", "en": "We can smell things because tiny particles drift off them and spread through the air (diffusion) until they reach the inside of our nose. That is why you smell food cooking even from another room.", "bis": "Makasimhot ta tungod kay adunay gagmayng partikulo nga mobuhi gikan sa butang ug mokatag sa hangin (diffusion) hangtod moabot sa sulod sa atong ilong. Mao nga masimhot nimo ang sud-an bisan lain ka og kwarto."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "evaporation-puddles-g3", "domain": "MATTER", "topic": "why puddles dry up", "grades": [3, 4], "terms": ["evaporation", "singaw", "sangag? no", "lusak", "puddle", "natutuyo", "mauga", "tubig", "init", "araw", "singaw ng tubig"], "fact": {"tl": "Natutuyo ang mga lusak dahil binibigyan ng init ng araw ang mga particle ng tubig ng sapat na lakas para makatakas papuntang hangin bilang singaw ng tubig (water vapor) na hindi nakikita. Ito ang tinatawag na evaporation.", "en": "Puddles dry up because the sun's heat gives water particles enough energy to escape into the air as invisible water vapor. This is called evaporation.", "bis": "Mauga ang mga lapok tungod kay ang init sa adlaw mohatag sa mga partikulo sa tubig og igong kusog aron makaikyas ngadto sa hangin isip dili-makita nga alisngaw sa tubig (water vapor). Kini gitawag og evaporation."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "condensation-cold-glass-g4", "domain": "MATTER", "topic": "why a cold glass sweats", "grades": [4, 5], "terms": ["condensation", "baso", "glass", "pawis ng baso", "hamog", "tubig", "water vapor", "malamig", "cold", "tumutulo"], "fact": {"tl": "'Pumapawis' ang malamig na baso dahil ang singaw ng tubig sa mainit na hangin ay dumidikit sa malamig na ibabaw, nawawalan ng lakas, at nagiging maliliit na patak ng tubig. Ito ang condensation — kabaligtaran ng evaporation.", "en": "A cold glass 'sweats' because water vapor in the warm air touches the cold surface, loses energy, and turns back into tiny drops of liquid water. This is condensation — the opposite of evaporation.", "bis": "'Magsingot' ang bugnaw nga baso tungod kay ang alisngaw sa tubig sa init nga hangin modikit sa bugnaw nga gawas, mawad-an og kusog, ug mahimong gagmayng tulo sa tubig. Kini ang condensation — kabaliktaran sa evaporation."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-wet-clothes-dry-g4", "domain": "MATTER", "topic": "why wet clothes dry", "grades": [3, 4, 5], "terms": ["damit", "clothes", "natutuyo", "mauga", "labada", "init", "hangin", "wind", "evaporation", "araw", "bilad"], "fact": {"tl": "Mas mabilis natutuyo ang basang damit kapag mainit at mahangin dahil pinapabilis ng init ang evaporation, at tinatangay ng hangin ang singaw ng tubig palayo para mas marami pang tubig ang makatakas mula sa tela.", "en": "Wet clothes dry faster on a hot, windy day because heat speeds up evaporation, and wind carries the water vapor away so even more water can escape from the cloth.", "bis": "Mas paspas mauga ang basa nga sanina kon init ug hanginon tungod kay ang init mopaspas sa evaporation, ug ang hangin modala sa alisngaw palayo aron mas daghan pang tubig ang makaikyas gikan sa panapton."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "density-float-sink-g5", "domain": "MATTER", "topic": "density and floating", "grades": [5, 6], "terms": ["density", "densidad", "lutang", "lumulutang", "float", "lumulubog", "sink", "bigat", "timbang", "tubig", "barko", "ship"], "fact": {"tl": "Lumulutang o lumulubog ang isang bagay ayon sa density nito. Kung mas mababa ang density kaysa tubig, lumulutang; kung mas mataas, lumulubog. Mahalaga rin ang hugis — kaya nakakalutang ang bakal na barko dahil maraming hangin sa loob nito.", "en": "Whether something floats or sinks depends on its density. If it is less dense than water it floats; if it is denser it sinks. Shape matters too — a steel ship floats because it is mostly hollow and traps air inside.", "bis": "Molutaw o molugdang ang usa ka butang sumala sa density niini. Kon mas ubos ang density kaysa tubig, molutaw; kon mas taas, molugdang. Importante sab ang porma — molutaw ang puthaw nga barko tungod kay daghan kinig hangin sa sulod."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "viscosity-g5", "domain": "MATTER", "topic": "viscosity", "grades": [5, 6], "terms": ["viscosity", "kapal", "makapal", "thick", "pulot", "honey", "langis", "oil", "dumadaloy", "agos", "flow", "likido"], "fact": {"tl": "Ang viscosity ang sukat kung gaano kabilis o kabagal dumaloy ang isang likido. Ang pulot at langis ay viscous (mabagal dumaloy), samantalang ang tubig ay mabilis. Kadalasan, mas madaling dumaloy ang likido kapag pinainit.", "en": "Viscosity is how slowly or quickly a liquid flows. Honey and oil are viscous (they flow slowly), while water flows fast. Heating a liquid usually makes it flow more easily.", "bis": "Ang viscosity mao ang sukod kon unsa ka hinay o paspas modagayday ang usa ka likido. Ang dugos ug lana viscous (hinay modagayday), samtang ang tubig paspas. Kasagaran, mas sayon modagayday ang likido kon initon."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-cut-apple-browns-g5", "domain": "MATTER", "topic": "why cut fruit turns brown", "grades": [4, 5, 6], "terms": ["mansanas", "apple", "prutas", "fruit", "kayumanggi", "brown", "oxidation", "oksiheno", "oxygen", "kalamansi", "lemon"], "fact": {"tl": "Nagiging kayumanggi ang hiniwang mansanas dahil ang oksiheno sa hangin ay tumutugon sa mga kemikal sa loob ng prutas — isang uri ng oxidation. Pinapabagal ito ng katas ng kalamansi o lemon.", "en": "A cut apple turns brown because oxygen in the air reacts with chemicals inside the fruit — a kind of oxidation. Squeezing on lemon or calamansi juice slows it down.", "bis": "Mahimong brown ang gihiwa nga mansanas tungod kay ang oksiheno sa hangin motubag sa mga kemikal sulod sa prutas — usa ka matang sa oxidation. Mahinay kini kon pug-an og duga sa lemon o kalamansi."}, "source": "AAAS BSL Ch.4; NRC PS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-balloon-shrinks-cold-g5", "domain": "MATTER", "topic": "why balloons shrink in cold", "grades": [5, 6], "terms": ["lobo", "balloon", "lumiliit", "shrink", "lumalaki", "expand", "malamig", "cold", "mainit", "hot", "hangin", "particle"], "fact": {"tl": "Lumiliit ang lobo sa lamig dahil bumabagal ang mga particle ng hangin sa loob at mas kaunting puwang ang kinakailangan nila. Sa init, bumibilis at lumalawak sila, kaya lumalaki ang lobo.", "en": "A balloon shrinks in the cold because the air particles inside slow down and take up less space. In heat they speed up and spread out, so the balloon expands.", "bis": "Mokunhod ang lobo sa katugnaw tungod kay ang mga partikulo sa hangin sa sulod mohinay ug mas gamay nga luna ang ilang gikinahanglan. Sa init, mopaspas ug mokatag sila, maong modako ang lobo."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-popcorn-pops-g4", "domain": "MATTER", "topic": "why popcorn pops", "grades": [3, 4, 5], "terms": ["popcorn", "mais", "corn", "pumuputok", "pop", "singaw", "steam", "init", "tubig", "presyon", "pressure"], "fact": {"tl": "Pumuputok ang popcorn dahil ang kaunting tubig sa loob ng butil ay nagiging singaw kapag pinainit. Lumalakas ang presyon hanggang sumabog ang matigas na balat, at lumalabas ang malambot na loob bilang puti at malutong na popcorn.", "en": "Popcorn pops because the little bit of water trapped inside the kernel turns to steam when heated. Pressure builds until the hard shell bursts open, and the soft inside puffs out as white, crunchy popcorn.", "bis": "Mobuto ang popcorn tungod kay ang gamayng tubig sa sulod sa lugas mahimong alisngaw kon initon. Mosaka ang presyon hangtod mobuto ang gahi nga panit, ug mogawas ang humok nga sulod isip puti ug tagiktik nga popcorn."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-soda-fizzes-g4", "domain": "MATTER", "topic": "why soda fizzes", "grades": [4, 5, 6], "terms": ["soda", "softdrink", "fizz", "bula", "bubble", "carbon dioxide", "gas", "presyon", "pressure", "umaapaw", "kalat"], "fact": {"tl": "Bumubula ang softdrinks dahil may carbon dioxide na gas na natunaw dito sa ilalim ng presyon. Kapag binuksan mo ang bote, bumababa ang presyon kaya tumatakas ang gas bilang maliliit na bula.", "en": "Soda fizzes because carbon-dioxide gas is dissolved in it under pressure. When you open the bottle, the pressure drops, so the gas escapes as tiny bubbles.", "bis": "Mobula ang softdrinks tungod kay adunay carbon-dioxide nga gas nga natunaw niini ubos sa presyon. Kon ablihan nimo ang botelya, mokunhod ang presyon maong moikyas ang gas isip gagmayng bula."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-metals-conduct-electricity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why metals conduct electricity", "grades": [6, 7, 8], "terms": ["metal", "bakal", "kuryente", "electricity", "conductor", "daloy", "electron", "libre", "charge", "kawad", "wire"], "fact": {"tl": "Mahusay magdaloy ng kuryente ang mga metal dahil may mga 'malayang electron' sila na madaling gumalaw. Itong gumagalaw na electron ang nagdadala ng singil ng kuryente sa kabuuan ng metal.", "en": "Metals conduct electricity well because they have free electrons that can move easily. These moving electrons carry the electric charge through the metal.", "bis": "Maayong modaloy og kuryente ang mga metal tungod kay aduna silay 'gawasnong electron' nga sayon molihok. Kining naglihok nga electron maoy nagdala sa kuryente nga charge latas sa metal."}, "source": "NRC PS3.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-hot-air-rises-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why hot air rises", "grades": [4, 5, 6], "terms": ["hangin", "air", "mainit", "hot", "tumataas", "rise", "pumapaitaas", "density", "magaan", "light", "lobo", "convection"], "fact": {"tl": "Tumataas ang mainit na hangin dahil kapag pinainit, kumakalat ang mga particle nito kaya nagiging mas magaan (mababa ang density) kaysa malamig na hangin sa paligid, at lumulutang ito pataas. Ito ang dahilan kung bakit lumilipad ang hot-air balloon.", "en": "Hot air rises because heating makes its particles spread apart, so the hot air becomes lighter (less dense) than the cooler air around it and floats upward. This is why a hot-air balloon flies.", "bis": "Mosaka ang init nga hangin tungod kay kon initon, ang mga partikulo niini mokatag maong mahimong mas gaan (ubos og density) kaysa bugnaw nga hangin sa palibot, ug molutaw kini pataas. Mao kini ngano molupad ang hot-air balloon."}, "source": "NRC PS3.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-goosebumps-g4", "domain": "LIVING_THINGS", "topic": "why we get goosebumps", "grades": [4, 5, 6], "terms": ["goosebumps", "balahibo", "kilabot", "tindig balahibo", "kalamig", "cold", "takot", "fear", "kalamnan", "muscle", "reflex"], "fact": {"tl": "Nagkakaroon tayo ng goosebumps kapag ang maliliit na kalamnan sa balat ay humihila pataas sa ating balahibo. Ito ay lumang reflex mula sa ating mga ninuno na may makapal na balahibo — para magkulong ng init kapag nilalamig o magmukhang mas malaki kapag natatakot.", "en": "We get goosebumps when tiny muscles at the base of our hairs pull them upright. It is an old reflex from ancestors with thick fur — to trap warmth when cold or look bigger when scared.", "bis": "Magkilabot ta kon ang gagmayng kaunoran sa atong panit mobira pataas sa atong balhibo. Karaan kining reflex gikan sa atong mga katigulangan nga baga og balhibo — aron motipig og init kon tugnawon o magpakita nga mas dako kon mahadlok."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-yawn-g3", "domain": "LIVING_THINGS", "topic": "why we yawn", "grades": [3, 4, 5], "terms": ["hikab", "humikab", "yawn", "paghinga", "hininga", "hangin", "utak", "brain", "antok", "cool", "nakakahawa"], "fact": {"tl": "Humihikab tayo para makahinga nang malalim at makakuha ng maraming hangin, na maaaring tumutulong palamigin ang utak at gisingin tayo. Nakakahawa rin ang hikab — humihikab tayo kapag nakita nating may humikab.", "en": "We yawn to take a deep breath of air, which may help cool the brain and make us more alert. Yawns are also contagious — we often yawn just from seeing someone else yawn.", "bis": "Maghuy-ab ta aron makaginhawa og lawom ug makakuha og daghang hangin, nga tingali makatabang sa pagpabugnaw sa utok ug pagpukaw kanato. Makatakod sab ang huy-ab — maghuy-ab ta kon makakita tag laing naghuy-ab."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-stomach-growls-g3", "domain": "LIVING_THINGS", "topic": "why our stomach growls", "grades": [3, 4], "terms": ["tiyan", "stomach", "kumakalam", "kalam", "growl", "gutom", "hungry", "gas", "bituka", "digestion", "tunog"], "fact": {"tl": "Kumakalam ang tiyan kapag gumagalaw ang gas at likido sa loob ng walang lamang sikmura at bituka, at pinipiga sila ng mga kalamnan. Mas malakas ang tunog kapag gutom dahil walang pagkaing humahadlang sa ingay.", "en": "Your stomach growls when gas and fluids move through the empty stomach and intestines while the muscles squeeze them along. It sounds louder when you are hungry because there is no food to muffle the noise.", "bis": "Magkagol ang tiyan kon ang gas ug likido molihok sulod sa walay sulod nga tiyan ug tinai samtang gipuga sila sa kaunoran. Mas kusog ang tingog kon gutom ka tungod kay walay pagkaon nga makapahupay sa saba."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-onions-make-cry-g4", "domain": "LIVING_THINGS", "topic": "why onions make us cry", "grades": [4, 5], "terms": ["sibuyas", "onion", "umiiyak", "luha", "tears", "cry", "mata", "eye", "gas", "asido", "acid", "hiwa"], "fact": {"tl": "Kapag hiniwa ang sibuyas, naglalabas ito ng gas na humahalo sa tubig sa ating mga mata at bumubuo ng banayad na asido. Para hugasan ito palabas, gumagawa ng luha ang mata kaya tayo umiiyak.", "en": "When you cut an onion, it releases a gas that mixes with the water in your eyes to form a mild acid. To wash it away, your eyes make tears — so you cry.", "bis": "Kon hiwaon ang sibuyas, mobuga kini og gas nga mosagol sa tubig sa atong mga mata ug maghimog hinay nga asido. Aron mahugasan kini, ang mata maghimog luha — maong mohilak ta."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-we-get-dizzy-spinning-g4", "domain": "LIVING_THINGS", "topic": "why we get dizzy", "grades": [4, 5, 6], "terms": ["hilo", "nahihilo", "dizzy", "umiikot", "ikot", "spin", "tainga", "inner ear", "balanse", "balance", "likido", "utak"], "fact": {"tl": "Nahihilo tayo pagkatapos umikot dahil may likido sa loob ng tainga na nakakaramdam ng balanse. Kapag huminto tayo, patuloy pa ring gumagalaw ang likido, kaya akala ng utak ay umiikot pa rin tayo.", "en": "We get dizzy after spinning because there is fluid in our inner ear that senses balance. When we stop, the fluid keeps swirling, so the brain thinks we are still spinning.", "bis": "Malipong ta human magtuyok tungod kay adunay likido sulod sa atong dalunggan nga makabati sa balanse. Kon mohunong ta, magpadayon og tuyok ang likido, maong maghunahuna ang utok nga nagtuyok pa ta."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-hiccup-g4", "domain": "LIVING_THINGS", "topic": "why we hiccup", "grades": [4, 5], "terms": ["sinok", "hiccup", "diaphragm", "kalamnan", "muscle", "paghinga", "lalamunan", "throat", "biglang", "hic"], "fact": {"tl": "Nagkakasinok tayo kapag biglang gumalaw nang pasumpong-sumpong ang diaphragm — ang kalamnan sa ilalim ng baga na ginagamit sa paghinga. Sabay nitong nagsasara ang lalamunan, kaya may 'hik' na tunog.", "en": "We hiccup when the diaphragm — the breathing muscle below the lungs — suddenly jerks. At the same moment the throat snaps shut, which makes the 'hic' sound.", "bis": "Magsinok ta kon ang diaphragm — ang kaunoran ubos sa baga nga gamiton sa pagginhawa — kalit molihok nga sumpo-sumpo. Dungan niini mosira ang tutunlan, maong adunay 'hik' nga tingog."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-bread-rises-g5", "domain": "LIVING_THINGS", "topic": "why bread rises", "grades": [5, 6], "terms": ["tinapay", "bread", "umaalsa", "alsa", "rise", "lebadura", "yeast", "fungus", "carbon dioxide", "gas", "bula", "masa"], "fact": {"tl": "Umaalsa ang tinapay dahil ang lebadura (yeast) — isang napakaliit na fungus — ay kumakain ng asukal at naglalabas ng carbon-dioxide na gas. Bumubuo ng mga bula ang gas na ito na nagpapalobo sa masa.", "en": "Bread rises because yeast — a tiny fungus — eats sugar and gives off carbon-dioxide gas. That gas forms bubbles that puff up the dough.", "bis": "Moalsa ang pan tungod kay ang lebadura (yeast) — usa ka gamayng fungus — mokaon og asukar ug mobuga og carbon-dioxide nga gas. Kining gasa maghimog bula nga maghubag sa minasa."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-fruit-ripens-g4", "domain": "LIVING_THINGS", "topic": "why fruit ripens", "grades": [4, 5], "terms": ["prutas", "fruit", "hinog", "nahihinog", "ripen", "ethylene", "gas", "asukal", "sugar", "tamis", "saging", "mansanas"], "fact": {"tl": "Nahihinog ang prutas dahil naglalabas ito ng likas na gas na tinatawag na ethylene. Ginagawang asukal nito ang starch, pinalalambot ang laman, at binabago ang kulay — kaya nagiging matamis ang hinog na prutas.", "en": "Fruit ripens as it gives off a natural gas called ethylene. The gas turns starch into sugar, softens the flesh, and changes the color — which is why ripe fruit tastes sweeter.", "bis": "Mahinog ang prutas samtang mobuga kini og natural nga gas nga gitawag ethylene. Ang gas mohimo sa starch nga asukar, mopahumok sa unod, ug mousab sa kolor — mao nga mas tam-is ang hinog nga prutas."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "el-nino-la-nina-g6", "domain": "EARTH_SPACE", "topic": "el nino and la nina", "grades": [6, 7, 8], "terms": ["el nino", "la nina", "tagtuyot", "drought", "baha", "flood", "tubig-dagat", "Pacific", "ulan", "panahon", "init", "tag-init"], "fact": {"tl": "Ang El Niño ay kapag uminit ang tubig sa Pacific Ocean — kadalasang nagdadala ito ng kakaunting ulan at tagtuyot sa Pilipinas. Ang La Niña naman ay kapag lumamig ang tubig — nagdadala ito ng mas maraming ulan, baha, at bagyo.", "en": "El Niño is when the Pacific Ocean's water warms up — it usually brings less rain and droughts to the Philippines. La Niña is when that water cools — it brings more rain, floods, and typhoons.", "bis": "Ang El Niño mao kon moinit ang tubig sa Pacific Ocean — kasagaran magdala kinig gamayng ulan ug hulaw sa Pilipinas. Ang La Niña mao kon mobugnaw ang tubig — magdala kinig mas daghang ulan, baha, ug bagyo."}, "source": "NRC ESS2.D; PAGASA", "generator": "claude", "reviewed": false},
  {"id": "pacific-ring-of-fire-g6", "domain": "EARTH_SPACE", "topic": "Pacific Ring of Fire", "grades": [6, 7, 8], "terms": ["Ring of Fire", "Pacific", "lindol", "earthquake", "bulkan", "volcano", "tectonic plate", "Pilipinas", "linog", "bukid"], "fact": {"tl": "Ang Pilipinas ay nasa 'Pacific Ring of Fire,' isang hugis-bakal-ng-kabayo na sona sa palibot ng Pacific Ocean kung saan maraming lindol at bulkan. Nangyayari ito dahil dito nagtatagpo at nagkakabanggaan ang mga tectonic plate ng Earth.", "en": "The Philippines sits on the 'Pacific Ring of Fire,' a horseshoe-shaped zone around the Pacific Ocean with many earthquakes and volcanoes. This happens because Earth's tectonic plates meet and grind against each other here.", "bis": "Ang Pilipinas naa sa 'Pacific Ring of Fire,' usa ka porma-kwadradong-kabayo nga sona palibot sa Pacific Ocean diin daghang linog ug bulkan. Mahitabo kini tungod kay dinhi magtagbo ug mag-banggaay ang mga tectonic plate sa Earth."}, "source": "NRC ESS2.B; PHIVOLCS", "generator": "claude", "reviewed": false},
  {"id": "why-ph-many-typhoons-g6", "domain": "EARTH_SPACE", "topic": "why the Philippines has many typhoons", "grades": [5, 6, 7], "terms": ["bagyo", "typhoon", "Pilipinas", "Pacific", "mainit na dagat", "hangin", "tubig-dagat", "unos", "bagyo-bagyo"], "fact": {"tl": "Tumatama sa Pilipinas ang humigit-kumulang 20 bagyo kada taon dahil nasa tabi ito ng mainit na kanlurang Pacific Ocean kung saan madaling bumuo ng bagyo, at ang ihip ng hangin ang nagtutulak ng mga ito papunta sa ating mga isla.", "en": "The Philippines is hit by about 20 typhoons a year because it lies beside the warm western Pacific Ocean where storms easily form, and the prevailing winds steer them toward the islands.", "bis": "Maigo ang Pilipinas og mga 20 ka bagyo matag tuig tungod kay naa kini sa kilid sa init nga kasadpang Pacific Ocean diin sayon maporma ang bagyo, ug ang huros sa hangin maoy nagtukmod niini paingon sa atong mga isla."}, "source": "NRC ESS2.D; PAGASA", "generator": "claude", "reviewed": false},
  {"id": "storm-surge-g6", "domain": "EARTH_SPACE", "topic": "storm surge", "grades": [5, 6, 7], "terms": ["storm surge", "daluyong", "bagyo", "typhoon", "baha", "dagat", "tubig-dagat", "pampang", "Yolanda", "Haiyan", "alon"], "fact": {"tl": "Ang storm surge ay tubig-dagat na itinutulak paahon sa lupa ng malakas na hangin at mababang presyon ng bagyo, na nagdudulot ng delikadong pagbaha sa baybayin. Ito ang dahilan ng maraming namatay noong Bagyong Yolanda (Haiyan).", "en": "A storm surge is sea water pushed onto land by a typhoon's strong winds and low pressure, causing dangerous coastal flooding. It was the main cause of deaths during Typhoon Yolanda (Haiyan).", "bis": "Ang storm surge mao ang tubig-dagat nga gitukmod ngadto sa yuta sa kusog nga hangin ug ubos nga presyon sa bagyo, nga maoy hinungdan sa peligrosong baha sa baybayon. Mao kini ang nag-unang hinungdan sa daghang namatay panahon sa Bagyong Yolanda (Haiyan)."}, "source": "NRC ESS2.D; PAGASA", "generator": "claude", "reviewed": false},
  {"id": "humidity-g5", "domain": "EARTH_SPACE", "topic": "humidity", "grades": [5, 6], "terms": ["humidity", "halumigmig", "alinsangan", "basa ang hangin", "singaw ng tubig", "water vapor", "pawis", "init", "maalinsangan"], "fact": {"tl": "Ang humidity (halumigmig) ay ang dami ng singaw ng tubig sa hangin. Kapag mataas ang humidity, mas maalinsangan ang init dahil mabagal sumingaw ang ating pawis kaya hindi tayo agad lumalamig.", "en": "Humidity is the amount of water vapor in the air. When humidity is high, hot days feel stickier because our sweat evaporates slowly, so we don't cool down as quickly.", "bis": "Ang humidity (kaumog) mao ang gidaghanon sa alisngaw sa tubig sa hangin. Kon taas ang humidity, mas alinsangan ang init tungod kay hinay mosingaw ang atong singot maong dili dayon ta mabugnawan."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "air-pressure-g5", "domain": "EARTH_SPACE", "topic": "air pressure", "grades": [5, 6, 7], "terms": ["air pressure", "presyon ng hangin", "bigat ng hangin", "bundok", "altitude", "panahon", "weather", "hangin", "timbang"], "fact": {"tl": "May timbang ang hangin at idinidiin nito ang lahat ng bagay — ito ang air pressure. Mas mataas ito sa pantay-dagat at mas mababa sa tuktok ng bundok. Ang pagkakaiba ng presyon ang lumilikha ng hangin at nagbabago ng panahon.", "en": "Air has weight and presses on everything around it — that is air pressure. It is higher at sea level and lower at the top of a mountain. Differences in pressure create wind and change the weather.", "bis": "Ang hangin adunay timbang ug moduot kini sa tanang butang — mao kini ang air pressure. Mas taas kini sa lebel sa dagat ug mas ubos sa tumoy sa bukid. Ang kalainan sa presyon maoy maghimog hangin ug mag-usab sa panahon."}, "source": "NRC ESS2.D; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "what-is-hail-g5", "domain": "EARTH_SPACE", "topic": "what is hail", "grades": [4, 5, 6], "terms": ["hail", "yelo", "ulan-yelo", "ulap", "thundercloud", "kidlat", "frozen", "malamig", "bumagsak"], "fact": {"tl": "Ang hail (ulan na yelo) ay mga bilog na yelo na nabubuo kapag ang mga patak ng ulan ay naitataas sa napakalamig na bahagi ng makapal na ulap, doon nagyeyelo at lumalaki bago bumagsak. Bihira ito sa Pilipinas dahil mainit ang klima.", "en": "Hail is balls of ice that form when raindrops are carried up into the very cold parts of a tall thundercloud, freeze, and grow before falling. It is rare in the Philippines because the climate is warm.", "bis": "Ang hail (ulan nga yelo) mao ang lingin nga yelo nga maporma kon ang tulo sa ulan madala pataas sa hilabihan kabugnaw nga bahin sa baga nga panganod, didto mag-yelo ug modako una mahulog. Talagsa ra kini sa Pilipinas tungod kay init ang klima."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "why-moon-has-craters-g5", "domain": "EARTH_SPACE", "topic": "why the moon has craters", "grades": [4, 5, 6], "terms": ["buwan", "moon", "crater", "butas", "meteoroid", "bato sa kalawakan", "banggaan", "hangin", "walang hangin", "kalawakan"], "fact": {"tl": "Puno ng crater (malalaking butas) ang buwan dahil sa mga bato mula sa kalawakan na bumabangga rito. Dahil walang hangin o panahon sa buwan, hindi naaagnas o nawawala ang mga crater kaya nananatili ang mga ito nang napakatagal.", "en": "The moon is covered in craters from space rocks crashing into it. Because the moon has no air or weather, the craters don't erode away, so they stay for a very long time.", "bis": "Puno og crater (dagkong lungag) ang bulan tungod sa mga bato gikan sa kawanangan nga nagbangga niini. Tungod kay walay hangin o panahon sa bulan, dili maguba o mawala ang mga crater maong magpabilin kini og dugay kaayo."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "no-air-in-space-g5", "domain": "EARTH_SPACE", "topic": "why there is no air in space", "grades": [4, 5, 6], "terms": ["kalawakan", "space", "walang hangin", "vacuum", "oxygen", "hininga", "tunog", "sound", "astronaut", "helmet"], "fact": {"tl": "Ang kalawakan ay halos walang laman (vacuum) — wala halos hanging dapat hingahin. Kaya nagsusuot ng espesyal na suit at tangke ng oksiheno ang mga astronaut, at hindi rin naririnig ang tunog sa kalawakan dahil walang hanging dadaluyan nito.", "en": "Space is almost completely empty (a vacuum) — there is almost no air to breathe. That is why astronauts wear special suits with oxygen tanks, and why sound cannot travel in space, since it needs air to move through.", "bis": "Ang kawanangan halos walay sulod (vacuum) — halos walay hangin nga maginhawa. Mao nga ang mga astronaut magsul-ob og espesyal nga suit ug tangke sa oksiheno, ug dili madungog ang tingog sa kawanangan kay nagkinahanglan kini og hangin aron molahos."}, "source": "NRC ESS1.B; PS4.A", "generator": "claude", "reviewed": false},
  {"id": "what-is-shooting-star-g4", "domain": "EARTH_SPACE", "topic": "what is a shooting star", "grades": [3, 4, 5], "terms": ["shooting star", "bulalakaw", "meteor", "bituin", "star", "bato sa kalawakan", "kuskos", "friction", "liwanag", "guhit"], "fact": {"tl": "Ang 'shooting star' (bulalakaw) ay hindi talaga bituin — ito ay maliit na bato mula sa kalawakan na nasusunog dahil sa kuskusan (friction) habang humahagibis ito sa hangin ng Earth, kaya may guhit ng liwanag.", "en": "A 'shooting star' is not really a star — it is a tiny space rock burning up from friction as it races through Earth's air, which makes a bright streak of light.", "bis": "Ang 'shooting star' (bulalakaw) dili gyud bituon — usa kini ka gamayng bato gikan sa kawanangan nga nasunog tungod sa kuskos (friction) samtang naghaguros kini sa hangin sa Earth, maong adunay guhit nga kahayag."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "greenhouse-effect-g6", "domain": "EARTH_SPACE", "topic": "greenhouse effect", "grades": [6, 7, 8], "terms": ["greenhouse effect", "carbon dioxide", "gas", "init", "heat", "kumot", "blanket", "pag-init ng mundo", "global warming", "atmosphere"], "fact": {"tl": "Sa greenhouse effect, ang ilang mga gas tulad ng carbon dioxide ay humuhuli ng bahagi ng init ng araw malapit sa Earth, parang kumot. Kailangan natin ito para mainit-init ang mundo, pero ang sobrang dami ay nagdudulot ng global warming.", "en": "In the greenhouse effect, certain gases like carbon dioxide trap some of the sun's heat near Earth, like a blanket. We need some of it to keep Earth warm, but too much causes global warming.", "bis": "Sa greenhouse effect, ang pipila ka gas sama sa carbon dioxide modakop sa bahin sa init sa adlaw duol sa Earth, sama sa habol. Gikinahanglan nato ang gamay niini aron init ang kalibotan, apan ang sobra maoy hinungdan sa global warming."}, "source": "NRC ESS3.D; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-ocean-has-waves-g4", "domain": "EARTH_SPACE", "topic": "why the ocean has waves", "grades": [3, 4, 5], "terms": ["alon", "wave", "dagat", "ocean", "hangin", "wind", "tubig", "ibabaw", "lakas ng hangin", "pampang"], "fact": {"tl": "Karamihan ng alon sa dagat ay ginagawa ng hangin na humahampas sa ibabaw ng tubig. Kapag mas malakas at mas matagal ang ihip ng hangin, mas malalaki ang alon. Ang malalakas na bagyo kaya gumagawa ng higanteng alon.", "en": "Most ocean waves are made by wind pushing on the surface of the water. The stronger and longer the wind blows, the bigger the waves. That is why strong storms make giant waves.", "bis": "Kadaghanan sa balod sa dagat hinimo sa hangin nga moduot sa ibabaw sa tubig. Kon mas kusog ug mas dugay mohuyop ang hangin, mas dako ang balod. Mao nga ang kusog nga bagyo maghimog higanteng balod."}, "source": "NRC ESS2.C", "generator": "claude", "reviewed": false},
  {"id": "sea-breeze-land-breeze-g5", "domain": "EARTH_SPACE", "topic": "sea breeze and land breeze", "grades": [5, 6], "terms": ["sea breeze", "land breeze", "simoy ng dagat", "hangin", "araw", "gabi", "lupa", "dagat", "mainit", "malamig", "baybayin"], "fact": {"tl": "Sa araw, mas mabilis uminit ang lupa kaysa dagat, kaya umaakyat ang mainit na hangin sa lupa at pumapalit ang malamig na hangin mula sa dagat — sea breeze. Sa gabi, kabaligtaran ito (land breeze) dahil mas mabilis lumamig ang lupa.", "en": "By day, land heats faster than the sea, so warm air rises over the land and cool air rushes in from the sea — a sea breeze. At night it reverses (land breeze) because land cools faster than the sea.", "bis": "Sa adlaw, mas paspas moinit ang yuta kaysa dagat, maong mosaka ang init nga hangin sa yuta ug mopuli ang bugnaw nga hangin gikan sa dagat — sea breeze. Sa gabii kabaliktaran kini (land breeze) tungod kay mas paspas mobugnaw ang yuta."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "why-we-get-fever-g4", "domain": "LIVING_THINGS", "topic": "why we get a fever", "grades": [3, 4, 5], "terms": ["lagnat", "fever", "init ng katawan", "mikrobyo", "germs", "immune system", "depensa", "sakit", "sipon", "laban"], "fact": {"tl": "Ang lagnat ay kapag itinataas ng katawan ang temperatura nito para tulungan labanan ang mga mikrobyo. Senyales ito na gumagana ang immune system, pero ang sobrang taas na lagnat ay kailangang ipakonsulta sa doktor.", "en": "A fever is when the body raises its temperature to help fight off germs. It is a sign the immune system is working, but a very high fever needs to be checked by a doctor.", "bis": "Ang hilanat mao kon ipataas sa lawas ang temperatura niini aron tabangan pakigbatok sa mga mikrobyo. Timailhan kini nga naglihok ang immune system, apan ang taas kaayo nga hilanat kinahanglan ipatan-aw sa doktor."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-cough-sneeze-g3", "domain": "LIVING_THINGS", "topic": "why we cough and sneeze", "grades": [3, 4], "terms": ["ubo", "cough", "bahin", "sneeze", "alikabok", "dust", "mikrobyo", "germs", "ilong", "lalamunan", "reflex", "hangin"], "fact": {"tl": "Ang pag-ubo at pagbahin ay mga reflex na biglang nagpapalabas ng hangin para tanggalin ang mga mikrobyo, alikabok, o sipon sa ilong at lalamunan. Kaya dapat takpan ang bibig para hindi kumalat ang sakit.", "en": "Coughing and sneezing are reflexes that suddenly blast out air to clear germs, dust, or mucus from the nose and throat. That is why you should cover your mouth so illness doesn't spread.", "bis": "Ang pag-ubo ug pagbahaon mga reflex nga kalit mobuga og hangin aron mawala ang mga mikrobyo, abog, o sip-on sa ilong ug tutunlan. Mao nga angay tabunan ang baba aron dili mokatag ang sakit."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-cuts-heal-scabs-g4", "domain": "LIVING_THINGS", "topic": "why cuts heal and form scabs", "grades": [3, 4, 5], "terms": ["sugat", "cut", "wound", "langib", "scab", "dugo", "blood clot", "gumagaling", "heal", "balat", "selula"], "fact": {"tl": "Kapag nasugatan ka, namumuo ang dugo at nagiging langib na nagsasara sa sugat. Sa ilalim nito, gumagawa ng bagong selula ang balat para ayusin ang sarili nito hanggang gumaling.", "en": "When you get a cut, the blood clots into a scab that seals the wound. Underneath, the skin builds new cells to repair itself until it heals.", "bis": "Kon masamad ka, ang dugo mamuo ug mahimong kagid nga mosira sa samad. Sa ilalom niini, ang panit maghimog bag-ong mga selula aron ayohon ang kaugalingon hangtod maayo."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-we-bruise-g4", "domain": "LIVING_THINGS", "topic": "why we bruise", "grades": [4, 5], "terms": ["pasa", "bruise", "dugo", "blood vessel", "ugat", "pagkabangga", "bukol", "kulay", "balat", "nadulas"], "fact": {"tl": "Ang pasa ay pagdurugo sa ilalim ng balat dahil sa mga maliliit na ugat na nasira nang mabangga ka. Nagbabago ang kulay nito (lila, berde, dilaw) habang nililinis ng katawan ang naipong dugo.", "en": "A bruise is bleeding under the skin from tiny blood vessels that broke when you got bumped. Its colors change (purple, green, yellow) as the body cleans up the trapped blood.", "bis": "Ang pangos mao ang pagdugo sa ilalom sa panit gikan sa gagmayng ugat nga nabuak dihang nabangga ka. Mausab ang kolor niini (purpura, berde, dalag) samtang ginalimpyohan sa lawas ang natipon nga dugo."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "baby-and-adult-teeth-g3", "domain": "LIVING_THINGS", "topic": "baby and adult teeth", "grades": [2, 3, 4], "terms": ["ngipin", "teeth", "gatas", "baby teeth", "pangtanda", "adult teeth", "nalalaglag", "20", "32", "permanente"], "fact": {"tl": "Ang mga bata ay may 20 ngipin na gatas na nahuhulog para bigyang-daan ang 32 mas matibay na ngipin ng nakatatanda. Ang mga ngiping pang-adult na ito ay kailangang tumagal habambuhay, kaya mahalagang alagaan.", "en": "Children grow 20 baby teeth that fall out to make room for 32 stronger adult teeth. These adult teeth have to last a lifetime, so it's important to take care of them.", "bis": "Ang mga bata adunay 20 ka ngipon nga gatas nga mangahulog aron hatagag dalan ang 32 ka mas lig-on nga ngipon sa hamtong. Kining mga ngipon sa hamtong kinahanglang molungtad sa tibuok kinabuhi, maong importanteng atimanon."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-we-need-vitamins-g4", "domain": "LIVING_THINGS", "topic": "why we need vitamins", "grades": [3, 4, 5], "terms": ["bitamina", "vitamins", "sustansya", "prutas", "gulay", "araw", "sunlight", "malusog", "vitamin C", "vitamin D", "mata"], "fact": {"tl": "Ang mga bitamina ay sustansyang kailangan sa maliliit na dami para manatiling malusog ang katawan — vitamin C mula sa prutas, vitamin D mula sa sikat ng araw, at vitamin A para sa malinaw na paningin.", "en": "Vitamins are nutrients the body needs in tiny amounts to stay healthy — vitamin C from fruit, vitamin D from sunlight, and vitamin A for clear eyesight.", "bis": "Ang mga bitamina mao ang sustansya nga gikinahanglan sa lawas sa gagmayng gidaghanon aron magpabiling himsog — vitamin C gikan sa prutas, vitamin D gikan sa sidlak sa adlaw, ug vitamin A alang sa tin-aw nga panan-aw."}, "source": "NRC LS1.C; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "germs-and-handwashing-g3", "domain": "LIVING_THINGS", "topic": "germs and handwashing", "grades": [2, 3, 4], "terms": ["mikrobyo", "germs", "bakterya", "virus", "sakit", "paghuhugas", "handwashing", "sabon", "soap", "kamay", "kalinisan"], "fact": {"tl": "Ang mga mikrobyo ay napakaliliit na nabubuhay na bagay na maaaring magpasakit sa atin. Ang paghuhugas ng kamay gamit ang sabon ay nag-aalis sa kanila at pumipigil na kumalat ang sakit.", "en": "Germs are tiny living things that can make us sick. Washing your hands with soap removes them and stops illness from spreading to others.", "bis": "Ang mga mikrobyo gagmayng buhing butang nga makapasakit kanato. Ang paghugas sa kamot gamit ang sabon makakuha kanila ug makapugong sa pagkatap sa sakit ngadto sa uban."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-skin-colors-differ-g5", "domain": "LIVING_THINGS", "topic": "why skin colors differ", "grades": [5, 6], "terms": ["kulay ng balat", "skin color", "melanin", "pigment", "araw", "sunlight", "maitim", "maputi", "proteksyon", "UV"], "fact": {"tl": "Ang kulay ng balat ay nagmumula sa melanin, isang likas na pigment. Mas maraming melanin, mas maitim ang balat at mas malakas ang proteksyon nito laban sa nakakapinsalang sikat ng araw. Lahat ng kulay ng balat ay normal at maganda.", "en": "Skin color comes from melanin, a natural pigment. More melanin means darker skin and stronger protection against the sun's harmful rays. Every skin color is normal and good.", "bis": "Ang kolor sa panit gikan sa melanin, usa ka natural nga pigment. Mas daghang melanin, mas itom ang panit ug mas kusgan ang panalipod batok sa makadaot nga sidlak sa adlaw. Tanang kolor sa panit normal ug nindot."}, "source": "NRC LS3.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-two-eyes-g4", "domain": "LIVING_THINGS", "topic": "why we have two eyes", "grades": [3, 4, 5], "terms": ["dalawang mata", "two eyes", "paningin", "depth", "lalim", "distansya", "utak", "sukat", "salo", "bola"], "fact": {"tl": "Ang pagkakaroon ng dalawang mata na bahagyang magkaiba ang nakikita ay nagbibigay-daan sa utak na husgahan ang lalim at distansya. Ito ang dahilan kaya kaya mong saluhin ang isang bola o malaman kung gaano kalayo ang isang bagay.", "en": "Having two eyes that see slightly different views lets the brain judge depth and distance. That is why you can catch a ball or tell how far away something is.", "bis": "Ang pagbaton og duha ka mata nga gamayng lahi ang makita maghatag og kahigayonan sa utok aron hukman ang giladmon ug gilay-on. Mao nga makasalo ka og bola o makahibalo kon unsa kalayo ang usa ka butang."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-feel-sleepy-g3", "domain": "LIVING_THINGS", "topic": "why we feel sleepy", "grades": [3, 4, 5], "terms": ["antok", "sleepy", "tulog", "sleep", "pagod", "kemikal", "utak", "brain", "gabi", "enerhiya", "puyat"], "fact": {"tl": "Inaantok tayo dahil unti-unting naiipon ang isang kemikal sa utak habang gising tayo sa buong araw. Kapag natulog tayo, inaalis ng katawan ang kemikal na ito at ibinabalik ang ating enerhiya.", "en": "We feel sleepy because a chemical slowly builds up in the brain while we are awake all day. When we sleep, the body clears that chemical away and restores our energy.", "bis": "Katulgon ta tungod kay hinay-hinayng matipon ang usa ka kemikal sa utok samtang nagmata ta sa tibuok adlaw. Kon matulog ta, kuhaon sa lawas kining kemikal ug ibalik ang atong kusog."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-ball-bounces-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why a ball bounces", "grades": [3, 4, 5], "terms": ["bola", "ball", "tumatalbog", "bounce", "enerhiya", "energy", "elastic", "lupa", "tumama", "bumalik", "goma"], "fact": {"tl": "Tumatalbog ang bola dahil kapag tumama ito sa lupa, naiipit at nipis ang hugis nito habang naiimbak ang enerhiya. Pagkatapos, bumabalik ito sa dati nitong hugis at itinutulak ang sarili paahon mula sa lupa.", "en": "A ball bounces because when it hits the ground it squashes, storing energy. Then it springs back to its shape and pushes itself up off the ground.", "bis": "Mounlod ang bola tungod kay kon mosukmag kini sa yuta, mapislat ug manipis ang porma niini samtang gitipigan ang kusog. Unya mobalik kini sa dati nga porma ug motukmod sa kaugalingon pataas gikan sa yuta."}, "source": "NRC PS3.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "action-reaction-rockets-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "action and reaction", "grades": [6, 7, 8], "terms": ["action reaction", "aksyon", "reaksyon", "Newton", "puwersa", "force", "rocket", "kohete", "tulak", "gas", "pataas", "balanse"], "fact": {"tl": "Sa bawat tulak ay may katumbas na tulak pabalik (action–reaction). Ang rocket ay tumataas dahil itinutulak nito ang mainit na gas pababa, at bilang ganti, itinutulak ng gas ang rocket pataas.", "en": "For every push there is an equal push back (action–reaction). A rocket lifts off because it pushes hot gas downward, and in return the gas pushes the rocket upward.", "bis": "Sa matag tukmod adunay katumbas nga tukmod balik (action–reaction). Mosaka ang rocket tungod kay gitukmod niini ang init nga gas paubos, ug isip balos, gitukmod sa gas ang rocket pataas."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-fan-cools-you-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why a fan cools you", "grades": [3, 4, 5], "terms": ["bentilador", "fan", "electric fan", "hangin", "pawis", "sweat", "evaporation", "init", "balat", "lamig", "presko"], "fact": {"tl": "Hindi talaga pinapalamig ng bentilador ang hangin — pinaiihip lang nito ang hangin sa ating balat para mas mabilis sumingaw ang pawis. Kapag sumisingaw ang pawis, dinadala nito ang init palayo, kaya nararamdaman nating presko.", "en": "A fan doesn't actually cool the air — it just blows air across your skin so your sweat evaporates faster. As sweat evaporates, it carries heat away, so you feel cooler.", "bis": "Ang bentilador dili gyud mopabugnaw sa hangin — gihuyop lang niini ang hangin sa atong panit aron mas paspas mosingaw ang singot. Samtang mosingaw ang singot, dad-on niini ang init palayo, maong mobati tag kabugnaw."}, "source": "NRC PS3.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "inertia-seatbelt-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "inertia", "grades": [6, 7, 8], "terms": ["inertia", "sasakyan", "seatbelt", "sinturon", "biglang preno", "galaw", "motion", "Newton", "huminto", "patuloy", "kaligtasan"], "fact": {"tl": "Ang inertia ay ang pagkahilig ng bagay na ipagpatuloy ang kasalukuyang galaw nito. Kapag biglang huminto ang sasakyan, patuloy pa ring gumagalaw pasulong ang katawan mo — kaya pinoprotektahan ka ng seatbelt.", "en": "Inertia is an object's tendency to keep doing what it is already doing. When a car stops suddenly, your body keeps moving forward — which is why a seatbelt protects you.", "bis": "Ang inertia mao ang kiling sa usa ka butang nga ipadayon ang iyang kasamtangang lihok. Kon kalit mohunong ang sakyanan, magpadayon og lihok paabante ang imong lawas — mao nga panalipdan ka sa seatbelt."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-compass-points-north-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why a compass points north", "grades": [5, 6, 7], "terms": ["compass", "kompas", "hilaga", "north", "magnet", "magnetic field", "Earth", "karayom", "direksyon", "timog"], "fact": {"tl": "Ang karayom ng kompas ay isang maliit na magnet na pumapantay sa magnetic field ng Earth. Kaya palaging tumuturo ito sa magnetic north, na tumutulong sa atin malaman ang direksyon.", "en": "A compass needle is a small magnet that lines up with Earth's magnetic field. That is why it always points toward magnetic north, helping us find direction.", "bis": "Ang dagom sa compass usa ka gamayng magnet nga mopahiluna sa magnetic field sa Earth. Mao nga kanunay kining motudlo sa magnetic north, nga makatabang nato mahibal-an ang direksyon."}, "source": "NRC PS2.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "friction-makes-heat-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why friction makes heat", "grades": [3, 4, 5], "terms": ["friction", "kuskos", "init", "heat", "kamay", "kiskis", "galaw", "energy", "mainit", "palamig"], "fact": {"tl": "Ang pagkuskos ng dalawang bagay ay gumagawa ng init dahil ginagawang init ng friction ang enerhiya ng galaw. Kaya kapag kinuskos mo ang iyong mga kamay, umiinit ang mga ito.", "en": "Rubbing two things together makes heat because friction turns the energy of motion into heat. That is why rubbing your hands together warms them up.", "bis": "Ang pagkuskos sa duha ka butang maghimog init tungod kay ang friction mohimo sa kusog sa lihok ngadto sa init. Mao nga kon imong kuskuson ang imong mga kamot, moinit kini."}, "source": "NRC PS3.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "how-flashlight-works-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "how a flashlight works", "grades": [3, 4, 5], "terms": ["flashlight", "flashlight", "baterya", "battery", "ilaw", "liwanag", "light", "kuryente", "kawad", "bombilya", "LED", "switch"], "fact": {"tl": "Gumagana ang flashlight kapag itinutulak ng baterya ang kuryente sa pamamagitan ng kawad papunta sa bombilya o LED, na nagpapalit ng enerhiya ng kuryente tungo sa liwanag. Bumubukas ang daloy kapag pinindot ang switch.", "en": "A flashlight works when a battery pushes electricity through a wire to a bulb or LED, which turns the electric energy into light. Pressing the switch completes the circuit so the current can flow.", "bis": "Molihok ang flashlight kon ang baterya motukmod sa kuryente agi sa kawad ngadto sa bombilya o LED, nga mohimo sa kusog sa kuryente ngadto sa kahayag. Ang pagpislit sa switch mohingpit sa sirkito aron modaloy ang kuryente."}, "source": "NRC PS3.B; PS4.A", "generator": "claude", "reviewed": false},
  {"id": "why-siren-changes-pitch-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why a siren changes pitch", "grades": [6, 7, 8], "terms": ["sirena", "siren", "Doppler", "tunog", "sound", "pitch", "ambulansya", "papalapit", "papalayo", "tono", "alon ng tunog"], "fact": {"tl": "Ang sirena ng dumadaang ambulansya ay tunog na mas mataas habang papalapit ito at mas mababa kapag papalayo na. Ito ay dahil nagsisiksikan ang mga alon ng tunog kapag palapit at humihiwalay kapag palayo — ang tinatawag na Doppler effect.", "en": "A passing ambulance siren sounds higher as it comes toward you and lower as it moves away. This is because the sound waves bunch up when approaching and spread out when leaving — the Doppler effect.", "bis": "Ang sirena sa naglabay nga ambulansya mas taas og tono samtang nagpaduol kini ug mas ubos kon nagpalayo na. Tungod kini kay magtapok ang mga balod sa tingog kon nagpaduol ug magkatag kon nagpalayo — ang gitawag nga Doppler effect."}, "source": "NRC PS4.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "pulley-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pulley", "grades": [4, 5, 6], "terms": ["pulley", "kalo", "gulong", "lubid", "rope", "simple machine", "pagbuhat", "lift", "mabigat", "poso", "bandila", "direksyon"], "fact": {"tl": "Ang pulley ay isang gulong na may lubid na nagbabago ng direksyon ng iyong hila. Sa halip na buhatin pataas ang mabigat na bagay, makakahila ka pababa — kaya mas madali, tulad sa pagtaas ng bandila o pagsalok ng tubig sa poso.", "en": "A pulley is a wheel with a rope that changes the direction of your pull. Instead of lifting a heavy load up, you can pull down — which is easier, like raising a flag or drawing water from a well.", "bis": "Ang pulley usa ka ligid nga adunay pisi nga mag-usab sa direksyon sa imong bira. Imbis nga alsahon pataas ang bug-at nga butang, makabira ka paubos — mas sayon, sama sa pagpataas sa bandera o pagkalos og tubig sa atabay."}, "source": "NRC PS3.C; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "why-knife-cuts-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why a sharp knife cuts", "grades": [4, 5, 6], "terms": ["kutsilyo", "knife", "matalas", "sharp", "presyon", "pressure", "gilid", "manipis", "puwersa", "hiwa", "talim"], "fact": {"tl": "Mahusay humiwa ang matalas na kutsilyo dahil ang manipis na talim nito ay nagpapatong ng buong puwersa mo sa napakaliit na lugar, kaya napakataas ng presyon na pumuputol sa bagay. Mahirap humiwa ang mapurol dahil kumakalat ang puwersa.", "en": "A sharp knife cuts well because its thin edge puts all of your push onto a very tiny area, making very high pressure that slices through. A dull knife cuts poorly because the force spreads out.", "bis": "Maayong mohiwa ang hait nga kutsilyo tungod kay ang nipis nga sulab niini magbutang sa tibuok nimong kusog sa gamay kaayong dapit, maong taas kaayo ang presyon nga moputol sa butang. Lisod mohiwa ang habol kay magkatag ang kusog."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-float-easier-seawater-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why we float easier in seawater", "grades": [5, 6], "terms": ["lumulutang", "float", "dagat", "seawater", "tubig-alat", "asin", "salt", "density", "buoyancy", "swimming pool", "tabang"], "fact": {"tl": "Mas madali kang lumutang sa dagat kaysa sa swimming pool dahil mas siksik (mas mataas ang density) ang tubig-alat kaysa tubig-tabang. Dahil dito, mas malakas ang pagtulak ng dagat paahon sa iyong katawan.", "en": "You float more easily in the sea than in a swimming pool because salt water is denser than fresh water. Because of that, the sea pushes up on your body more strongly.", "bis": "Mas sayon kang molutaw sa dagat kaysa swimming pool tungod kay mas baga (mas taas og density) ang tubig-asin kaysa tab-ang nga tubig. Tungod niini, mas kusgan ang pagtukmod sa dagat pataas sa imong lawas."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "crystals-g6", "domain": "MATTER", "topic": "crystals", "grades": [5, 6, 7], "terms": ["kristal", "crystal", "asin", "salt", "asukal", "sugar", "particle", "hugis", "pattern", "tubig", "sumingaw", "yelo"], "fact": {"tl": "Ang mga kristal tulad ng asin at asukal ay nabubuo kapag ang kanilang mga particle ay nag-aayos sa maayos at paulit-ulit na pattern habang lumalamig ang likido o sumisingaw ang tubig. Kaya may tiyak na hugis ang mga butil ng asin.", "en": "Crystals like salt and sugar form when their particles arrange into a neat, repeating pattern as a liquid cools or water evaporates. That is why grains of salt have a regular shape.", "bis": "Ang mga kristal sama sa asin ug asukar maporma kon ang ilang mga partikulo mag-areglo sa hapsay ug balik-balik nga pattern samtang mobugnaw ang likido o mosingaw ang tubig. Mao nga ang lugas sa asin adunay piho nga porma."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-metals-shiny-g5", "domain": "MATTER", "topic": "why metals are shiny", "grades": [4, 5, 6], "terms": ["metal", "bakal", "makintab", "shiny", "kinang", "liwanag", "light", "salamin", "electron", "ibabaw", "reflection"], "fact": {"tl": "Makintab ang mga metal dahil ang makinis nilang ibabaw at malalayang electron ay pantay na sumasalamin ng liwanag pabalik. Kaya kumikinang ang pinakintab na metal tulad ng salamin.", "en": "Metals look shiny because their smooth surfaces and free electrons reflect light back evenly. That is why polished metal gleams almost like a mirror.", "bis": "Makintab ang mga metal tungod kay ang hapsay nilang nawong ug gawasnong electron pantay nga mosalamin sa kahayag pabalik. Mao nga mosidlak ang gipasinaw nga metal sama sa salamin."}, "source": "NRC PS4.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-ice-cream-melts-g3", "domain": "MATTER", "topic": "why ice cream melts", "grades": [2, 3, 4], "terms": ["sorbetes", "ice cream", "natutunaw", "melt", "init", "heat", "yelo", "likido", "malamig", "particle", "araw"], "fact": {"tl": "Natutunaw ang sorbetes kapag ang init mula sa mainit na hangin ay nagbibigay sa nagyelong particle nito ng sapat na enerhiya para muling maging likido. Kaya mabilis itong natutunaw sa labas kapag mainit.", "en": "Ice cream melts when heat from the warm air gives its frozen particles enough energy to turn back into liquid. That is why it melts fast outdoors on a hot day.", "bis": "Matunaw ang sorbetes kon ang init gikan sa init nga hangin mohatag sa mga nagyelo niini nga partikulo og igong kusog aron mahimo na usab likido. Mao nga paspas kini matunaw sa gawas kon init."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "baking-soda-vinegar-fizz-g4", "domain": "MATTER", "topic": "baking soda and vinegar reaction", "grades": [4, 5, 6], "terms": ["baking soda", "suka", "vinegar", "bula", "fizz", "carbon dioxide", "gas", "chemical reaction", "reaksyon", "bulkan", "eksperimento"], "fact": {"tl": "Kapag pinaghalo ang baking soda at suka, bumubula ito dahil nagreaksyon sila at bumubuo ng carbon-dioxide na gas — isang chemical change. Ito ang dahilan kung bakit 'sumasabog' ang laruang bulkan sa science fair.", "en": "When you mix baking soda and vinegar, it bubbles because they react to form carbon-dioxide gas — a chemical change. This is why a toy volcano 'erupts' at a science fair.", "bis": "Kon sagolon ang baking soda ug suka, mobula kini tungod kay nag-react sila ug naghimog carbon-dioxide nga gas — usa ka chemical change. Mao kini ngano 'mobuto' ang dulaang bulkan sa science fair."}, "source": "NRC PS1.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-we-have-fingerprints-g4", "domain": "LIVING_THINGS", "topic": "why we have fingerprints", "grades": [3, 4, 5], "terms": ["fingerprint", "bakas ng daliri", "daliri", "finger", "hawak", "grip", "balat", "ridge", "kakaiba", "unique", "kambal"], "fact": {"tl": "Ang mga fingerprint ay maliliit na guhit (ridges) sa ating mga daliri na tumutulong sa paghawak ng bagay at pagdama ng texture. Natatangi ang pattern ng bawat tao — magkaiba pa rin kahit kambal.", "en": "Fingerprints are tiny ridges on our fingers that help us grip things and feel textures. Everyone's pattern is unique — even identical twins have different fingerprints.", "bis": "Ang mga fingerprint mao ang gagmayng linya (ridges) sa atong tudlo nga makatabang sa pagkupot og butang ug pagbati sa texture. Talagsaon ang pattern sa matag tawo — lahi gihapon bisan kambal."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-two-ears-g4", "domain": "LIVING_THINGS", "topic": "why we have two ears", "grades": [3, 4, 5], "terms": ["dalawang tainga", "two ears", "tunog", "sound", "direksyon", "pandinig", "hearing", "utak", "saan", "galing"], "fact": {"tl": "Ang dalawang tainga ay nagpapahintulot sa utak na ikumpara kung kailan umabot ang tunog sa bawat gilid. Kaya nalalaman natin kung saang direksyon nanggaling ang isang tunog.", "en": "Two ears let the brain compare when a sound reaches each side. That is how we can tell which direction a sound came from.", "bis": "Ang duha ka dalunggan magtugot sa utok nga itandi kanus-a moabot ang tingog sa matag kilid. Mao nga mahibal-an nato kon asa nga direksyon naggikan ang usa ka tingog."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "animal-hibernation-g4", "domain": "LIVING_THINGS", "topic": "animal hibernation", "grades": [4, 5], "terms": ["hibernation", "hibernate", "hayop", "animal", "tulog", "taglamig", "winter", "enerhiya", "pagkain", "oso", "bear"], "fact": {"tl": "Ang ilang hayop ay nag-hi-hibernate — mahimbing na natutulog sa buong malamig na taglamig — para makatipid ng enerhiya kapag kakaunti ang pagkain. Bumabagal ang kanilang tibok ng puso at paghinga.", "en": "Some animals hibernate — sleep deeply through the cold winter — to save energy when food is scarce. Their heartbeat and breathing slow way down.", "bis": "Ang pipila ka hayop mag-hibernate — mahinanok nga matulog sa tibuok bugnaw nga tingtugnaw — aron makatipig og kusog kon nihit ang pagkaon. Mohinay pag-ayo ang ilang pitik sa kasingkasing ug pagginhawa."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "animal-migration-g4", "domain": "LIVING_THINGS", "topic": "animal migration", "grades": [4, 5], "terms": ["migration", "paglipat", "hayop", "animal", "ibon", "bird", "panahon", "season", "pagkain", "init", "langaw? no", "lumilipad"], "fact": {"tl": "Maraming hayop ang naglalakbay nang malayo ayon sa panahon (migration) para maghanap ng pagkain, init, o lugar na mapag-aalagaan ng anak — tulad ng mga ibong lumilipad patungong mainit na lugar kapag malamig.", "en": "Many animals migrate — travel long distances with the seasons — to find food, warmth, or places to raise their young, like birds flying to warmer places when it gets cold.", "bis": "Daghang hayop ang mobiyahe og layo sumala sa panahon (migration) aron mangita og pagkaon, kainit, o dapit nga kapadakuan sa ilang anak — sama sa mga langgam nga molupad sa mas init nga dapit kon mobugnaw."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "pollination-g4", "domain": "LIVING_THINGS", "topic": "pollination", "grades": [3, 4, 5], "terms": ["pollination", "polinasyon", "bulaklak", "flower", "pollen", "bubuyog", "bee", "paruparo", "butterfly", "buto", "seed", "prutas"], "fact": {"tl": "Ang pollination ay kapag ang pollen (alikabok ng bulaklak) ay nalilipat mula sa isang bulaklak patungo sa iba — kadalasan sa tulong ng bubuyog, paruparo, o hangin. Dahil dito, nakakagawa ang halaman ng buto at prutas.", "en": "Pollination is when pollen moves from one flower to another — often carried by bees, butterflies, or wind. This lets plants make seeds and fruit.", "bis": "Ang pollination mao kon ang pollen (abog sa bulak) mabalhin gikan sa usa ka bulak ngadto sa lain — kasagaran dala sa buyog, alibangbang, o hangin. Tungod niini, makahimo ang tanom og liso ug prutas."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "how-bees-make-honey-g4", "domain": "LIVING_THINGS", "topic": "how bees make honey", "grades": [3, 4, 5], "terms": ["bubuyog", "bee", "pulot", "honey", "nectar", "bulaklak", "pakpak", "bahay-pukyutan", "hive", "matamis", "tinipon"], "fact": {"tl": "Kinukuha ng bubuyog ang matamis na nectar mula sa mga bulaklak, iniimbak ito, at pinapaypayan gamit ang kanilang pakpak para palaputin tungo sa pulot. Ito ang pagkain ng kolonya sa bahay-pukyutan.", "en": "Bees collect sweet nectar from flowers, store it, and fan it with their wings to thicken it into honey. The honey feeds the whole colony in the hive.", "bis": "Manguha ang mga buyog og tam-is nga nectar gikan sa mga bulak, tipigan kini, ug paypayan gamit ang ilang pako aron pabagaon ngadto sa dugos. Ang dugos maoy pagkaon sa tibuok kolonya sa balay-putyukan."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-food-spoils-mold-g4", "domain": "LIVING_THINGS", "topic": "why food spoils", "grades": [3, 4, 5], "terms": ["pagkain", "food", "nabubulok", "spoil", "amag", "mold", "bakterya", "bacteria", "ref", "fridge", "malamig", "sira"], "fact": {"tl": "Nabubulok ang pagkain kapag dumadami ang bakterya at amag dito. Pinapabagal sila ng paglalagay ng pagkain sa malamig o tuyong lugar — kaya natin ginagamit ang ref para mas matagal bago masira ang pagkain.", "en": "Food spoils when bacteria and mold grow on it. Keeping food cold or dry slows them down — that is why we use the fridge to make food last longer before it goes bad.", "bis": "Madunot ang pagkaon kon modaghan ang bakterya ug agup-op niini. Mahinay sila kon ibutang ang pagkaon sa bugnaw o uga nga dapit — mao nga mogamit tag ref aron mas dugay molungtad ang pagkaon."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "butterfly-metamorphosis-g3", "domain": "LIVING_THINGS", "topic": "butterfly metamorphosis", "grades": [2, 3, 4], "terms": ["paruparo", "butterfly", "metamorphosis", "itlog", "egg", "higad", "caterpillar", "uod", "pupa", "chrysalis", "yugto"], "fact": {"tl": "Nagbabago ang anyo ng paruparo sa apat na yugto: itlog, higad (caterpillar), pupa (chrysalis), at saka ang ganap na paruparo. Ito ay tinatawag na complete metamorphosis.", "en": "A butterfly changes form in four stages: egg, caterpillar (larva), pupa (chrysalis), and finally the adult butterfly. This is called complete metamorphosis.", "bis": "Mausab ang porma sa alibangbang sa upat ka hugna: itlog, ulod (caterpillar), pupa (chrysalis), ug sa kataposan ang hingkod nga alibangbang. Gitawag kini nga complete metamorphosis."}, "source": "NRC LS1.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-dogs-pant-g3", "domain": "LIVING_THINGS", "topic": "why dogs pant", "grades": [2, 3, 4], "terms": ["aso", "dog", "humihingal", "pant", "dila", "tongue", "init", "palamig", "cool", "pawis", "sweat", "hininga"], "fact": {"tl": "Humihingal ang aso para magpalamig dahil hindi sila pinagpapawisan sa balat tulad natin. Sa paghingal, sumisingaw ang tubig mula sa kanilang dila at bibig, na nag-aalis ng init sa katawan.", "en": "Dogs pant to cool down because they can't sweat through their skin like we do. Panting evaporates water from their tongue and mouth, which carries heat away.", "bis": "Maghangak ang iro aron mobugnaw tungod kay dili sila singot sa panit sama nato. Sa paghangak, mosingaw ang tubig gikan sa ilang dila ug baba, nga magkuha sa init sa lawas."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "nocturnal-animals-g3", "domain": "LIVING_THINGS", "topic": "nocturnal animals", "grades": [2, 3, 4], "terms": ["nocturnal", "gabi", "night", "hayop", "animal", "kuwago", "owl", "paniki", "bat", "dilim", "gising", "natutulog", "mata"], "fact": {"tl": "Ang mga nocturnal na hayop tulad ng kuwago at paniki ay gising at aktibo sa gabi, at natutulog kapag araw. May espesyal silang mga mata o pandinig para makahanap ng pagkain sa dilim.", "en": "Nocturnal animals like owls and bats are awake and active at night and sleep during the day. They have special eyes or hearing to find food in the dark.", "bis": "Ang mga nocturnal nga hayop sama sa ngiwngiw ug kabog nagmata ug aktibo sa gabii, ug matulog kon adlaw. Aduna silay espesyal nga mata o pandungog aron makapangita og pagkaon sa kangitngit."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "what-is-aurora-g6", "domain": "EARTH_SPACE", "topic": "what is an aurora", "grades": [6, 7, 8], "terms": ["aurora", "northern lights", "ilaw sa langit", "particle", "araw", "sun", "gas", "atmosphere", "poste", "pole", "kulay", "liwanag"], "fact": {"tl": "Ang aurora (northern o southern lights) ay kumikinang na kulay sa langit na nabubuo kapag ang mga particle mula sa araw ay tumatama sa mga gas sa itaas ng atmosphere malapit sa mga poste ng Earth. Hindi ito nakikita sa Pilipinas dahil malayo tayo sa poste.", "en": "An aurora (northern or southern lights) is glowing color in the sky that forms when particles from the sun hit gases high in the atmosphere near Earth's poles. It is not seen in the Philippines because we are far from the poles.", "bis": "Ang aurora (northern o southern lights) mao ang nagsidlak nga kolor sa langit nga maporma kon ang mga partikulo gikan sa adlaw mosukmag sa mga gas sa taas sa atmospera duol sa mga poste sa Earth. Dili kini makita sa Pilipinas kay layo ta sa poste."}, "source": "NRC ESS1.B; PS3.D", "generator": "claude", "reviewed": false},
  {"id": "ozone-layer-g6", "domain": "EARTH_SPACE", "topic": "the ozone layer", "grades": [6, 7, 8], "terms": ["ozone", "ozone layer", "atmosphere", "UV", "ultraviolet", "araw", "sun", "proteksyon", "sanhi", "radiation", "kalanguban"], "fact": {"tl": "Ang ozone layer ay bahagi ng atmosphere na sumasalag sa atin mula sa karamihan ng nakakapinsalang ultraviolet (UV) na sinag ng araw. Kung wala ito, mas mapanganib ang sikat ng araw sa balat at mata.", "en": "The ozone layer is a part of the atmosphere that shields us from most of the sun's harmful ultraviolet (UV) rays. Without it, sunlight would be far more dangerous to our skin and eyes.", "bis": "Ang ozone layer kabahin sa atmospera nga manalipod kanato gikan sa kadaghanan sa makadaot nga ultraviolet (UV) nga sidlak sa adlaw. Kon wala kini, mas peligroso ang sidlak sa adlaw sa atong panit ug mata."}, "source": "NRC ESS3.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-leap-year-g5", "domain": "EARTH_SPACE", "topic": "why we have leap years", "grades": [5, 6], "terms": ["leap year", "bisiyesto", "Pebrero", "February", "365", "366", "araw", "day", "kalendaryo", "Earth", "orbit", "umiikot"], "fact": {"tl": "Ang isang taon ay talagang halos 365 at kalahating-kapat na araw — ang oras na iniikot ng Earth sa araw. Kaya tuwing 4 na taon, nagdadagdag tayo ng isang araw (Pebrero 29) para manatiling tama ang kalendaryo. Ito ang leap year (bisiyesto).", "en": "A year is really about 365 and a quarter days — the time Earth takes to orbit the sun. So every 4 years we add one extra day (February 29) to keep the calendar lined up. That is a leap year.", "bis": "Ang usa ka tuig halos 365 ug tunga-kuwarto ka adlaw — ang panahon nga libuton sa Earth ang adlaw. Maong matag 4 ka tuig, magdugang tag usa ka adlaw (Pebrero 29) aron magpabiling sakto ang kalendaryo. Mao kini ang leap year."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "what-is-light-year-g6", "domain": "EARTH_SPACE", "topic": "what is a light-year", "grades": [6, 7, 8], "terms": ["light-year", "light year", "liwanag", "light", "layo", "distance", "bituin", "star", "kalawakan", "taon", "year", "sukat"], "fact": {"tl": "Ang light-year ay ang layong nilalakbay ng liwanag sa loob ng isang taon — humigit-kumulang 9.5 trilyong kilometro. Ginagamit ito para sukatin ang napakalalayong distansya sa pagitan ng mga bituin.", "en": "A light-year is the distance light travels in one year — about 9.5 trillion kilometers. It is used to measure the huge distances between the stars.", "bis": "Ang light-year mao ang gilay-on nga gibiyahe sa kahayag sulod sa usa ka tuig — mga 9.5 ka trilyong kilometro. Gigamit kini aron sukoron ang dagkong gilay-on tali sa mga bituon."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-bubbles-pop-g3", "domain": "MATTER", "topic": "why bubbles pop", "grades": [2, 3, 4], "terms": ["bula", "bubble", "pumuputok", "pop", "sabon", "pelikula", "film", "tubig", "tuyo", "hawak", "nasira"], "fact": {"tl": "Pumuputok ang bula kapag natutuyo ang manipis na pelikula ng tubig-sabon nito o kapag may humawak dito, kaya nasisira ang ibabaw at tumatakas ang hangin sa loob.", "en": "A bubble pops when its thin film of soapy water dries out or something touches it, breaking the surface so the air inside escapes.", "bis": "Mobuto ang bula kon mauga ang nipis nga pelikula sa tubig-sabon niini o kon adunay mohikap niini, maong maguba ang gawas ug moikyas ang hangin sa sulod."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-lemon-sour-acid-g4", "domain": "MATTER", "topic": "why citrus tastes sour", "grades": [3, 4, 5], "terms": ["maasim", "sour", "kalamansi", "lemon", "dayap", "asido", "acid", "citric", "dila", "tongue", "prutas", "suka"], "fact": {"tl": "Maasim ang lasa ng kalamansi at lemon dahil naglalaman sila ng banayad na asido (citric acid). Nararamdaman ng ating dila ang mga asido bilang maasim na lasa.", "en": "Lemons and calamansi taste sour because they contain a mild acid (citric acid). Our tongue senses acids as a sour taste.", "bis": "Aslom ang lasa sa kalamansi ug lemon tungod kay aduna silay hinay nga asido (citric acid). Mabati sa atong dila ang mga asido isip aslom nga lami."}, "source": "NRC PS1.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-glass-brittle-g5", "domain": "MATTER", "topic": "why glass is brittle", "grades": [5, 6], "terms": ["salamin", "glass", "babasagin", "brittle", "basag", "shatter", "particle", "matigas", "rigid", "lamat", "crack"], "fact": {"tl": "Madaling mabasag ang salamin dahil ang mga particle nito ay nakatali sa matigas na pattern na hindi makadausdos. Kapag tinamaan nang malakas, mabilis kumakalat ang lamat hanggang mabasag ito.", "en": "Glass shatters easily because its particles are locked in a rigid pattern with no way to slide past each other. A sharp blow makes cracks spread fast until it breaks.", "bis": "Sayon mabuak ang salamin tungod kay ang mga partikulo niini gigapos sa gahi nga pattern nga dili makadalin-as. Kon igoon og kusog, paspas mokatag ang liki hangtod mabuak kini."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-rubber-stretches-g4", "domain": "MATTER", "topic": "why rubber stretches", "grades": [4, 5, 6], "terms": ["goma", "rubber", "umuunat", "stretch", "elastic", "bumabalik", "molekula", "kulot", "coiled", "banat", "laso"], "fact": {"tl": "Umuunat ang goma at bumabalik sa dati nitong hugis dahil ang mahahaba at nakakulot nitong molekula ay naghahat kapag hinila at nagkukulot muli kapag binitawan. Kaya nababanat ang rubber band.", "en": "Rubber stretches and snaps back because its long, coiled molecules uncoil when you pull them and recoil when you let go. That is why a rubber band springs back.", "bis": "Mounat ang goma ug mobalik sa dati niini nga porma tungod kay ang taas ug kulot niini nga molekula mobukhad kon birahon ug mokulot pag-usab kon buhian. Mao nga mobalik ang rubber band."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "alloys-g6", "domain": "MATTER", "topic": "alloys", "grades": [6, 7, 8], "terms": ["alloy", "haluang metal", "halo", "metal", "bakal", "steel", "asero", "tanso", "bronze", "carbon", "matibay", "matigas"], "fact": {"tl": "Ang alloy ay haluan ng mga metal (o metal at ibang sangkap) na ginagawang mas matibay o mas kapaki-pakinabang. Halimbawa: ang asero (steel) ay bakal na may halong carbon, at ang bronze ay tanso na may halong lata.", "en": "An alloy is a mix of metals (or a metal plus another element) made stronger or more useful. For example, steel is iron mixed with carbon, and bronze is copper mixed with tin.", "bis": "Ang alloy mao ang sagol nga mga metal (o metal ug laing sangkap) nga gihimong mas lig-on o mas mapuslanon. Pananglitan: ang asero (steel) puthaw nga gisagolan og carbon, ug ang bronze tumbaga nga gisagolan og lata."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "plasma-fourth-state-g7", "domain": "MATTER", "topic": "plasma the fourth state", "grades": [7, 8, 9, 10], "terms": ["plasma", "ikaapat na estado", "fourth state", "solid", "liquid", "gas", "araw", "sun", "kidlat", "lightning", "neon", "mainit"], "fact": {"tl": "Bukod sa solid, liquid, at gas, may ikaapat na estado ng bagay na tinatawag na plasma — napakainit na nagliliwanag na gas na may mga particle na may kuryente. Matatagpuan ito sa araw, sa kidlat, at sa mga neon na ilaw.", "en": "Besides solid, liquid, and gas, there is a fourth state of matter called plasma — super-hot, glowing gas made of charged particles. It is found in the sun, in lightning, and in neon lights.", "bis": "Gawas sa solid, liquid, ug gas, adunay ikaupat nga kahimtang sa butang nga gitawag plasma — init kaayo, nagsidlak nga gas nga adunay mga partikulo nga may kuryente. Makita kini sa adlaw, sa kilat, ug sa mga neon nga suga."}, "source": "NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "gas-fills-container-g4", "domain": "MATTER", "topic": "why gas fills its container", "grades": [4, 5, 6], "terms": ["gas", "hangin", "lalagyan", "container", "kumakalat", "spread", "particle", "malayang gumalaw", "hugis", "lobo", "puno"], "fact": {"tl": "Kumakalat ang gas para punuin nang buo ang anumang lalagyan dahil malayang gumagalaw ang mga particle nito sa lahat ng direksyon — hindi tulad ng likido o solid na may tiyak na hugis o dami.", "en": "A gas spreads out to completely fill any container because its particles move freely in all directions — unlike a liquid or solid, which keep a set volume or shape.", "bis": "Mokatag ang gas aron pun-on sa hingpit ang bisan unsang sudlanan tungod kay ang mga partikulo niini gawasnong molihok sa tanang direksyon — dili sama sa likido o solid nga adunay piho nga gidaghanon o porma."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "saturated-solution-g6", "domain": "MATTER", "topic": "saturated solution", "grades": [6, 7, 8], "terms": ["saturated", "saturated solution", "natunaw", "dissolve", "asukal", "sugar", "asin", "salt", "tubig", "limitado", "init", "sobra"], "fact": {"tl": "May hangganan kung gaano karaming asukal o asin ang kayang tunawin ng tubig. Kapag hindi na ito makakatunaw pa, tinatawag itong saturated, at ang sobrang solid ay naiipon sa ilalim. Mas marami itong matutunaw kapag pinainit ang tubig.", "en": "Water can only dissolve so much sugar or salt. Once it cannot hold any more, it is 'saturated', and extra solid just settles at the bottom. Warming the water lets it dissolve more.", "bis": "Adunay kinutoban kon pila ka asukar o asin ang matunaw sa tubig. Kon dili na kini makatunaw pa, gitawag kining saturated, ug ang sobrang solid molingkod sa ilalom. Mas daghan kini matunaw kon initon ang tubig."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "air-resistance-parachute-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "air resistance and parachutes", "grades": [4, 5, 6], "terms": ["air resistance", "hangin", "parachute", "payong-hangin", "bagsak", "fall", "mabagal", "lapad", "drag", "puwersa", "pababa"], "fact": {"tl": "Pinapabagal ng parachute ang pagbagsak dahil ang malapad nitong ibabaw ay tumutulak laban sa maraming hangin (air resistance), kaya marahan itong nakakahawak sa taong nahuhulog.", "en": "A parachute slows a fall because its wide surface pushes against a lot of air (air resistance), gently holding back the falling person.", "bis": "Gipahinay sa parachute ang pagkahulog tungod kay ang lapad niini nga nawong moduot batok sa daghang hangin (air resistance), maong hinay nga makapugong sa nahulog nga tawo."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-feather-falls-slower-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why a feather falls slower than a stone", "grades": [4, 5, 6], "terms": ["balahibo", "feather", "bato", "stone", "bumabagsak", "fall", "air resistance", "hangin", "buwan", "moon", "gravity", "magaan"], "fact": {"tl": "Mas mabagal bumagsak ang balahibo kaysa bato dahil mas malakas itinutulak ng air resistance ang magaan at malapad nitong hugis. Kung walang hangin tulad sa buwan, sabay silang babagsak dahil pareho ang hila ng gravity.", "en": "A feather falls slower than a stone because air resistance pushes harder on its light, wide shape. Without air, like on the moon, they would fall together because gravity pulls on both the same.", "bis": "Mas hinay mahulog ang balhibo kaysa bato tungod kay mas kusog ituklod sa air resistance ang gaan ug lapad niini nga porma. Kon walay hangin sama sa bulan, dungan silang mahulog kay parehas ang bira sa gravity."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "inclined-plane-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "inclined plane", "grades": [4, 5, 6], "terms": ["inclined plane", "rampa", "ramp", "dalisdis", "simple machine", "puwersa", "force", "pataas", "mabigat", "push", "madali"], "fact": {"tl": "Ang rampa (inclined plane) ay nagbibigay-daan na itaas ang mabigat na bagay gamit ang mas kaunting puwersa sa pamamagitan ng pagtulak dito paahon sa banayad na dalisdis, sa halip na buhatin ito nang diretso pataas.", "en": "A ramp (inclined plane) lets you raise a heavy object with less force by pushing it up a gentle slope, instead of lifting it straight up.", "bis": "Ang rampa (inclined plane) magtugot nimo nga ipataas ang bug-at nga butang gamit ang mas gamayng kusog pinaagi sa pagtulod niini pasaka sa hinay nga bakilid, imbis nga alsahon kini deretso pataas."}, "source": "NRC PS3.C; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "centripetal-force-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "centripetal force", "grades": [6, 7, 8], "terms": ["centripetal", "puwersa", "force", "umiikot", "circle", "balde", "bucket", "tubig", "gitna", "center", "hindi natatapon", "ikot"], "fact": {"tl": "Kapag iniikot mo ang isang balde ng tubig sa bilog, may puwersang humihila dito papunta sa gitna (centripetal force) na pumipigil sa tubig na matapon — kahit pabaligtad ang balde sa itaas.", "en": "When you swing a bucket of water in a circle, a force pulls it toward the center (centripetal force) and keeps the water from spilling — even when the bucket is upside down at the top.", "bis": "Kon tuyokon nimo ang usa ka balde nga tubig sa lingin, adunay kusog nga mobira niini paingon sa tunga (centripetal force) nga makapugong sa tubig sa pag-awas — bisan kon balitad ang balde sa taas."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "lightning-rod-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lightning rod", "grades": [5, 6, 7], "terms": ["lightning rod", "kidlat", "lightning", "bubong", "metal", "kuryente", "grounding", "lupa", "gusali", "building", "proteksyon", "daan"], "fact": {"tl": "Ang lightning rod ay nagbibigay sa kidlat ng ligtas na daanang metal patungo diretso sa lupa, kaya naiingatan ang mga gusali mula sa sunog at pinsala kapag tinamaan ng kidlat.", "en": "A lightning rod gives lightning a safe metal path straight down into the ground, protecting buildings from fire and damage when lightning strikes.", "bis": "Ang lightning rod maghatag sa kilat og luwas nga agianan nga metal deretso ngadto sa yuta, maong mapanalipdan ang mga building gikan sa sunog ug kadaot kon maigo sa kilat."}, "source": "NRC PS3.A; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "why-we-blink-g3", "domain": "LIVING_THINGS", "topic": "why we blink", "grades": [2, 3, 4], "terms": ["kurap", "blink", "mata", "eye", "luha", "tears", "alikabok", "dust", "basa", "proteksyon", "liwanag", "reflex"], "fact": {"tl": "Kumukurap tayo para ikalat ang luha na naglilinis at nagpapabasa sa ating mga mata, at para protektahan ang mga ito mula sa alikabok at sobrang liwanag.", "en": "We blink to spread tears that clean and moisten our eyes, and to protect them from dust and bright light.", "bis": "Mokurap ta aron ikatag ang luha nga maglimpyo ug magpabasa sa atong mga mata, ug aron panalipdan kini gikan sa abog ug sobra nga kahayag."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-have-eyebrows-g4", "domain": "LIVING_THINGS", "topic": "why we have eyebrows and eyelashes", "grades": [3, 4, 5], "terms": ["kilay", "eyebrow", "pilikmata", "eyelash", "pawis", "sweat", "ulan", "alikabok", "dust", "mata", "proteksyon"], "fact": {"tl": "Ang kilay ay pumipigil sa pawis at ulan na dumiretso sa mga mata, at ang pilikmata naman ay sumasalo sa alikabok bago ito makapasok sa mata. Pareho silang nagpoprotekta sa ating paningin.", "en": "Eyebrows keep sweat and rain from running into our eyes, and eyelashes catch dust before it gets in. Both help protect our eyesight.", "bis": "Ang kilay magpugong sa singot ug ulan nga modiretso sa mga mata, ug ang pilok mosalo sa abog una kini makasulod sa mata. Pareho silang manalipod sa atong panan-aw."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "white-blood-cells-g5", "domain": "LIVING_THINGS", "topic": "white blood cells", "grades": [5, 6, 7], "terms": ["white blood cells", "puting selula ng dugo", "dugo", "blood", "mikrobyo", "germs", "immune", "depensa", "sundalo", "sakit", "laban"], "fact": {"tl": "Ang white blood cells (puting selula ng dugo) ay ang maliliit na tagapagtanggol ng katawan — hinahanap at nilalabanan nila ang mga mikrobyong nakakapasok sa atin, parang mga sundalo laban sa sakit.", "en": "White blood cells are the body's tiny defenders — they hunt down and destroy germs that get inside us, like soldiers fighting off illness.", "bis": "Ang white blood cells (puti nga selula sa dugo) mao ang gagmayng tigpanalipod sa lawas — pangitaon ug pakigbatokan nila ang mga mikrobyo nga makasulod kanato, sama sa mga sundalo batok sa sakit."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "coral-reefs-g5", "domain": "LIVING_THINGS", "topic": "coral reefs", "grades": [4, 5, 6], "terms": ["coral reef", "bahura", "coral", "polyp", "hayop", "dagat", "isda", "fish", "Pilipinas", "tirahan", "biodiversity", "tubig-dagat"], "fact": {"tl": "Ang coral reef (bahura) ay itinatayo ng napakaliliit na hayop na tinatawag na coral polyp. Tirahan ito ng napakaraming nilalang sa dagat, at ang Pilipinas ay may ilan sa pinakamayamang reef sa buong mundo.", "en": "Coral reefs are built by tiny animals called coral polyps. They shelter a huge variety of sea creatures, and the Philippines has some of the richest reefs in the whole world.", "bis": "Ang coral reef (bahura) gitukod sa gagmay kaayong hayop nga gitawag coral polyp. Puy-anan kini sa daghan kaayong binuhat sa dagat, ug ang Pilipinas adunay pipila sa kinaadunahang reef sa tibuok kalibotan."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "mangroves-g5", "domain": "LIVING_THINGS", "topic": "mangroves", "grades": [4, 5, 6], "terms": ["bakawan", "bakhaw", "mangrove", "puno", "tree", "baybayin", "coast", "ugat", "roots", "alon", "bagyo", "isda", "alimango", "proteksyon"], "fact": {"tl": "Ang bakawan (mangrove) ay mga punong tumutubo sa maalat na tubig sa baybayin. Ang magkakabuhol nitong ugat ay nagpoprotekta sa dalampasigan laban sa alon at bagyo, at tirahan ng mga isda at alimango.", "en": "Mangroves are trees that grow in salty coastal water. Their tangled roots protect the shore from waves and storms, and they are home to fish and crabs.", "bis": "Ang bakhaw (mangrove) mao ang mga kahoy nga motubo sa parat nga tubig sa baybayon. Ang nagkalambigit niini nga gamot manalipod sa baybay batok sa balod ug bagyo, ug puy-anan kini sa mga isda ug alimango."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-moon-visible-daytime-g4", "domain": "EARTH_SPACE", "topic": "why the moon is sometimes visible in daytime", "grades": [3, 4, 5], "terms": ["buwan", "moon", "araw", "daytime", "umaga", "tanghali", "langit", "liwanag", "anggulo", "nakikita", "gabi"], "fact": {"tl": "Nakikita minsan ang buwan kahit araw dahil sapat itong maliwanag at nasa tamang anggulo sa langit. Hindi lang ito lumalabas sa gabi — kasing-dalas itong nasa langit sa araw, pero mas mapansin sa madilim na gabi.", "en": "The moon is sometimes visible in daytime because it is bright enough and in the right spot in the sky. It is not only out at night — it is up in the day about as often, just harder to notice against the bright sky.", "bis": "Makita usahay ang bulan bisan adlaw tungod kay igo kini kahayag ug naa sa saktong anggulo sa langit. Dili lang kini mogawas sa gabii — sama ka subsob nga naa kini sa langit sa adlaw, apan lisod mamatikdan batok sa hayag nga langit."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "star-vs-planet-g5", "domain": "EARTH_SPACE", "topic": "difference between stars and planets", "grades": [4, 5, 6], "terms": ["bituin", "star", "planeta", "planet", "sariling liwanag", "reflect", "kumikislap", "twinkle", "araw", "langit", "ningning"], "fact": {"tl": "Ang mga bituin ay gumagawa ng sariling liwanag sa pamamagitan ng pagliyab, samantalang ang mga planeta ay hindi — nagniningning lang sila dahil sinasalamin nila ang liwanag ng araw. Kumikislap ang bituin; matatag namang nagniningning ang planeta.", "en": "Stars make their own light by burning, while planets do not — they only shine by reflecting the sun's light. Stars twinkle, but planets shine with a steady light.", "bis": "Ang mga bituon maghimo og kaugalingong kahayag pinaagi sa pagdilaab, samtang ang mga planeta dili — mosidlak lang sila kay ilang gisalamin ang kahayag sa adlaw. Mokislap ang bituon; lig-on nga mosidlak ang planeta."}, "source": "NRC ESS1.A; ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-venus-hottest-g6", "domain": "EARTH_SPACE", "topic": "why Venus is the hottest planet", "grades": [6, 7, 8], "terms": ["Venus", "pinakamainit", "hottest", "planeta", "planet", "carbon dioxide", "greenhouse", "init", "atmosphere", "Mercury", "makapal"], "fact": {"tl": "Ang Venus ang pinakamainit na planeta — mas mainit pa kaysa Mercury na mas malapit sa araw — dahil ang makapal nitong hanging carbon dioxide ay humuhuli ng init sa sobrang lakas na greenhouse effect.", "en": "Venus is the hottest planet — even hotter than Mercury, which is closer to the sun — because its thick carbon-dioxide air traps heat in a runaway greenhouse effect.", "bis": "Ang Venus mao ang kinainitang planeta — mas init pa kaysa Mercury nga mas duol sa adlaw — tungod kay ang baga niini nga hangin nga carbon dioxide modakop sa init sa hilabihan kakusog nga greenhouse effect."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-pluto-not-planet-g6", "domain": "EARTH_SPACE", "topic": "why Pluto is not a planet", "grades": [5, 6, 7], "terms": ["Pluto", "dwarf planet", "planeta", "planet", "maliit", "orbit", "walo", "eight", "solar system", "kahulugan", "2006"], "fact": {"tl": "Ang Pluto ngayon ay tinatawag na 'dwarf planet' (planetang duwende) dahil maliit ito at hindi pa nalilinis ang ibang bagay sa daanan nito sa paligid ng araw, hindi tulad ng walong pangunahing planeta. Kaya walo na lang ang opisyal na planeta.", "en": "Pluto is now called a 'dwarf planet' because it is small and has not cleared other objects out of its orbit around the sun, unlike the eight main planets. That is why there are now only eight official planets.", "bis": "Ang Pluto karon gitawag nga 'dwarf planet' tungod kay gamay kini ug wala pa nahawan ang ubang butang sa iyang agianan palibot sa adlaw, dili sama sa walo ka nag-unang planeta. Mao nga walo na lang ang opisyal nga planeta."}, "source": "NRC ESS1.B; IAU 2006", "generator": "claude", "reviewed": false},
  {"id": "soil-layers-g5", "domain": "EARTH_SPACE", "topic": "soil layers", "grades": [4, 5, 6], "terms": ["lupa", "soil", "layer", "saplot", "topsoil", "subsoil", "bato", "sustansya", "halaman", "durog", "nabubulok", "ugat"], "fact": {"tl": "May mga patong (layer) ang lupa: ang topsoil sa itaas ay mayaman sa sustansya at dito tumutubo ang halaman, sumunod ang subsoil, at sa ilalim ay bato. Dahan-dahang nabubuo ang lupa habang nadudurog ang bato at nabubulok ang mga patay na bagay.", "en": "Soil has layers: the nutrient-rich topsoil on top where plants grow, then subsoil, then rock below. Soil forms slowly as rock breaks down and dead things decay.", "bis": "Ang yuta adunay mga sapaw (layer): ang topsoil sa ibabaw nga dato sa sustansya diin motubo ang tanom, sunod ang subsoil, ug sa ilalom ang bato. Hinay-hinay maporma ang yuta samtang madugmok ang bato ug madunot ang patay nga mga butang."}, "source": "NRC ESS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "volcano-types-g6", "domain": "EARTH_SPACE", "topic": "types of volcanoes", "grades": [5, 6, 7], "terms": ["bulkan", "volcano", "uri", "types", "lava", "abo", "ash", "pagsabog", "eruption", "Mayon", "Pinatubo", "kono", "cone"], "fact": {"tl": "Magkakaiba ang mga bulkan: ang iba ay marahang pumuputok na may malabnaw na lava, at ang iba naman ay malakas sumabog na may malapot na lava at abo. Ang Bulkang Mayon sa Pilipinas ay tanyag sa perpekto nitong hugis-kono.", "en": "Volcanoes differ: some erupt gently with runny lava, while others explode violently with thick lava and ash. The Philippines' Mayon Volcano is famous for its near-perfect cone shape.", "bis": "Magkalainlain ang mga bulkan: ang uban hinay mobuto nga adunay malabnaw nga lava, ug ang uban kusog mobuto nga adunay baga nga lava ug abo. Ang Bulkang Mayon sa Pilipinas inila sa hapit-hingpit niini nga porma-kono."}, "source": "NRC ESS2.B; PHIVOLCS", "generator": "claude", "reviewed": false},
];
